// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст подячний «Слава Богу за все»","e":"Akathist of Thanksgiving “Glory to God for All Things”","secs":[{"h":"Кондак 1","ps":["Нетлінний Царю віків, що тримаєш у правиці Своїй усі шляхи людського життя силою спасенного Промислу Твого, дякуємо Тобі за всі відомі й потаємні благодіяння Твої, за земне життя і за небесні радощі Царства Твого майбутнього. Простягай нам і надалі милості Твої, коли співаємо:","Слава Тобі, Боже, навіки."]},{"h":"Ікос 1","ps":["Слабкою безпорадною дитиною народився я у світ, але Твій Ангел простер світлі крила, оберігаючи мою колиску. Відтоді любов Твоя сяє на всіх моїх шляхах, дивовижно ведучи мене до світла вічности. Славні щедрі дари Твого Промислу явлені від першого дня й донині. Дякую й волаю разом з усіма, що пізнали Тебе:","Слава Тобі, що покликав мене до життя;","Слава Тобі, що явив мені красу всесвіту.","Слава Тобі, що розкрив переді мною небо й землю, як вічну книгу мудрости;","Слава Твоїй вічності серед світу тлінного.","Слава Тобі за таємні й явні милості Твої;","Слава Тобі за кожен подих моїх грудей.","Слава Тобі за кожен крок життя, за кожну мить радости.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 2","ps":["Господи, як добре гостювати в Тебе: пахучий вітер, гори, простягнені в небо, води, як безмежні дзеркала, що відбивають золото променів і легкість хмар. Уся природа таємниче шепоче, уся сповнена ніжности, і птахи, і звірі носять печать Твоєї любови. Благословенна мати земля з її швидкоплинною красою, що пробуджує тугу за вічною вітчизною, де в нетлінній красі лунає: Алилуя!"]},{"h":"Ікос 2","ps":["Ти ввів мене в це життя, як у чарівний рай. Ми побачили небо, як глибоку синю чашу, в блакиті якої дзвенять птахи, ми почули заспокійливий шум лісу й солодкозвучну музику вод, ми їли пахучі й солодкі плоди й духмяний мед. Добре в Тебе на землі, радісно в Тебе в гостях:","Слава Тобі за свято життя;","Слава Тобі за пахощі конвалій і троянд.","Слава Тобі за солодку розмаїтість ягід і плодів;","Слава Тобі за діамантове сяйво ранкової роси.","Слава Тобі за усмішку світлого пробудження;","Слава Тобі за земне життя, провісницю небесного.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 3","ps":["Силою Святого Духа має кожна квітка тихе віяння аромату, ніжність забарвлення, красу Великого в малому. Хвала і честь Богові Животворящому, що простягає луги, як квітучий килим, вінчає поля золотом колосся й блакиттю волошок, а душі — радістю споглядання. Веселіться й співайте Йому: Алилуя!"]},{"h":"Ікос 3","ps":["Який Ти прекрасний у святковості весни, коли воскресає все створіння і тисячею ладів радісно взиває до Тебе: Ти джерело життя, Ти переможець смерти. У світлі місяця й пісні соловейка стоять долини й ліси у своїх сніжно-білих весільних уборах. Уся земля — наречена Твоя, вона чекає нетлінного Нареченого. Якщо Ти траву так зодягаєш, то як же нас перетворишиш у майбутньому віці воскресіння, як просвітяться наші тіла, як засяють наші душі!","Слава Тобі, що вивів із темряви землі різноманітні барви, смак і аромат;","Слава Тобі за привітність і ласку всієї природи.","Слава Тобі за те, що Ти оточив нас тисячами Своїх створінь;","Слава Тобі за глибину Твого розуму, відбиту в усьому світі.","Слава Тобі, з благоговінням цілую сліди Твоєї незримої стопи;","Слава Тобі, що запалив попереду яскраве світло вічного життя.","Слава Тобі за надію безсмертної досконалої нетлінної краси.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 4","ps":["Як Ти солодиш тих, що думають про Тебе, як животворно живе Слово Твоє, м’якша за єлей і солодша за стільники розмова з Тобою. Окрилює й оживляє молитва до Тебе; яким трепетом тоді наповнюється серце і якою величною та розумною стає тоді природа й усе життя! Де немає Тебе — там порожнеча. Де Ти — там багатство душі, там живим потоком виливається пісня: Алилуя!"]},{"h":"Ікос 4","ps":["Коли на землю сходить присмерк, коли настає спокій нічного сну й тиша згасаючого дня, я бачу Твій чертог у образі сяючих палат і хмарних сіней зорі. Вогонь і багрянець, золото й блакить пророчо говорять про невимовну красу Твоїх осель, урочисто кличуть: ходімо до Отця!","Слава Тобі в тиху годину вечора;","Слава Тобі, що розлив над світом великий спокій.","Слава Тобі за прощальний промінь сонця, що заходить;","Слава Тобі за спочинок благодатного сну.","Слава Тобі за Твою благість у темряві, коли далеко весь світ;","Слава Тобі за зворушені молитви розчуленої душі.","Слава Тобі за обіцяне пробудження до радости вічного невечірнього дня.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 5","ps":["Не страшні бурі життєві тому, в кого в серці сяє світильник Твого вогню. Навкруги негода й темрява, жах і завивання вітру. А в душі в нього тиша й світло: там Христос! І серце співає: Алилуя!"]},{"h":"Ікос 5","ps":["Я бачу небо Твоє, що сяє зорями. О, який Ти багатий, скільки в Тебе світла! Променями далеких світил дивиться на мене вічність, я такий малий і нікчемний, але зі мною Господь, Його люблюча правиця береже мене.","Слава Тобі за невпинні турботи про мене;","Слава Тобі за промислительні зустрічі з людьми.","Слава Тобі за любов рідних, за відданість друзів;","Слава Тобі за лагідність тварин, що служать мені.","Слава Тобі за світлі хвилини мого життя;","Слава Тобі за ясні радощі серця.","Слава Тобі за щастя жити, рухатися й споглядати.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 6","ps":["Який Ти великий і близький у могутньому русі грози, як видна Твоя потужна рука у вигинах осяйних блискавиць, дивна велич Твоя. Голос Господній над полями й у шумі лісів, голос Господній у народженні громів і дощів, голос Господній над водами багатьма. Хвала Тобі в гуркоті вогнедишних гір. Ти стрясаєш землю, як одяг. Ти здіймаєш до неба хвилі морські. Хвала Тобі, що смиряєш людську гординю, видобуваючи покаянний вигук: Алилуя!"]},{"h":"Ікос 6","ps":["Як блискавка, коли освітить чертоги бенкету, то після неї жалюгідними здаються вогні світильників. Так Ти раптово спалахував у душі моїй під час найсильніших радощів життя. І після блискавичного світла Твого якими безбарвними, темними, примарними здавалися вони. Душа гналася за Тобою.","Слава Тобі, межа й край найвищої людської мрії;","Слава Тобі за наше невгамовне прагнення спілкування з Богом.","Слава Тобі, що вдихнув у нас незадоволеність земним;","Слава Тобі, що огорнув нас найтоншими променями Твоїми.","Слава Тобі, що зруйнував владу духів темряви, прирік на знищення всяке зло;","Слава Тобі за відкриття Твої, за щастя відчувати Тебе й жити з Тобою.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 7","ps":["У дивному поєднанні звуків чується поклик Твій. Ти відкриваєш нам передпокої майбутнього раю в мелодійності співу, у гармонійних тонах, у висоті музичних барв, у блиску мистецької творчости. Усе істинно прекрасне могутнім закликом несе душу до Тебе, спонукає захоплено співати: Алилуя!"]},{"h":"Ікос 7","ps":["Навіюванням Святого Духа Ти осяваєш думку митців, поетів, геніїв науки. Силою Надсвідомости вони пророчо осягають закони Твої, розкриваючи нам безодню творчої премудрости Твоєї. Їхні діла мимоволі говорять про Тебе: о, який Ти великий у Своїх творіннях, о, який Ти великий у людині.","Слава Тобі, що явив незбагненну силу в законах всесвіту;","Слава Тобі, уся природа сповнена законів Твого буття.","Слава Тобі за все відкрите нам з благости Твоєї;","Слава Тобі за те, що Ти приховав з премудрости Твоєї.","Слава Тобі за геніальність людського розуму;","Слава Тобі за животворну силу праці.","Слава Тобі за вогненні язики натхнення.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 8","ps":["Який Ти близький у дні хвороби, Ти Сам відвідуєш недужих, Ти Сам схиляєшся над ложем страждальця, і серце розмовляє з Тобою. Ти миром осяваєш душу під час тяжких скорбот і страждань, Ти посилаєш несподівану допомогу. Ти втішаєш, Ти — любов, що випробовує й спасає, Тобі співаємо пісню: Алилуя!"]},{"h":"Ікос 8","ps":["Коли я в дитинстві вперше свідомо покликав Тебе, Ти виконав мою молитву, і душу осінив благоговійний спокій. Тоді я зрозумів, що Ти — благий і блаженні ті, що вдаються до Тебе. Я став закликати Тебе знову й знову, і нині волаю:","Слава Тобі, що виконуєш на добре бажання мої;","Слава Тобі, що пильнуєш наді мною день і ніч.","Слава Тобі, що лікуєш скорботи й втрати цілющим плином часу;","Слава Тобі, з Тобою немає безнадійних втрат, Ти даруєш усім вічне життя.","Слава Тобі, Ти обдарував безсмертям усе добре й високе. Ти обіцяв бажану зустріч зі спочилими.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 9","ps":["Чому вся природа таємниче всміхається в дні свят? Чому тоді в серці розливається дивна легкість, ні з чим земним не зрівняна, і саме повітря вівтаря й храму стає світлоносним? Це віяння благодати Твоєї, це відблиск Фаворського світла; тоді і небо, і земля хвалебно співають: Алилуя!"]},{"h":"Ікос 9","ps":["Коли Ти надихав мене служити ближнім, а душу осявав смиренням, то один із незліченних променів Твоїх падав на моє серце, і воно ставало світлоносним, як залізо у вогні. Я бачив Твій таємничий, невловимий Лик.","Слава Тобі, що перетворив наше життя ділами добра;","Слава Тобі, що закарбував невимовну солодкість у кожній заповіді Твоїй.","Слава Тобі, що явно перебуваєш там, де пахне милосердя;","Слава Тобі, що посилаєш нам невдачі й скорботи, щоб ми були чуйними до страждань інших.","Слава Тобі, що поклав велику нагороду в самоцінності добра;","Слава Тобі, що приймаєш високий порив.","Слава Тобі, що возвеличив любов понад усе земне й небесне.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 10","ps":["Розбите на порох не можна відновити, але Ти відновлюєш тих, у кого стліла совість. Ти повертаєш давню красу душам, що безнадійно її втратили. З Тобою немає непоправного. Ти весь — любов. Ти — Творець і Відновитель. Тебе хвалимо піснею: Алилуя!"]},{"h":"Ікос 10","ps":["Боже мій, Ти знаєш падіння гордого ангела — денниці, спаси мене силою благодаті, не дай мені відпасти від Тебе, не дай засумніватися в Тобі. Загостри слух мій, щоб у всі хвилини життя я чув Твій таємничий голос і взивав до Тебе, всюдисущого:","Слава Тобі за промислительний збіг обставин;","Слава Тобі за благодатні передчуття.","Слава Тобі за одкровення у сні й наяву.","Слава Тобі, що руйнуєш наші марні задуми;","Слава Тобі, що стражданнями отверезюєш нас від чаду пристрастей.","Слава Тобі, що спасенно смиряєш гординю серця.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 11","ps":["Крізь крижаний ланцюг віків я відчуваю тепло Твого Божественного подиху, чую струмування крови. Ти вже близько, частина часу розвіялася. Я бачу Твій Хрест — він заради мене. Мій дух у порсі перед Хрестом: тут торжество любови й спасіння, тут не вгаває навіки хвала: Алилуя!"]},{"h":"Ікос 11","ps":["Блаженний, хто скуштує вечерю в Царстві Твоєму, але Ти вже на землі причастив мене цього блаженства. Скільки разів Ти простягав мені Божественною правицею Тіло і Кров Твою, і я, многогрішний, приймав цю святиню і відчував Твою любов, невимовну, надприродну.","Слава Тобі за незбагненну животворну силу благодаті;","Слава Тобі, що спорудив Церкву Твою, як тиху пристань змученому світові.","Слава Тобі, що відроджуєш нас животворними водами хрещення;","Слава Тобі, Ти повертаєш тим, що каються, чистоту непорочних лілій.","Слава Тобі, невичерпна безодне прощення;","Слава Тобі за чашу життя, за хліб вічної радости.","Слава Тобі, що підніс нас на небо.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 12","ps":["Я бачив багато разів відблиск слави Твоєї на обличчях померлих. Якою неземною красою й радістю світилися вони, які повітряні, нематеріальні були їхні риси, це було торжество досягнутого щастя, спокою; мовчанням вони кликали до Тебе. У годину кончини моєї просвіти й мою душу, що взиває: Алилуя!"]},{"h":"Ікос 12","ps":["Що моя хвала перед Тобою! Я не чув співу Херувимів, це доля високих душ, але я знаю, як хвалить Тебе природа. Я споглядав узимку, як у місячній тиші вся земля тихо молилася Тобі, зодягнена в білу ризу, сяючи діамантами снігу. Я бачив, як радувалося про Тебе сонце, що сходить, і хори птахів гриміли славу. Я чув, як таємниче про Тебе шумить ліс, співають вітри, дзюркочуть води, як проповідують про Тебе хори світил своїм стрункім рухом у безконечному просторі. Що моя хвала! Природа слухняна, а я — ні, поки живу, я бачу любов Твою, хочу дякувати, молитися й взивати:","Слава Тобі, що показав нам світло;","Слава Тобі, що полюбив нас любов’ю глибокою, незмірною, божественною.","Слава Тобі, що осіняєш нас світлом, сонмами ангелів і святих;","Слава Тобі, Всесвятий Отче, що заповів нам Твоє Царство.","Слава Тобі, Спасителю Сину, що відкрив нам шлях до спасіння;","Слава Тобі, Душе Святий, животворяще сонце майбутнього віку.","Слава Тобі за все, о Троїце Божественна, Всеблага.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 13","ps":["О Всеблага і Животворяща Троїце, прийми подяку за всі милості Твої й вчини нас гідними Твоїх благодіянь, щоб, примноживши вручені нам таланти, ми ввійшли в вічну радість Господа свого з переможною хвалою: Алилуя! Алилуя! Алилуя!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Слабкою безпорадною дитиною народився я у світ, але Твій Ангел простер світлі крила, оберігаючи мою колиску. Відтоді любов Твоя сяє на всіх моїх шляхах, дивовижно ведучи мене до світла вічности. Славні щедрі дари Твого Промислу явлені від першого дня й донині. Дякую й волаю разом з усіма, що пізнали Тебе:","Слава Тобі, що покликав мене до життя;","Слава Тобі, що явив мені красу всесвіту.","Слава Тобі, що розкрив переді мною небо й землю, як вічну книгу мудрости;","Слава Твоїй вічності серед світу тлінного.","Слава Тобі за таємні й явні милості Твої;","Слава Тобі за кожен подих моїх грудей.","Слава Тобі за кожен крок життя, за кожну мить радости.","Слава Тобі, Боже, навіки."]},{"h":"Кондак 1","ps":["Нетлінний Царю віків, що тримаєш у правиці Своїй усі шляхи людського життя силою спасенного Промислу Твого, дякуємо Тобі за всі відомі й потаємні благодіяння Твої, за земне життя і за небесні радощі Царства Твого майбутнього. Простягай нам і надалі милості Твої, коли співаємо:","Слава Тобі, Боже, навіки."]},{"h":"Молитва","ps":["Го́споди Ісу́се Христе́ Бо́же наш, Бо́же вся́каго милосе́рдія і щедро́т, Єго́же ми́лость безмі́рна, і человіколю́бія неізслі́димая пучи́на! Ко Твоєму́ вели́честву припа́дающе, со стра́хом і тре́петом, я́ко раби́ недосто́йнії, благодаре́ніє Твоєму́ благоутро́бію о Твої́х благодія́ніїх, на рабі́х Твої́х би́вших, ни́ні смире́нно принося́ще, я́ко Го́спода, Влади́ку і Благоді́теля сла́вим, хва́лим, поє́м і велича́єм і, припа́дающе, па́ки благодари́м, Твоє́ безмі́рноє і неізрече́нноє милосе́рдіє смире́нно моля́щеє. Да я́коже ни́ні моле́ніє рабо́в Твої́х прия́ти і ми́лостивно іспо́лнити сподо́бил єси́, і во пре́дняя в Твоє́й і і́скренняго любві́ і во всіх доброді́теліх преспіва́ющих Твоя́ благодія́нія всіх ві́рних Твої́х получи́ти, Це́рков Твою́ Святу́ю і град сей от вся́каго зла́го обстоя́нія избавля́я, і мир і безм'яте́жіє тім да́руя, Тебі́ со Безнача́льним Твої́м Отце́м, і Пресвяти́м, і Благи́м, і Єдиносу́щним Твої́м Ду́хом, во Єди́нім Существі́ сла́вимому Бо́гу, всегда́ благодаре́ніє приноси́ти і преблага́я глаго́лати і воспі́ти сподо́биши: Сла́ва Тебі́, Бо́гу, Благода́телю на́шему, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Благода́рні су́ще недосто́йнії раби́ Твої́, Го́споди, / о Твої́х вели́ких благодія́ніях на нас би́вших, / сла́в'яще Тя хва́лим, благослови́м, благодари́м, поє́м і велича́єм Твоє́ благоутро́біє, / і ра́бськи любо́вію вопіє́м Ті: / Благоді́телю Спа́се наш, сла́ва Тебі́."]},{"h":"Кондак, глас 3","ps":["Твої́х благодія́ній і даро́в ту́не, / я́ко раби́ непотре́бнії, сподо́бльшеся, Влади́ко, / к Тебі́ усе́рдно притека́юще, / благодаре́ніє по си́лі прино́сим, / і Тебі́ я́ко благоді́теля і Творця́ сла́в'яще, вопіє́м: // сла́ва Тебі́, Бо́же Всеще́дрий."]}],"notes":[]},{"u":"Акафіст святому Ангелу Хоронителю","e":"Akathist to the Holy Guardian Angel","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Го́спода Бо́га на хране́ніє ду́ші моєя́ і тілесе́, святи́й А́нгеле, похва́льная ті воспіва́ти дерза́ю, недосто́йний раб твой; ти же, я́ко імі́яй дерзнове́ніє к Царю́ Небе́сному, от вся́ких м'я бід і скорбе́й, от враг ви́димих же і неви́димих защити́, зову́ща:","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Ікос 1","ps":["А́нгеле святи́й, по́сланний с Небесе́, во є́же храни́ти м'я і руководи́ти во всей жи́зні моє́й, припа́дая молю́ ті ся: сам наста́ви і вразуми́ м'я, начина́юща от серде́чния любве́ і усе́рдія возглаша́ти пі́сненния ті хвали́:","Ра́дуйся, А́нгеле Бо́жий, предста́телю мой у Пресвяти́я Тро́йці;","ра́дуйся, Царя́ ца́рствующих безпло́тний во́їне.","Ра́дуйся, Го́спода госпо́дствующих небе́сний слуго́;","ра́дуйся, у́мних і невеще́ственних слуг Єго́ сожи́телю.","Ра́дуйся, творя́й при́сно во́лю Влади́ки своєго́;","ра́дуйся, приє́мий от Бо́га повелі́ніє і власть храни́ти ду́шу мою́.","Ра́дуйся, нікогда́же отлуча́яйся мене́, грі́шнаго;","ра́дуйся, ви́ну спребива́яй мі, недосто́йному.","Ра́дуйся, соблюда́яй м'я на всіх путеіх мої́х;","ра́дуйся, сохраня́яй м'я от вся́каго зла.","Ра́дуйся, от Бо́га да́нний мі руководи́телю на путеіх житія́ моєго́;","ра́дуйся, благи́й мой наста́вниче.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 2","ps":["Ви́дів человіколюби́вий Госпо́дь, я́ко, по прегріше́нії пра́отця на́шего Ада́ма, всі челові́ци удо́б прекло́нни суть ко гріху́, по Своє́й неізрече́нній ми́лости посла́л єсть во всю зе́млю святи́х А́нгелов і коєму́ждо от челові́к приста́ви храни́теля. Ісполня́юще у́бо повелі́ніє Влади́ки своєго́, святі́ї А́нгели всегда́ гото́ві суть помога́ти нам, богоуго́дно пою́щим: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зуму моєму́ просвіще́ніє сви́ше ісхода́тайствуй, святи́й А́нгеле, да возмогу́ позна́ти, что єсть во́ля Бо́жия, блага́я і уго́дная і соверше́нная, і се́рдце моє́ напра́ви, є́же со усе́рдієм твори́ти ю; тебі́ же, храни́теля моєго́, да не преста́ну восхваля́ти сицеви́ми гла́си:","Ра́дуйся, воспламеня́яй се́рдце моє́ любо́вію к Бо́гу, Созда́телю моєму́;","ра́дуйся, возбужда́яй м'я на всяк день же і час приноси́ти Єму́ моли́тви, проше́нія і благодаре́нія.","Ра́дуйся, я́коже стра́жем ві́рним, стра́хом Госпо́днім душе́вний мой дом огражда́яй;","ра́дуйся, вся помишле́нія моя́ к расп'я́тому за гріхи́ ми́ра Спаси́телю устремля́яй.","Ра́дуйся, страда́нія Єго́ і кре́стную смерть в па́м'ять мою́ вперя́яй;","ра́дуйся, воспомина́нієм Страсте́й Госпо́дніх блюсти́ся от гріхо́в м'я поуча́яй.","Ра́дуйся, благода́тнаго Сви́ше осіне́нія Свята́го Ду́ха проси́ти м'я наставля́яй;","ра́дуйся, я́ко на кро́ткия то́чію і смире́нния се́рдцем ми́лостивне призира́ти Єму́, Уті́шителю, увіря́я м'я.","Ра́дуйся, ми́слію о вездесу́щії Бо́жії всю́ду окружа́яй м'я;","ра́дуйся, всеве́деніє Єго́ у́мним очесе́м мої́м представля́яй.","Ра́дуйся, милосе́рдієм Єго́ ко ка́ющимся грі́шником се́рдце моє́ утіша́яй;","ра́дуйся, правосу́дієм Єго́ к ожесточе́нним і нераска́янним ду́шу мою́ устраша́яй.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 3","ps":["Си́лу Боже́ственния благода́ті іспроси́ мі, храни́телю мой А́нгеле, во є́же неукло́нно і непреткнове́нно ходи́ти мі спаси́тельним путе́м Христо́вих за́повідей, се́рдцем же і усти́ непреста́нно сла́вити всесвято́є і́м'я Бо́га на́шего і пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["І́мам тя, Богоізбра́нний покрови́телю мой, я́коже сві́тлую зарю́, просвіща́ющую душі́ моєя́ темноту́ і разгоня́ющую мрак серде́чнаго неві́дінія моєго́; сего́ ра́ди, со умиле́нієм припа́дая, молю́ ті ся, да і вся моя́ чу́вствія, потемне́нная страстьми́, очи́стяться, во є́же не блужда́ти мі во тьмі гріхо́вній. Пречу́дную же сві́тлость твою́ воспіва́ю си́це:","Ра́дуйся, звіздо́ Невече́рняго Сві́та, от трисія́ннаго Божества́ возсія́вшая і мене́ ви́ну озаря́ющая;","ра́дуйся, пресві́тлая луче́, помраче́нная гріхми́ серде́чная мі очеса́ осіява́ющая.","Ра́дуйся, я́ко тщи́шася напра́вити м'я на і́стинний путь во тьмі беззако́ній заблужда́ющаго;","ра́дуйся, я́ко предлага́єши мі за́повіді Госпо́дні, а́ки зерца́ло для всея́ жи́зні моєя́.","Ра́дуйся, я́ко поставля́єши мі зако́н Бо́жий, а́ки світи́льник нога́ма мої́ма і світ стезя́м мої́м;","ра́дуйся, я́ко слове́с Єва́нгелія Христо́ва в сла́дость послу́шати поуча́єши м'я.","Ра́дуйся, я́ко уче́нію Боже́ственнаго Учи́теля моєго́ і Го́спода несумні́нно ві́ровати побужда́єши м'я;","ра́дуйся, я́ко в повинове́нії уста́вом святи́я Це́ркве укріпля́єши м'я.","Ра́дуйся, я́ко пра́вилом і преда́нієм святи́х Апо́стол і оте́ць покаря́тися наставля́єши м'я;","ра́дуйся, я́ко во іспові́данії святи́я і правосла́вния ві́ри утвержда́єши м'я.","Ра́дуйся, я́ко за сіє́ іспові́даніє і на смерть гото́ва м'я би́ти убежда́єши;","ра́дуйся, я́ко єретико́м і отсту́пником і́стинния Це́ркве сообща́тися возбраня́єши мі.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 4","ps":["Бу́ря жите́йськаго мо́ря сокруша́єть духо́вний мой кора́бль волна́ми мирськи́х попече́ній, і мир убо́гія душі́ моєя́ м'яте́ться, і гді обря́щу ти́хоє приста́нище спасе́нія? То́кмо на тя по Бо́зі возлага́ю наде́жду, храни́телю мой А́нгеле, я́ко прему́драго тя ко́рмчаго в ми́сленних бу́рях, смуща́ющих м'я, стяжа́х: благода́рственні у́бо пою́ Бо́гу моєму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і зря́ще тя, Боже́ственний А́нгеле, крі́пкаго моєго́ блюсти́теля, зло́бнії ду́си поднебе́снії не смі́ють прибли́житися ко твоє́й пречи́стій сві́тлости і душегуби́тельниє мі па́кості ді́яти. Сего́ ра́ди смире́нно молю́ тя, не отступи́ от мене́ за невоздержа́ніє моє́, но при́сно от лука́ваго тіх лови́тельства і ко́зней соблюда́й м'я, со умиле́нієм глаго́люща:","Ра́дуйся, крі́пким кро́вом крил твої́х осіня́яй м'я і покрива́яй;","ра́дуйся, о́крест мене́ с пла́менним мече́м при́сно ополча́яйся.","Ра́дуйся, проти́ву кня́зя тьми во бра́ні мі посо́бствуяй;","ра́дуйся, лука́вих єго́ служи́телей побіжда́ти мі помога́яй.","Ра́дуйся, отгоня́яй от мене́ душепа́губния де́мони, а́ки хи́щния пти́ці;","ра́дуйся, вразумля́яй м'я бісо́вськия ко́зні позна́ти, а́ки лука́вия лиси́ці.","Ра́дуйся, зверообра́зная тіх на ум і се́рдце моє́ нападе́нія отріва́яй.","Ра́дуйся, порожде́нія їх, го́рдость і не́нависть, із сердця́ моєго́ історга́яй.","Ра́дуйся, за́висть і злопомні́ніє от ми́слей мої́х прогоня́яй;","ра́дуйся, во отраже́ніє злих по́мислов кре́стним зна́менієм себі́ огражда́ти побужда́яй м'я.","Ра́дуйся, на а́спида і васили́ска небоя́зненно наступа́ти укріпля́яй м'я;","ра́дуйся, імі́яй непобіди́моє ору́жіє проти́ву всіх враго́в мої́х.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 5","ps":["Боготе́чній і лучеза́рней звізді́, путеводи́вшей дре́вле волхви́ на поклоне́ніє ро́ждшемуся во Вифлеє́мі Спаси́телю ми́ра, дерза́ю уподо́бити тя, благи́й мой храни́телю: неотлу́чним бо і світоно́сним твої́м мі спребива́нієм указу́єши мі пра́вий путь, веду́щий в Го́рній Вифлеє́м, в Небе́сноє Ца́рствіє, да та́мо с ли́ки Арха́нгел і А́нгел сподо́блюся воспіва́ти Преві́чному Царю́ сла́ви: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя М'я но́щію содержи́ма мра́чною і те́мним о́блаком страсте́й покрива́єма, святи́й храни́телю ду́ші моєя́, не огорчи́ся, не оста́ви мене́, но подража́яй долготерпі́нію Спаси́теля моєго́, пожди́ єще́, возбужда́я м'я к покая́нію, до́ндеже очеса́ моя́ ізлію́ть істо́чники слез на оми́тіє душе́вния нечистоти́ моєя́. О сем смире́нно молю́ тя і глаго́лю:","Ра́дуйся, я́ко ви́ну прино́сиши Бо́гу о мні грі́шнім моли́тви своя́, я́ко кади́ло пред Ним благово́нноє;","ра́дуйся, я́ко при́сно хода́тайствуєши пред Созда́телем мої́м о є́же спасти́ся мі.","Ра́дуйся, я́ко пра́ведний гнів Єго́, дви́жимий на м'я, свої́м предста́тельством отвраща́єши;","ра́дуйся, я́ко про́сиши всемилосе́рдаго Го́спода пода́ти проще́ніє злих мої́х дія́ній.","Ра́дуйся, я́ко умилостивля́єши Єго́ бла́гость, да не погуби́ть м'я со беззако́ньми мої́ми;","ра́дуйся, я́ко непреста́нно мо́лишися Іскупи́телю моєму́, да да́руєть мі вре́м'я ко ісправле́нію.","Ра́дуйся, я́ко возбужда́єши м'я в покая́нії препроводи́ти вся дні живота́ моєго́;","ра́дуйся, я́ко внуша́єши мі жела́ніє, да ви́ну ка́юся пред Го́сподем во всіх мої́х прегріше́ніях.","Ра́дуйся, я́ко вразумля́єши м'я на вся́коє вре́м'я ми́сленно себі́ іспи́товати і во грісі́х мої́х іспові́датися;","ра́дуйся, я́ко влага́єши в се́рдці моє́ сокруше́ніє і скорб, зане́ прогні́вах Преблага́го Бо́га моєго́.","Ра́дуйся, я́ко побужда́єши м'я опла́кивати окая́нноє і скве́рноє житіє́ моє́;","ра́дуйся, світоно́сний і неумолка́ющий хода́таю спасе́нія моєго́.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 6","ps":["Пропові́дую велегла́сно при́сноє твоє́, храни́телю мой А́нгеле, о мні, грі́шнім, попече́ніє: в ско́рбіх бо і напа́стіх, я́же в сем многом'яте́жнім ми́рі смуща́єть мир душі́ моєя́, явля́єши мі ся ско́рий уті́шитель, вразумля́я м'я, я́ко вся сія́ низпосила́ються от прему́драго Созда́теля, а́ки врачевство́ проти́ву душе́вних неду́гов мої́х, і поуча́я благоді́ющему си́це Небе́сному Врачу́ воспіва́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіява́єть в душі́ моє́й, омрача́ємой ско́рбію і уни́нієм, світ благода́тнаго утіше́нія, і се́рдце моє́ ісполня́ється весе́лія і ра́дости, єгда́ непреста́нними твої́ми, святи́й А́нгеле, наставле́нії возбужда́єм дерза́ю, я́ко мита́р, вопи́ти к ще́дрому Бо́гу, да ми́лостив бу́деть і прости́ть мі прегріше́нія моя́. Не премолчи́ у́бо, наста́вниче мой, вразумля́я і укріпля́я м'я, зову́ща ті:","Ра́дуйся, помога́яй мі благи́й яре́м спаси́тельнаго терпі́нія с любо́вію носи́ти;","ра́дуйся, в біда́х і заключе́ніїх упова́нієм на Го́спода Бо́га укріпля́яй м'я.","Ра́дуйся, ско́рби і болі́зні му́жественні преодолева́ти м'я поуча́яй;","ра́дуйся, вся́кую печа́ль і уни́ніє от се́рдця моєго́ отгоня́яй.","Ра́дуйся, проти́ву врага́, в сіть отча́янія улови́ти м'я хотя́ща, бра́тися побужда́яй м'я;","ра́дуйся, словесе́м Апо́стола, я́ко всі хотя́щії благоче́стно жи́ти гони́ми бу́дуть, ві́ровати убежда́яй м'я.","Ра́дуйся, о́браз терпі́нія і злострада́нія прия́ти мі проро́ки і Апо́столи внуша́яй;","ра́дуйся, на лик му́ченик і іспові́дник, за Христа́ до ізлія́нія кро́ве своєя́ подвиза́вшихся, во утіше́ніє мі показу́яй.","Ра́дуйся, страда́нія Самаго́ Спаси́теля і Го́спода ви́ну у́мним очесе́м мої́м представля́яй;","ра́дуйся, наде́ждею бу́дущаго воздая́нія се́рдце моє́ услажда́яй.","Ра́дуйся, всера́достним ожида́нієм ві́чних благ ду́шу мою́ оживля́яй;","ра́дуйся, благи́й і при́сний мой уті́шитель.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 7","ps":["Хотя́й всім челові́ком спасти́ся, премилосе́рдий Созда́тель мой посла́ Тя, А́нгела Своєго́, я́ко ві́рна мі стра́жа і пі́стуна до́бра во всем житії́ моє́м, да всю́ду вспомоществу́єши мі святи́ми твої́ми вдохнове́нії, защища́єши проти́ву ко́зней дия́вола і предуготовля́єши м'я ді́ли благи́ми вни́ти с му́дрими ді́вами в Небе́сний Черто́г, с Богокра́сною пі́снію: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показу́єть бла́гость Госпо́дь і Влади́ка мой на мні, непотре́бнім і па́че всіх грі́шнійшем ра́бе Своє́м: презира́я бо лю́тая моя́ і тя́жкая, не погуби́л м'я єсть со беззако́ньми мої́ми да́же до настоя́щаго дне і ча́са, но долготерп'я́ на мні, ми́лостивне ожида́єть моєго́ обраще́нія і серде́чнаго покая́нія. Ві́рую, благи́й храни́телю мой, я́ко твої́м при́сним пред Бо́гом за м'я хода́тайством досе́лі храни́м єсьм: ті́мже, любо́вію к тебі́ подвиза́ємий, взива́ю:","Ра́дуйся, я́ко обурева́ющася м'я в мо́рі житія́ сего́ от коне́чнаго потопле́нія соблюда́єши;","ра́дуйся, я́ко із ро́ва беззако́ній мої́х руко́ю твоєя́ по́мощі м'я ісхища́єши.","Ра́дуйся, я́ко гріхо́вний сон душевре́дния моєя́ лі́ності отряса́єши;","ра́дуйся, я́ко ум мой, омраче́нний небреже́нієм, сві́тлим твої́м прису́тствієм озаря́єши.","Ра́дуйся, я́ко хла́дноє і ма́ло не уга́сшеє се́рдце моє́ моли́твами воспламеня́ти мі помога́єши;","ра́дуйся, я́ко на славосло́віє Бо́жиє при́сно м'я возставля́єши.","Ра́дуйся, я́ко настроя́єши глас мой к піснопі́ніям, і́миже досто́йно і пра́ведно єсть хвали́ти Творця́ вся́чеських;","ра́дуйся, я́ко поуча́єши м'я прославля́ти Го́спода моєго́ не усти́ то́чію, но і се́рдцем.","Ра́дуйся, я́ко к ісполне́нію пресвяти́я во́лі Єго́ возбужда́єши м'я;","ра́дуйся, я́ко самоотверже́нію і отрече́нію моєя́ зли́я во́лі приобучи́ти м'я тщи́шися.","Ра́дуйся, я́ко голуби́ну простоту́ і а́гнчу кро́тость стяжа́ти мі преі́скренні жела́єши;","ра́дуйся, я́ко о є́же младе́нчеському незло́бію і ста́рчеському доброразсужде́нію дарова́тися мі хода́тайствуєши.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 8","ps":["Стра́нен і пришле́ць єсьм на землі́ сей: житіє́ моє́ су́єтно і маловре́менно єсть; аз же, окая́нний, сме́рті безві́стноє во ум нікогда́же приє́млю, ні помишля́ю о Стра́шнім Суди́щі, в нем же і́мам Пра́ведному Судії́ предста́ти і да́ти отві́т о вся́ком ді́лі же і сло́ве. Ті́мже молю́ тя, душі́ моєя́ храни́теля, возбуди́ м'я ско́ро от сна гріхо́внаго, да не пости́гнеть м'я час сме́рти неіспра́вленна і да сподо́блюся іспроси́ти от Всеми́лостиваго Бо́га беззако́нієм мої́м проще́ніє і во гла́сі ра́дованія воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всіх Госпо́дь і Созда́тель мой, єгда́ назна́менуєть мі преста́витися от житія́ сего́, ти, благи́й храни́телю мой, прови́дяй гро́зния му́ки, духово́м зло́би і нераска́янним грі́шником угото́ванния і мене́ ожида́ющия, покри́й м'я твоєго́ милосе́рдія крила́ми, я́коже оре́л птенці́ своя́, і внегда́ ісчеза́ти от мене́ ду́ху моєму́, да у́зрю тя близ мене́ предстоя́ща і лю́тия враги́ отгоня́юща. О сем со умиле́нієм молю́ ті ся, віща́я си́це:","Ра́дуйся, у́мним очесе́м мої́м го́ркий і стра́шний час сме́ртний представля́яй;","ра́дуйся, я́ко неізбе́жен, вку́пі же і безві́стен час той при́сно мі напомина́яй.","Ра́дуйся, на ки́йждо день, а́ки уже́ на послі́дній житія́ моєго́ взира́ти м'я поуча́яй;","ра́дуйся, на вся́коє вре́м'я ко ісхо́ду во ін мир м'я приуготовля́яй.","Ра́дуйся, душе́вноє умиле́ніє і серде́чноє сокруше́ніє во мні рожда́яй;","ра́дуйся, ви́ну жела́яй мі, да поне́ при кончи́ні дній мої́х пока́юся.","Ра́дуйся, люби́ти мир і я́же в ми́рі мі воспреща́яй;","ра́дуйся, пристра́стіє к тлі́нному бога́тству із се́рдця моєго́ іскореня́ти помога́яй.","Ра́дуйся, вся бла́га земна́я би́ти привре́менна і скоропреходя́ща мі показу́яй;","ра́дуйся, я́ко вся кра́сная ми́ра сего́ кри́ну се́льному подо́бна суть, вразумля́яй м'я.","Ра́дуйся, сла́ви челові́чі, а́ки ті́ни преходя́щия, іска́ти возбраня́яй мі;","ра́дуйся, от єди́наго Бо́га сла́ви нетлі́нния в бу́дущем ві́ці взиска́ти побужда́яй м'я.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 9","ps":["Всяк гріх соді́ях в житії́ сем і весь живо́т мой во мно́зі прите́к суєті́, ко концю́ прибли́жихся: вразі́ же мої́ устремля́ються на м'я, а́лчуще поя́ти м'я і низри́нути во глубину́ а́дову. Ті́мже молю́ ті ся, благи́й мой Храни́телю, бу́ди мі защи́титель, єгда́ і́мам преходи́ти лю́тая мита́рства, і безбі́дно доведи́ м'я до врат Небе́снаго Ца́рствія, іді́же ли́ци а́нгельстії ра́достні сріта́ють восклиця́ющих: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к не мо́жеть ізрещи́, я́же сотвори́л мі єси́, святи́й храни́телю мой, во всем житії́ моє́м: прия́в бо ду́шу мою́ от купі́лі Свята́го Креще́нія, храни́л м'я єси́ во младе́нчестві, учи́л і вразумля́л єси́ во о́трочестві, соблюда́л м'я єси́ от поползнове́нія ко гріхо́м во во́зрасті ю́ношестім, наставля́л єси́, прише́дша м'я в му́жество, охраня́л єси́ на всіх путеіх мої́х да́же до ста́рости, облича́я і утіша́я, всю́ду помога́я і направля́я на путь спасе́нія. Сего́ ра́ди благода́рственно вопію́ ті:","Ра́дуйся, я́ко нікогда́же лиша́єши м'я твоєя́ по́мощі і заступле́нія;","ра́дуйся, я́ко от сна востаю́ща м'я подвиза́єши ко благодаре́нію Го́спода, укріпля́ющаго си́ли моя́.","Ра́дуйся, я́ко нача́ток коєго́ждо дне моли́твою освяща́ти м'я поуча́єши;","ра́дуйся, я́ко воспреща́єши мі без моли́тви к всеблаго́му Промисли́телю, дерзнове́нно собо́ю что начина́ти.","Ра́дуйся, я́ко самонаде́яніє із се́рдця моєго́ істреби́ти тщи́шися;","ра́дуйся, я́ко сладча́йшеє і́м'я Го́спода Ісу́са Христа́ усти́ непреста́нно проізноси́ти і во умі́ держа́ти м'я побужда́єши.","Ра́дуйся, я́ко во вся́коє вре́м'я ну́жная то́чію і поле́зная віща́ти язи́ком мі внуша́єши;","ра́дуйся, я́ко от праздносло́вія, многоглаго́ланія, па́че же і кощу́нства м'я удержава́єши.","Ра́дуйся, я́ко яду́щу і пію́щу мі іли́ і́но что творя́щу при́сно спребива́єши;","ра́дуйся, я́ко воздержа́нію в пи́щі і питії́ приобучи́ти м'я пече́шися.","Ра́дуйся, я́ко сп'я́ща м'я храни́ти і врага́, хотя́ща іскуси́ти м'я со́нними мечта́нії, отгоня́єши;","ра́дуйся, я́ко восп'яща́єши м'я от любостра́стнаго стремле́нія і во о́чію моє́ю цілому́дренний стид влага́єши.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 10","ps":["Спасти́ всіх прише́дий Ісу́се мой преблаги́й, со умиле́нієм молю́ Ті ся, Твої́м милосе́рдієм прості́ мої́х злих премно́жество і безмі́ріє, преклоня́ємий на сіє́ Боже́ственними мольба́ми Твоєго́ невеще́ственнаго служи́теля, єго́же мі приста́вил єси́ із младе́нства, я́ко Человіколю́бець, храни́теля: да досто́їн явлю́ся вни́ти в черто́г сла́ви Твоєя́ і со ду́хи пра́ведних воспі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда при́сно явля́єши мі ся, святи́й А́нгеле, проти́ву ухищре́ній зло́бних враго́в мої́х, і́щущих ві́чния поги́белі моєя́ і разслабля́ющих ду́шу мою́ лі́ностію і самозабве́нієм. Молю́ у́бо тя, храни́телю мой, да твої́м хода́тайством сподо́блюся, при ісхо́ді душі́ моєя́ із тілесе́ прича́стник би́ти Пречи́стаго Ті́ла і святі́йшия Кро́ве моєго́ Спаси́теля, я́ко да укріпи́вся се́ю нетлі́нною пи́щею і животворя́щим питіє́м, безтре́петно прейду́ во ін мир, воспіва́я тя, моєго́ благоді́теля:","Ра́дуйся, я́ко дана́ ті єсть власть і си́ла отража́ти де́монськая на м'я нападе́нія;","ра́дуйся, я́ко прия́л єси́ от Бо́га крі́пость на побіжде́ніє неви́димих враго́в мої́х.","Ра́дуйся, я́ко от вся́каго злоді́йства і ко́зней дия́вольських моги́й ізба́вити м'я;","ра́дуйся, я́ко го́рких мита́рств нача́льника, лю́таго мироде́ржця нападе́нія от мене́ отріва́єши.","Ра́дуйся, я́ко, огражда́ємий твої́м прису́тствієм, і́мам наде́жду в час сме́рти не устраши́тися мра́чних лиць духо́в зло́би;","ра́дуйся, я́ко храни́мий тобо́ю, упова́ю безбі́дно прейти́ возду́шная мита́рства.","Ра́дуйся, я́ко укріпля́ємий твоє́ю по́мощію, ча́ю не уде́ржан би́ти вні врат рая́, мі вожделі́ннаго;","ра́дуйся, я́ко твоє́ за м'я предста́тельство си́льно єсть пред Бо́гом, є́же не вве́ржену мі би́ти во тьму кромі́шную.","Ра́дуйся, я́ко при́сно внуша́єши мі умилостивля́ти Го́спода слеза́ми покая́нія, да ізба́влюся геє́нни а́дськия;","ра́дуйся, я́ко побужда́єши м'я день і нощ моли́тися, да не по́слан бу́ду со де́мони му́читися.","Ра́дуйся, неотсту́пний мой руководи́телю і пе́стуне;","ра́дуйся, крі́пкий мой засту́пниче і ско́рий помо́щниче.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 11","ps":["Пі́ніє сіє́, а́ще і от усе́рдія моєго́ ті приноси́моє, святи́й храни́телю мой, вім, я́ко не дово́льно єсть ко із'явле́нію моєго́ серде́чнаго благодаре́нія за вся блага́я, я́же мі сотвори́л єси́ і не престає́ши твори́ти да́же до сего́ дне і ча́са; но і о сем молю́ ті ся, о́бщаго мі с тобо́ю Созда́теля уми́лостиви, да на Стра́шнім Суді́ Своє́м шу́їя ча́сти ізба́вить м'я і сподо́бит со всі́ми святи́ми воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник мой угасе́, єле́я же благи́х діл, во є́же возжещи́ і, ність мі; і гді обря́щуся аз, окая́нний, сном гріхо́вним отягче́нний, єгда́ пости́гнеть м'я внеза́пу полу́нощ, час кончи́ни моєя́? Но да не усли́шу і аз, я́коже юро́дивия ді́ви, гро́знаго гла́са Жениха́: не вім тя! Помози́ мі, неусипа́ємий храни́телю мой, напо́лнити сосу́ди душі́ моєя́ єле́єм благи́х діл, па́че же милосе́рдія і смире́нія. Ни́ні же прийми́ от мене́ сіє́ пі́ніє:","Ра́дуйся, Єди́наго Го́спода імі́ти в ра́зумі при́сно мі внуша́яй;","ра́дуйся, за́повідь о любві́ к Нему́, преблаго́му, в се́рдці моє́м обновля́яй.","Ра́дуйся, люби́ти Єго́, Созда́теля, всім умо́м і всім помишле́нієм м'я побужда́яй;","ра́дуйся, і к бли́жнім і́скреннюю любо́в мою́ Богоуго́дну би́ти непреста́нно мі напомина́яй.","Ра́дуйся, люби́ти їх не сло́вом іли́ язи́ком, но ді́лом і і́стиною м'я поуча́яй;","ра́дуйся, во всіх ну́ждах їх помога́ть жела́ніє мі влага́яй.","Ра́дуйся, утіша́ти скорб'я́щих, заступа́ти оби́димих м'я наставля́яй;","ра́дуйся, от імі́ній свої́х уділя́ти бі́дним і неіму́щим се́рдце моє́ преклоня́яй.","Ра́дуйся, і ду́шу мою́, по за́повіді Спаси́теля, положи́ти за дру́ги своя́ гото́ву мі би́ти возбужда́яй;","ра́дуйся, закрива́яй очеса́ моя́, є́же не зрі́ти мі прегріше́нія бра́та моєго́.","Ра́дуйся, не попуща́яй мі осужда́ти поползну́вшагося на гріх бли́жняго моєго́;","ра́дуйся, воспреща́яй мі я́ти ві́ру оглаго́льником клевре́та моєго́.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 12","ps":["Благода́ть дана́ ті єсть от Всемогу́щаго Го́спода, святи́й покрови́телю мой, є́же храни́ти м'я на всіх путеіх мої́х, да не о ка́мень ко́єго собла́зна преткне́ться нога́ моя́, до́ндеже м'я предста́виши Христу́ Бо́гу спасе́на, Єму́же немо́лчно вся Си́ли Небе́сния взива́ють: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ Твоє́ досточу́дноє милосе́рдіє і мно́гоє снисхожде́ніє, бистродви́жний у́ме, безпло́тний слуго́ Госпо́день: я́ко не гнуша́єшися гріхо́вния моєя́ смра́дности і не престає́ши приноси́ти о мні, непотре́бнім, святи́я моли́тви своя́ ко святі́йшему престо́лу Триіпоста́снаго Бо́га, є́же не поги́бнути мі во ві́ки, но Ца́рствіє Небе́сноє наслі́довати. Благоволи́ у́бо прия́ти от душе́вних сокро́вищ мої́х приноси́моє ті піснопі́ніє:","Ра́дуйся, я́ко воспомина́нієм гряду́щаго гро́знаго Суда́ Бо́жия от гріхо́в м'я отріва́єши;","ра́дуйся, я́ко ду́шу мою́, а́ки неві́сту, ко срі́тенію прекра́снаго Жениха́ Христа́ предуготовля́ти возбужда́єши м'я.","Ра́дуйся, я́ко при́сно жела́єши досто́йна м'я сотвори́ти бра́чнаго черто́га Єго́;","ра́дуйся, я́ко ви́ну учи́ша м'я возжига́ти світи́льник душі́ моєя́, да с му́дрими ді́вами, ду́шами пра́ведних, вни́ду в онь.","Ра́дуйся, я́ко гріхо́вния оде́жди моєя́ совлачи́тися побужда́єши м'я;","ра́дуйся, я́ко в ри́зу непоро́чности і чистоти́ облещи́ся мі спосо́бствуєши.","Ра́дуйся, я́ко хода́тайствуєши, да на Стра́шнім Суді́ Христо́вом одесну́ю Єго́ ста́ти сподо́блюся;","ра́дуйся, я́ко умоля́єши благоутро́біє Бо́жиє, да ли́ку ізбра́нних Свої́х сопричте́ть м'я.","Ра́дуйся, я́ко подвиза́єши на моли́тву ко Го́споду і сожи́телей твої́х небе́сних, да всели́ть м'я с ни́ми во Ца́рствії Своє́м;","ра́дуйся, до́брий і бо́дрий блюсти́телю мой.","Ра́дуйся, те́плий о мні, грі́шнім, моли́твенниче і благи́й предста́телю;","ра́дуйся, по Го́споді Бо́зі і Пресвяті́й Богоро́дице крі́пкоє моє́ упова́ніє.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 13","ps":["О пресла́вний і у́мний сві́те, А́нгеле Бо́жий! Прийми́ благода́рственноє сіє́ і моле́бноє пі́ніє, і, єгда́ і́мам от землі́ воста́ти на Суд, покажи́ тогда́ милосе́рдіє твоє́ на мні, грі́шнім: предста́ни близ мене́ тих і ра́достен, наде́ждою спасе́нія от'є́мля страх мой, да в селе́ніїх ра́йських сподо́блюся вку́пі с тобо́ю во ві́ки віко́во воспіва́ти преві́чному Царю́ сла́ви: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгеле святи́й, по́сланний с Небесе́, во є́же храни́ти м'я і руководи́ти во всей жи́зні моє́й, припа́дая молю́ ті ся: сам наста́ви і вразуми́ м'я, начина́юща от серде́чния любве́ і усе́рдія возглаша́ти пі́сненния ті хвали́:","Ра́дуйся, А́нгеле Бо́жий, предста́телю мой у Пресвяти́я Тро́йці;","ра́дуйся, Царя́ ца́рствующих безпло́тний во́їне.","Ра́дуйся, Го́спода госпо́дствующих небе́сний слуго́;","ра́дуйся, у́мних і невеще́ственних слуг Єго́ сожи́телю.","Ра́дуйся, творя́й при́сно во́лю Влади́ки своєго́;","ра́дуйся, приє́мий от Бо́га повелі́ніє і власть храни́ти ду́шу мою́.","Ра́дуйся, нікогда́же отлуча́яйся мене́, грі́шнаго;","ра́дуйся, ви́ну спребива́яй мі, недосто́йному.","Ра́дуйся, соблюда́яй м'я на всіх путеіх мої́х;","ра́дуйся, сохраня́яй м'я от вся́каго зла.","Ра́дуйся, от Бо́га да́нний мі руководи́телю на путеіх житія́ моєго́;","ра́дуйся, благи́й мой наста́вниче.","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Кондак 1","ps":["Ізбра́нний от Го́спода Бо́га на хране́ніє ду́ші моєя́ і тілесе́, святи́й А́нгеле, похва́льная ті воспіва́ти дерза́ю, недосто́йний раб твой; ти же, я́ко імі́яй дерзнове́ніє к Царю́ Небе́сному, от вся́ких м'я бід і скорбе́й, от враг ви́димих же і неви́димих защити́, зову́ща:","Ра́дуйся, А́нгеле Госпо́день, неусипа́ємий храни́телю мой."]},{"h":"Молитва","ps":["О, святи́й А́нгеле, храни́телю і покрови́телю мой благи́й! С сокруше́нним се́рдцем і болі́зненною душе́ю предстою́ ті, моля́ся: усли́ши м'я, грі́шнаго раба́ своєго́ (ім’я), с во́плем крі́пким і пла́чем го́рким вопію́щаго. Не пом'яни́ мої́х беззако́ній і непра́вд, і́миже аз окая́нний прогнівля́ю тя по вся дні і часи́, і ме́рзостна себі́ творю́ пред Созда́телем на́шим Го́сподем. Яви́ся мні милосе́рд і не отлуча́йся мене́ скве́рнаго да́же до кончи́ни моєя́. Возбуди́ м'я от сна гріхо́внаго і посо́бствуй твої́ми моли́твами про́чеє вре́м'я живота́ моєго́ без поро́ка прейти́ і сотвори́ти плоди́ досто́йни покая́нія, па́че же от сме́ртних паде́ній гріхо́вних соблюди́ м'я, да не поги́бну во отча́янії і да не пора́дується враг о поги́белі моє́й. Вім воі́стину і усти́ іспові́дую, я́ко нікто́же тако́в друг і предста́тель, защи́титель і побо́рник, я́коже ти, святи́й А́нгеле. Предстоя́ бо Престо́лу Госпо́дню, мо́лишися о мні непотре́бнім і па́че всіх грі́шнійшем, да не ізи́меть Преблаги́й душі́ моєя́ в день неча́янія моєго́ і в день творе́нія зло́би. Не преста́й у́бо умилостивля́я Премилосе́рдаго Го́спода і Бо́га моєго́, да отпу́стить согріше́нія моя́, я́же сотвори́х во всем житії́ моє́м, ді́лом, сло́вом і всі́ми мої́ми чу́встви, і ї́миже вість судьба́ми да спасе́ть м'я, да нака́жеть м'я зді по Своє́й неізрече́нной ми́лости, но да не обличи́ть і не істя́жеть м'я она́мо по Своєму́ нелицеприя́тному правосу́дію, да сподо́бит м'я покая́ніє принести́, с покая́нієм же Боже́ственноє Причаще́ніє досто́йні прия́ти, о сем па́че молю́, і такова́го да́ра всеусе́рдно жела́ю. В стра́шний же час сме́рти неотсту́пен бу́ди мі, благи́й Храни́телю мой, прогоня́я мра́чния де́мони, іму́щия устраши́ти притре́петную ду́шу мою́. Защити́ м'я от тіх ловле́нія, єгда́ і́мам преходи́ти возду́шная мита́рства, да храни́м тобо́ю, безбі́дно дости́гну рая́ мі вожделі́ннаго, іді́же ли́ци святи́х і го́рніх сил непреста́нно восхваля́ють всечестно́є і великолі́поє і́м'я в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, Єму́же подоба́єть честь і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 6","ps":["А́нгеле Бо́жий, / храни́телю мой святи́й, / живо́т мой соблюди́ во стра́сі Христа́ Бо́га, / ум мой утверди́ во і́стиннім путі́, / і к любві́ го́рній уязви́ ду́шу мою́, / да тобо́ю направля́єм, // получу́ от Христа́ Бо́га ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Яви́ся мні милосе́рд, / святи́й А́нгеле Госпо́день, храни́телю мой, / і не отлуча́йся мене́ скве́рнаго, / но просвіти́ м'я сві́том неприкоснове́нним // і сотвори́ м'я досто́йна Ца́рствія Небе́снаго."]}],"notes":[]},{"u":"Акафіст Всемогутньому Богу в наступі скорботи","e":"Akathist to Almighty God in Time of Affliction","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Го́споди, ра́досте і весе́ліє рабо́м Твої́м, іді́же Ти, та́мо потребля́ється вся́кая печа́ль, іді́же ність Тебе́, та́мо вся́кая ра́дость су́єтна. При́зри на м'я грі́шнаго, погиба́ющаго в біді́ сей, і явле́нієм спасе́нія Твоєго́ посіти́ м'я, зову́ща:","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче і Го́споди сил, спасе́нія ра́ди па́дшаго челові́ка не возгнуша́лся єси́ Девичеського Чре́ва, посліди́ же заплева́нія, поноше́нія і поно́сную смерть претерпі́л єси́, Сло́ве Бо́жий, благ бо єси́ і Человіколю́бець. Сіє́ помишля́я, дерза́ю приступи́ти к Тебі́ і со слеза́ми моли́тися:","Го́споди мой, Го́споди, милосе́рдий Спаси́телю мой, спаси́ м'я погиба́ющаго;","Го́споди мой, Го́споди, прише́дий не пра́ведния спасти́, но грі́шния, ізба́ви м'я от напа́сти сея́.","Го́споди мой, Го́споди, неду́ги на́ша приє́мий і болі́зні понеси́й, ісціли́ болі́зні се́рдця моєго́;","Го́споди мой, Го́споди, кресто́м Твої́м мир ми́ру Твоєму́ дарова́вий, ниспосли́ мир Твой смущенней душі́ моє́й.","Го́споди мой, Го́споди, Своє́ю сме́ртію смерть упраздни́вий, упраздни́ я́же на м'я ко́зні лука́ваго;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 2","ps":["Ви́дівий мно́гія о́брази человіколю́бія Твоєго́, явле́нния на би́вших пре́жде мене́ грі́шниціх, дерзну́х і аз возвісти́ к Тебі́ о́чі мої́, живу́щему на небесі́: поми́луй м'я, Го́споди, я́ко не́мощен єсьм, ізба́ви м'я го́ркия сея́ печа́лі і сподо́би ра́достію і весе́лієм пі́ти Тебі́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мную м'я твар сотвори́л єси́, Созда́телю мой, аз же окая́нний приложи́хся ското́м несми́сленним і уподо́бихся їм, прогні́вах бо бла́гость Твою́, Спа́се: сего́ ра́ди пра́ведно се́ю ско́рбію порази́л м'я єси́; є́же позна́х і ка́яйся к Тебі́ прибіго́х, си́це моля́ся:","Го́споди мой, Го́споди, сохрани́вий м'я в ю́ності моє́й, сохрани́ м'я от враго́в, напа́дающих на м'я;","Го́споди мой, Го́споди, подкріпле́ніє ті́ла моєго́ в ста́рости моє́й, укріпи́ м'я ду́хом і ті́лом ізнемога́ющаго.","Го́споди мой, Го́споди, Наста́вниче мой, наста́ви м'я на путь спасе́нія;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 3","ps":["Си́льний во бра́ніх, Го́споди, прийди́ в по́мощ ізнемогающей душі́ моє́й і бу́ди мі засту́пник от враг ви́димих і неви́димих, я́ко оте́ць мой і ма́ти моя́ оста́виста м'я, дру́зі мої́ і і́скреннії мої́ дале́че от мене́ ста́ша. Но Ти, О́тче си́рих і Судіє́ вдови́ць, бу́ди мі безпомощному помо́щник, пою́щему Тебі́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй престо́л не́бо і подно́жіє зе́млю, Стра́шний, от'ємлющий дух князе́м, не отри́ни мене́, су́ща прах і пе́пел, но дерза́юща к Тебі́ Вездесущему і Всеведущему си́це глаго́лати:","Го́споди мой, Го́споди, воздви́гни си́лу Твою́ і прийди́ во є́же спасти́ м'я от руки́ си́льних і оби́дящих м'я;","Го́споди мой, Го́споди, Єго́ же вся боя́ться і трепе́щуть, пощади́ м'я, я́ко страх і тре́петь при́йде на м'я, і покри́ м'я тьма сме́ртная гріхо́в ра́ди мої́х.","Го́споди мой, Го́споди, одія́йся сві́том, я́ко ри́зою, просвіти́ м'я омраче́ннаго печа́льми жите́йськими;","Го́споди мой, Го́споди, простира́яй не́бо я́ко ко́жу, простри́ мі покро́в заступле́нія Твоєго́.","Го́споди мой, Го́споди, мир Твой да́руй смире́нній душі́ моє́й;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 4","ps":["Бу́рею многом'яте́жнаго сего́ житія́ потопля́єм, к Тебі́ ру́ці мої́ простира́ю, Сло́ве Бо́жий: я́ко же Петра́ утопа́ющаго спасл єси́, та́ко і мні простри́ крі́пкую ру́ку Твою́ і ізба́ви м'я біди́ сея́, да с ра́достію благода́рним се́рдцем вопію́ Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Усли́шах, Го́споди, глас Твой пресла́дкий, я́коже рекл єси́: призови́ М'я в день ско́рби твоєя́, і ізму́ тя, і просла́виши М'я; і із глубини́ отча́янія моєго́ со дерзнове́нієм приступи́ти к Тебі́ дерза́ю, глаго́ля:","Го́споди мой, Го́споди, согріши́х на не́бо і пред Тобо́ю, прийми́ м'я, я́коже блу́днаго си́на прия́л єси́;","Го́споди мой, Го́споди, митаря́ па́че фарисея оправда́вий, не вни́ди в суд с рабо́м Твої́м, я́ко не оправди́ться пред Тобо́ю всяк живи́й.","Го́споди мой, Го́споди, му́дрости наста́вниче, наста́ви м'я, раба́ Твоєго́;","Го́споди мой, Го́споди, сми́сла пода́телю, пода́ждь мі смисл, да возмогу́ ізбіжа́ти хитросплетенія і лука́ваго наві́та ненави́дящих м'я.","Го́споди мой, Го́споди, на смире́нния призира́яй, виждь і скорб мою́ і труд мой, і яви́ мі ми́лость Твою́;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 5","ps":["Богото́чною кро́вію возлю́бленнаго Си́на Твоєго́ Ісу́са Христа́ примирихся Тебі́, О́тче Небе́сний, но се па́ки я́коже пес на свою́ блево́тину ко гріху́ возврати́хся, сего́ ра́ди пра́ведно се́ю лю́тою бідо́ю наказу́єши м'я. Но усли́ши м'я, Го́споди Бо́же мой, в день печа́лі сея́, яви́ мні ми́лость і спасе́ніє Твоє́ і даждь мі в наказа́нії при́сно взива́ти Тебі́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя проро́к Дави́д проро́ка Нафа́на, облича́юща єго́ о соді́янних їм, при́йде в чу́вство і іспові́да свой гріх і рече́: согріши́х ко Го́споду, і усли́ша м'я Госпо́дь, і от'ят согріше́нія моя́. Аз же, окая́нний, па́че о́наго прегрешивий, плода́ покая́нія отню́дь не стяжа́х; сего́ ра́ди прийдо́ша на м'я зла́я сія́. Но Ми́лостив бу́ди мі, си́це моля́щуся:","Го́споди мой, Го́споди, укріпи́ м'я си́лою сви́ше, да не паду под тя́жестію ско́рби сея́;","Го́споди мой, Го́споди, на Єзекі́їни сле́зи ми́лостивно воззрі́вий, воззри́ о́ком благосердія Твоєго́ і на ізлія́ніє слез мої́х пред Тобо́ю.","Го́споди мой, Го́споди, Манассі́їни воздиха́нія усли́шавий, усли́ши моє́ воздиха́ніє серде́чноє;","Го́споди мой, Го́споди, во ви́шніх живи́й і на смире́нния призира́яй, при́зри на м'я грі́шнаго.","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 6","ps":["Пропові́дник покая́нія, Предте́ча Твой, Сло́ве Бо́жий, многократно вопіє́ть к со́вісти моє́й, да пока́юся от злих діл мої́х; но аз, окая́нний, пренебрегох о сем. Тім же пости́же м'я пра́ведний гнів Твой, біди́ бо і ско́рби нападо́ша на м'я, грі́шнаго; но Ти, Го́споди Бо́же, Спаси́телю мой, пре́жде да́же не посіти́ши м'я, да́руй мі вре́м'я, да пла́чуся злих мої́х і Тебі́ вопію́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в ско́рбі моє́й утешительноє сло́во Твоє́, Спаси́телю мой, є́же рекл єси́: \"Просі́те і да́сться вам\". А́біє ізбі́гнув тене́т отчаятія, с наде́ждою на Твоє́ человіколю́біє прибіго́х к Тебі́, та́ко моля́ся:","Го́споди мой, Го́споди, утіше́ніє моє́, уті́ши м'я в печа́лі су́щаго;","Го́споди мой, Го́споди, засту́пниче мой, заступи́ м'я от возстаю́щих на м'я.","Го́споди мой, Го́споди, по́моще моя́, помози́ мі, я́ко ізнемо́же душа́ моя́ от ско́рби сея́;","Го́споди мой, Го́споди, па́м'яте предві́чная, да́руй мі імі́ти всегда́ в па́м'яті благодія́нія Твоя́ і нікогда́же отча́ятися ми́лости Твоєя́.","Го́споди мой, Го́споди, крі́посте моя́, укріпи́ м'я без смуще́нія проси́ти от Теб'я́ по́мощі Твоєя́;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 7","ps":["Хотя́й іногда́ злочести́вий цар Навуходоно́сор погуби́ти о́троки, повелі́, да вве́ржені бу́дуть в пещ о́гненную; но Ти, О́тче Небе́сний, посла́л єси́ А́нгела Твоєго́, да остудить пла́мень горя́щий. Посли́ і ни́ні, Го́споди, утіше́ніє Твоє́ рабу́ Твоєму́, і спаси́ м'я ра́ди ми́лости Твоєя́. А́ще бо і согріши́х, но не отступи́х от Тебе́, і Тебі́ Єди́ному і І́стинному Бо́гу покланя́юся, поя́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно просла́вился єси́ во фарао́ні і во всем во́їнстві єго́, Бо́же Ізра́їлев, призрі́л бо єси́ на озлобле́ніє люде́й Твої́х, і вопль їх усли́шал єси́. Усли́ши у́бо і мою́ моли́тву і спаси́ м'я, си́це к Тебі́ вопію́щаго:","Го́споди мой, Го́споди, ізба́вивий лю́ди Твоя́ от руки́ враго́в їх, ізми́ і м'я із руки́ ненави́дящих м'я;","Го́споди мой, Го́споди, ізведи́й ізбра́нния Твоя́ із землі́ Єги́петськия, ізведи́ із ско́рби сея́ ду́шу мою́.","Го́споди мой, Го́споди, сокруши́вий бра́ні, сокруши́ зли́я наві́ти ми́слящих зла́я мні;","Го́споди мой, Го́споди, ізбра́нния і вса́дники потопи́вий в Чермні́м мо́рі, потопи́ мно́жество непра́вд мої́х в мо́рі милосе́рдія Твоєго́.","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 8","ps":["Стра́нна сотвори́х себі́ ми́лости Твоєя́, О́тче Небе́сний, зли́ми ді́ли удали́хся от Тебе́ і порабо́тихся су́єтному ми́ру сему́. Ті́мже і пожигаюся лю́тою ско́рбію, утопая в глубо́ких де́бріх отча́янія; но Ти, я́ко Милосе́рд і Человіколю́бець, прийми́ м'я, заблу́дшаго, і спаси́ м'я от біди́ сея́, Тебі́ вопію́ща: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь оскверне́н нечистото́ю гріхо́вною, в бе́здні зол погружаєм, к Тебі́ о́чі мої́, живу́щему на небесі́, возвожу́; усли́ши плаче́вний вопль мой;","Го́споди мой, Го́споди, просвіти́вий день сві́том со́лнечним, просвіти́ ду́шу мою́, тьмо́ю сує́ть ми́ра сего́ помраче́нную;","Го́споди мой, Го́споди, Преблаги́й Уті́шителю, іспо́лни боже́ственнаго утіше́нія грі́шную ду́шу мою́.","Го́споди мой, Го́споди, Єго́ же сло́вом небеса́ утверди́шася, утверди́ м'я во іспові́данії свята́го і́мене Твоєго́;","Го́споди мой, Го́споди, на Херуви́міх носи́мий і піва́ємий от Серафи́м, прийми́ от мене́, грі́шнаго, приноси́моє Тебі́ моле́ніє.","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 9","ps":["Вся́кия ми́лости Істо́чниче і сми́сла Пода́телю, о Преблаги́й Уті́шителю, наста́ви м'я, глаго́лати досто́йная пред Тобо́ю; ум же мой, печа́лію ми́ра сего́ смуща́ємий, і ду́шу мою́, помраче́нную страстьми́, іспо́лни боже́ственнаго Твоєго́ утіше́нія, да с весе́лієм воспою́ Тебі́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния не мо́гуть ізглаго́лати мно́жества бла́гости Твоєя́ і любве́ к ро́ду челові́чеському, Си́не Бо́жий; смири́л бо єси́ Себе́ до ра́бія зра́ка. Не отри́ни у́бо і мене́, без числа́ согріша́юща, оба́че со стра́хом предстоя́ща пред Тобо́ю і та́ко моля́щася:","Го́споди мой, Го́споди, Па́стирю до́брий, ду́шу Твою́ положи́вий за о́вці, ізба́ви м'я, заблудшеє овча́, от че́люсти душетлі́ннаго во́лка, зіяющия пожре́ти м'я;","Го́споди мой, Го́споди, нас ра́ди пору́ганний і убієнний і ко кресту́ пригвожде́нний, тіх ра́ди страда́ній Твої́х от поруга́ній ви́димих і неви́димих враго́в сохрани́ м'я.","Го́споди мой, Го́споди, безгрі́шний, со беззако́нними вмененний, ізми́ м'я із рук ненави́дящих м'я;","Го́споди мой, Го́споди, Єго́же я́звами всі ісцілі́хом, ісціли́ уя́звленноє го́рестію се́рдце моє́.","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й ізбра́ннаго Тобо́ю Ізра́їля от наси́лія єги́петськаго, воззва́л єси́ Мойсе́я, раба́ Твоєго́, із купини́ огнегорящия, і сія́ глаго́лал єси́ єму́: \"Ви́дя ви́діх озлобле́ніє люде́й Мої́х, і́же во Єги́пті, і вопль їх усли́шах\". При́зри у́бо і ни́ні, Го́споди, на озлобле́ніє моє́, і ісціли́ болі́знь се́рдця моєго́, да с благодарностію вопію́ Тебі́: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Небе́сний, Утешетелю, Душе́ і́стини, яви́ милосе́рдіє мні, рабу́ Твоєму́, і погруже́нную в печа́ль ду́шу мою́ посіти́ і укріпи́ м'я, та́ко Тебі́ моля́щася: Го́споди мой, Го́споди, Апо́столи научи́вий віща́ти іни́ми язи́ки, научи́ м'я стра́ху Твоєму́;","Го́споди мой, Го́споди, му́ченики пред мучи́телі дерзнове́нія іспо́лнивий, да́руй мі дерзнове́нно ста́ти проти́ву гріха́, ми́ра і дия́вола.","Го́споди мой, Го́споди, Святи́й Освятителю ві́рних Твої́х, освяти́ ду́шу мою́, да бу́деть досто́йна нарещи́ся домо́м Твої́м;","Го́споди мой, Го́споди, Сві́ті і сві́та Пода́телю, просвіти́ м'я, тьмо́ю ско́рби омраче́ннаго.","Го́споди мой, Го́споди, Сокро́вище благи́х, не лиши́ і мене́ даро́в бла́гости Твоєя́;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє Тебі́ принося́ща і сокруше́нним се́рдцем Тебі́ моля́щася, не пре́зри, о Преблаги́й Влади́ко; отврати́ у́бо лице́ Твоє́ от гріх мої́х, но не отврати́ лиця́ Твоєго́ от раба́ Твоєго́, я́ко скорблю́, ско́ро усли́ши м'я, пою́ща Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́те і́стинний, Христе́ Бо́же, просвіти́ омраче́нную страстьми́ ду́шу мою́ сві́том благода́ті Твоєя́, да с благогові́нієм молю́ся Тебі́, си́це глаго́ля:","Го́споди мой, Го́споди, не погуби́ мене́ окая́ннаго, не іму́ща ісправле́нія жи́зні, но дерзну́вша ста́ти пред Тобо́ю;","Го́споди мой, Го́споди, Теплото́ животво́рная, согрі́й м'я в ско́рбі сей ісчеза́ющаго.","Го́споди мой, Го́споди, сія́ніє сла́ви О́тчія, осія́й м'я сві́том заступле́нія Твоєго́;","Го́споди мой, Го́споди, творя́й А́нгели Своя́ ду́хи і слуги́ Своя́ пла́мень о́гненний, посли́ А́нгела Твоєго́, соблюда́юща м'я от вся́каго зла.","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 12","ps":["Благості ра́ди і любве́ к ро́ду челові́чеському, О́тче Небе́сний, посла́л єси́ Єдиноро́днаго Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, і́же на землі́ яви́ся і с челові́ки поживе́, посліди́ же, безгрі́шен Сий, со беззако́нними вміни́ся, і Своє́ю Кро́вію обнови́ растлі́нноє гріхо́м єстество́ на́ше, і весь мир пі́ти научи́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ неізрече́нноє человіколю́біє, Христе́ Бо́же, я́ко на́шего ра́ди спасе́нія крест і смерть претерпі́ти ізво́лил єси́, іспові́дую і правосу́діє Твоє́, я́ко і́стиною і судо́м наве́л єси́ на м'я скорб сію́, гріх ра́ди мої́х; но Ти, прише́дий призва́ти не пра́ведния, а грі́шния на покая́ніє, усли́ши м'я, па́че всіх грі́шнійшаго, си́це моля́щагося Тебі́:","Го́споди мой, Го́споди, А́гнче Бо́жий, взе́мляй гріхи́ ми́ра, возьми́ от мене́ бреме тя́жкоє гріхо́в мої́х;","Го́споди мой, Го́споди, я́ко А́гнець безгла́сен, на закла́ніє веденний, научи́ м'я терпі́ти находя́щая мні зла́я без ропта́нія.","Го́споди мой, Го́споди, Ада́мово рукописа́ніє раздра́вий, раздери́ рукописа́ніє безчи́сленних гріхо́в мої́х;","Го́споди мой, Го́споди, разбо́йниче покая́ніє приє́мий, прийми́ і моє́ грі́шнаго покая́ніє.","Го́споди мой, Го́споди, ме́ртвих воскреси́вий, воскреси́ ду́шу мою́, умерщвле́нную гріхми́;","Го́споди мой, Го́споди, па́дших возста́ніє, воздви́гни і м'я па́дшаго.","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 13","ps":["О, Премилосердний і Преблаги́й Го́споди Бо́же мой, Засту́пниче оби́димих і безнаде́жних наді́яніє, воззри́ о́ком благоутро́бія Твоєго́ на озлобле́ніє і скорб мою́, і спаси́ м'я ра́ди ми́лости Твоєя́, пою́ща Тебі́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче і Го́споди сил, спасе́нія ра́ди па́дшаго челові́ка не возгнуша́лся єси́ Девичеського Чре́ва, посліди́ же заплева́нія, поноше́нія і поно́сную смерть претерпі́л єси́, Сло́ве Бо́жий, благ бо єси́ і Человіколю́бець. Сіє́ помишля́я, дерза́ю приступи́ти к Тебі́ і со слеза́ми моли́тися:","Го́споди мой, Го́споди, милосе́рдий Спаси́телю мой, спаси́ м'я погиба́ющаго;","Го́споди мой, Го́споди, прише́дий не пра́ведния спасти́, но грі́шния, ізба́ви м'я от напа́сти сея́.","Го́споди мой, Го́споди, неду́ги на́ша приє́мий і болі́зні понеси́й, ісціли́ болі́зні се́рдця моєго́;","Го́споди мой, Го́споди, кресто́м Твої́м мир ми́ру Твоєму́ дарова́вий, ниспосли́ мир Твой смущенней душі́ моє́й.","Го́споди мой, Го́споди, Своє́ю сме́ртію смерть упраздни́вий, упраздни́ я́же на м'я ко́зні лука́ваго;","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Го́споди, ра́досте і весе́ліє рабо́м Твої́м, іді́же Ти, та́мо потребля́ється вся́кая печа́ль, іді́же ність Тебе́, та́мо вся́кая ра́дость су́єтна. При́зри на м'я грі́шнаго, погиба́ющаго в біді́ сей, і явле́нієм спасе́нія Твоєго́ посіти́ м'я, зову́ща:","Го́споди мой, Го́споди, ра́досте моя́, да́руй мі, да возра́дуюся о ми́лості Твоє́й."]},{"h":"Молитва перша","ps":["Го́споди, спаси́ м'я погиба́ющаго! Се, корабле́ць мой бі́дствуєть от іскуше́нія волн жите́йських і близ потопле́нія єсть; но Ти, я́ко Бог милосе́рдний і сострада́тельний не́мощем на́шим, вла́стію Твоє́ю всеси́льно запрети́ волне́нію бі́дствія, хотя́щих погрузи́ти м'я і низвести́ во глубину́ зол; і да бу́деть тишина́, я́ко ві́три і мо́ре послу́шають Тебі́. Амі́нь."]},{"h":"Інша молитва","ps":["Спаси́ м'я, Спа́се мой, по ми́лості Твоє́й, не по ді́лом мої́м. Ти хо́щеши м'я спасти́. Ти ві́си, ко́їм о́бразом спасти́ м'я. Спаси́ у́бо мене́, я́коже хо́щеши, я́коже мо́жеши, я́коже ві́си. І́миже ві́си судьба́ми, спаси́ м'я. Аз на Тя, Го́спода моєго́, наді́юся, і Твоє́й во́лі свято́й себі́ вруча́ю. Твори́ со мно́ю, є́же хо́щеши: а́ще хо́щеши м'я імі́ти во сві́ті, бу́ди благослове́н: а́ще хо́щеши м'я імі́ти во тьмі, бу́ди па́ки благослове́н. А́ще отве́рзеши мі милосе́рдія Твоєго́ две́рі, добро́ у́бо і бла́го; а́ще затвори́ши мі две́рі милосе́рдія Твоєго́, благослове́н єси́, Го́споди, затвори́вий мі по пра́вді. А́ще не погуби́ши м'я со беззако́ньми мої́ми, сла́ва безмі́рному милосе́рдію Твоєму́; а́ще погуби́ши м'я со беззако́ньми мої́ми, сла́ва пра́ведному суду́ Твоєму́: я́коже хо́щеши, устро́й о мні вещ. Амі́нь."]},{"h":"Тропар, глас 8","ps":["С ви́шніх призира́я, убо́гія приє́мля, посіти́ нас, озло́бленния гріхи́, Влади́ко Всеми́лостиве, моли́твами Богоро́диці да́руй душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 6","ps":["Вся́кия скве́рни, Всеми́лостивий Спа́се, аз бих ді́латель і во отча́янія ров впа́дся, но стеню́ от се́рдця і вопію́ к Тебі́, Сло́ве: ускори́, Ще́дрий, і потщи́ся на по́мощ на́шу, я́ко Ми́лостив."]}],"notes":[]},{"u":"Акафіст Архангелу Божому Михаїлу","e":"Akathist to the Archangel of God Michael","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Небе́сних сил воєво́до і ро́да челові́чеськаго засту́пниче, сіє́ тебі́ і́же тобо́ю от ско́рбних ізбавля́ємі, благода́рственноє прино́сим пі́ніє: ти же, я́ко предстоя́й Престо́лу Царя́ Сла́ви, от вся́ких нас бід свобожда́й, да с ві́рою і любо́вію в похвалу́ тебі́ зове́м:","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Ікос 1","ps":["Я́ко а́нгельських огнезра́чних лико́в предстоя́теля, а́нгельськими у́бо і язи́ки подоба́ше восхвали́ти тя, Михаї́ле: но до́ндеже вразумля́ємі тобо́ю нави́кнем безпло́тних глаго́лом, усли́ши, а́ще і от челові́чеських, оба́че благода́рних усте́н, сицева́я:","Ра́дуйся, звіздо́ ми́ра первообра́зная;","ра́дуйся, свіще́ і́стини і пра́вди златоза́рная.","Ра́дуйся, луче́й сві́та несозда́ннаго пе́рвий во а́нгельських ликостоя́ніях приє́мниче;","ра́дуйся, А́нгелов і Арха́нгелов нача́льниче.","Ра́дуйся, в не́мже найв'я́щше світле́ється сла́ва Тво́рчеськия Десни́ці;","ра́дуйся, і́мже красу́ються собо́ри всіх суще́ств безпло́тних.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 2","ps":["Прови́дяще ві́ри очеси́ вели́чіє духо́вния красоти́ і си́лу молнієно́сния десни́ці твоєя́, Арха́нгеле Бо́жий, ми, я́ко земні́ї і пло́тію обложе́ннії, удивле́нієм, ра́достію і благодаре́нієм ко Творцю́ вся́чеських ісполня́ємся, зову́ще со всі́ми Небе́сними си́лами: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум чист і свобо́ден от страсте́й іспроси́ нам, пречу́дний Михаї́ле, Небе́сних чино́в нача́льниче, да, возне́сшеся ми́слію от земни́х к Небе́сним, хвале́бную піснь воспоє́м ті си́це:","Ра́дуйся, Бо́жия неізре́ченния красоти́ і добро́ти ближа́йший зри́телю;","ра́дуйся, всеблаги́х сові́тов Пресвяти́я Тро́йці преі́скренній таї́нниче.","Ра́дуйся, преві́чних суде́б Тро́їчеських ві́рний ісполни́телю;","ра́дуйся, єму́же с любо́вію удивля́ються Небе́сная во́їнства.","Ра́дуйся, єго́же с ві́рою прославля́ють земноро́днії;","ра́дуйся, єго́же трепе́щуть а́дськия си́ли.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 3","ps":["Си́лу необори́мия ре́вности по сла́ві Бо́жієй в себі́ явля́я, стал єси́ во главі́ лико́в а́нгельських, Михаї́ле, проти́ву ди́шащаго зло́бою, прего́рдаго Денни́ці, єму́же со те́мними клевре́ти єго́ с висоти́ небе́сния в преіспо́днюю низве́ржену су́щу, во́їнства Небе́сная, тобо́ю пресла́вне води́мая, с весе́лієм, я́ко єди́ними усти́, пред Престо́лом Бо́жиїм возгласи́ша: Аллилу́я."]},{"h":"Ікос 3","ps":["І́мать тебі́, Арха́нгеле Михаї́ле, весь род христия́нський вели́ка засту́пника і ди́вна во бра́ніх с проти́вними помо́щника: сего́ ра́ди пречу́днаго покро́ва твоєго́ сподо́битися жела́юще, в день торжества́ твоєго́ взива́єм ті си́це:","Ра́дуйся, і́мже сатана́, я́ко мо́лнія, с Небесе́ низве́ржеся;","ра́дуйся, і́мже храни́мий род челові́чеський к Небесі́ восхо́дить.","Ра́дуйся, всесві́тлаго ми́ра Го́рняго преди́вноє украше́ніє;","ра́дуйся, па́дшаго ми́ра до́льняго пресла́вноє заступле́ніє.","Ра́дуйся, ніколи́же си́лами зла побежде́нний;","ра́дуйся, со всі́ми А́нгели Бо́жиїми в і́стині і пра́вді на ві́ки благода́тію Бо́жиєю утвержде́нний.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 4","ps":["Бу́ри іскуше́ній і бід ізба́ви нас, А́нгелов первопресто́льниче, с любо́вію і ра́достію пресві́тлоє торжество́ твоє́ соверша́ющих: ти бо єси́ в біда́х вели́кий помо́щник і в час сме́рти от злих духо́в храни́тель і засту́пник всіх вопію́щих твоєму́ і на́шему Влади́ці і Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дяще твоє́ проти́ву по́лчищ сатани́нських дерзнове́ніє, всі чи́нове а́нгельстії с ра́достію подвиго́шася во слід тебі́ на брань за і́м'я і сла́ву своєго́ Влади́ки, вопію́ще: кто я́ко Бог? Ми же, ві́дуще сатану́ под нога́ма твої́ма пове́ржена, тебі́, я́ко побіди́телю, зове́м:","Ра́дуйся, і́мже мир і тишина́ на Небесі́ водвори́шася;","ра́дуйся, от него́же ду́хове зло́би да́же до а́да низложи́шася.","Ра́дуйся, а́нгельськия во́їнства і си́ли ми́ра неви́димаго ко істребле́нію зла направля́яй;","ра́дуйся, прю і возмуще́ніє стихі́й ми́ра ви́димаго незри́мо укроща́яй.","Ра́дуйся, под'є́млющих брань к духово́м зло́би поднебе́сним ди́вний спобо́рниче;","ра́дуйся, ізнемога́ющих во іскуше́ніїх і напа́стіх ві́ка сего́ крі́пкий помо́щниче.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник превели́ких чуде́с яви́лся єси́ во хра́мі твоє́м, і́же в Хо́ніх; не то́чію бо змій вели́кий і стра́шний, на мі́сті том пребива́вий, си́лою твоє́ю потреби́ся, но і струї́ водни́я, вся́кий неду́г тіле́сний врачу́ющия, откри́шася, да всі прославля́ющему тя Влади́ці А́нгелов с ві́рою зову́ть: Аллилу́я."]},{"h":"Ікос 5","ps":["Сли́шаще і ві́дуще тя я́ко світи́ло вели́коє, посреді́ лико́в а́нгельських блиста́ющася, пречу́дний Михаї́ле, к тебі́, по Бо́зі і Пресвяті́й Ма́тері Бо́жієй, прибіга́єм: озари́ луча́ми сві́та твоєго́ всіх нас, вопію́щих ті си́це:","Ра́дуйся, вождю́ і храни́телю в пусти́ні наро́да богоізбра́ннаго;","ра́дуйся, висо́кий посре́дниче зако́на, руко́ю Моїсе́я на Сина́ї да́ннаго.","Ра́дуйся, у него́же судії́ і вожди́ Ізра́їлеви си́лу і покро́в обріта́ху;","ра́дуйся, чрез него́же проро́ци і первосвяще́нници іуде́йстії дар ві́дінія от всеве́дущаго Бо́га прийма́ху.","Ра́дуйся, богобоя́зненния законода́вці та́йною прему́дростію снабдіва́яй;","ра́дуйся, суд і пра́вду творя́щим бла́гость на се́рдці полага́яй.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 6","ps":["Провозві́стника тя Бо́жиїх суде́б єгда́ узрі́ ні́когда Мано́є, недоумі́нія і стра́ха іспо́лнися, мня не жи́ти ктому́ на землі́; науче́н же от жени́ своєя́ о бла́гости явле́нія і кро́тости слове́с твої́х, в ра́дості о іме́вшем роди́тися, по словесі́ твоєму́, си́ні своє́м Сампсо́не, благода́рні возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ пречу́дно сла́вою, Михаї́ле, єгда́ во о́бразі челові́честі пред Ісу́сом Нави́ном стал єси́, глаго́ля: Іззу́й сапо́г с ногу́ твоє́ю: аз єсьм Архистрати́г си́ли Госпо́дні. Таково́му явле́нію твоєму́ чудя́шеся, с любо́вію вопіє́м ті:","Ра́дуйся, боговінча́нних глав неуси́пний охрани́телю;","ра́дуйся, противля́ющихся вла́сті, я́ко Бо́жию повелі́нію проти́в'ящихся, ско́рий низложи́телю.","Ра́дуйся, усмири́телю наро́дних треволне́ній;","ра́дуйся, незри́мий упраздни́телю злочести́вих оби́чаєв.","Ра́дуйся, я́ко ти просвіща́єши сомня́щихся в час лю́тих недоумі́ній;","ра́дуйся, я́ко ти ісхища́єши іскуша́ємих от пагубоно́сних наважде́ній.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 7","ps":["Хотя́й Влади́ка вся́чеських показа́ти, я́ко жре́бії сино́в челові́чеських не самослуча́йнії суть, но в десни́ці Єго́ ви́ну содержа́ться, даде́ тя ца́рствам земни́м засту́пника і храни́теля, да племена́ і наро́ди к ві́чному Ца́рствію Бо́жию уготовля́єши; сего́ ра́ди всі, ві́дущії о вели́цім служе́нії твоє́м спасе́нію челові́чеському, благода́рні зову́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая чудеса́ показа́ нам, Архістрати́же, тобо́ю на землі́ всіх чуде́с Творе́ць і Влади́ка, єгда́ храм, во і́м'я твоє́ созда́нний, от потопле́нія вода́ми рі́чними ди́вно спасл єси́, струя́м пото́ка в ні́дра земна́я устреми́тися повелі́вий: є́же ви́дя блаже́нний Архи́пп с духо́вними ча́ди свої́ми, благода́рні к тебі́ возопи́:","Ра́дуйся, святи́х хра́мов Бо́жиїх несокруши́мая огра́до;","ра́дуйся, враго́м ві́ри Христо́ви необори́мая прегра́до.","Ра́дуйся, єго́же велі́нію стихі́ї покоря́ються;","ра́дуйся, і́мже всі зло́бнії за́мисли сокруша́ються.","Ра́дуйся, ві́рним ра́дость от Престо́ла Вседержи́теля ізнося́щий;","ра́дуйся, неві́рних на стезю́ пра́вди і і́стини приводя́щий.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до си́ли твоєя́, Архістрати́же Бо́жий, уві́де на себі́ Авваку́м, єгда́ по ма́нію Бо́жию восхи́тив, прине́сл єси́ єго́ скороте́чне от Іуде́ї во Вавило́н, да́ти пи́щу Данії́лу, в ро́ві со льви заключе́ну: ті́мже уди́влься превели́кому ді́йствію си́ли твоєя́, возопи́ с ві́рою: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ во ви́шніх, Михаї́ле, Престо́лу Царя́ Сла́ви предстоя́й, не дале́к єси́ і от ни́жніх, ра́туя ви́ну со врага́ми спасе́нія челові́чеськаго: ті́мже всі вожделі́ннаго Оте́чества Небе́снаго дости́гнути хотя́щії согла́сно тебі́ зову́ть:","Ра́дуйся, нача́льниче трисвята́го а́нгельськаго пі́нія;","ра́дуйся, земноро́дних при́сно гото́вий предста́телю і храни́телю.","Ра́дуйся, прего́рдаго фарао́на с неві́рними єги́птяни порази́вий страннообра́зно;","ра́дуйся, ві́рния іуде́ї путеводи́вий в пусти́ні пресла́вно.","Ра́дуйся, і́мже угаси́ся пла́мень пещі́ вавило́нськия;","ра́дуйся, і́мже посрами́шася ко́зні бісо́вськия.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 9","ps":["Всі і́ноці Святи́я Гори́ Афо́нськия в ра́достний тре́петь прийдо́ша, ви́дяще, ка́ко богобоя́зненна о́трока, неі́стовно от нечести́вих златолю́бцев во глубину́ морську́ю с ка́мнем пове́ржена, спасл єси́: ті́мже прия́вшая єго́ оби́тель, і́менем твої́м красу́ющися, благода́рні взива́єть ко Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й глаго́ли і любому́дров сми́сли не довлі́ють ко ізглаго́ланію си́ли твоєя́, Михаї́ле, ка́ко во єди́ну нощ сто о́смдесят і п'ять ти́сящ порази́л єси́ от во́єв царя́ ассирі́йська Сеннахири́ма, да нака́жеться про́чеє не хули́ти і́м'я Госпо́днє: ми же, почита́юще святу́ю ре́вность твою́ о сла́ві Бо́га І́стиннаго, с весе́лієм зове́м ті си́це:","Ра́дуйся, правосла́вних во́їнств непобіди́мий воєво́до;","ра́дуйся, злові́рних ра́тей страх і низложе́ніє.","Ра́дуйся, пра́вия ві́ри і богопочита́нія насади́телю;","ра́дуйся, душевре́дних єресе́й і раско́лов іскорени́телю.","Ра́дуйся, благочести́вия Маккаве́ї на по́лі бра́ні мно́гажди укріпи́вий;","ра́дуйся, нечести́ваго вождя́ Антіо́хова Іліодо́ра в самі́м хра́мі порази́вий.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим нам бу́ди помо́щник тверд, Архістрати́же Бо́жий, ізбавля́яй і храня́й нас от бід і напа́стей, па́че же от злих на́виков і гріхо́в на́ших, да, преспіва́юще во ві́рі, наде́жде і любві́ Христо́ві, с ра́достію о преди́внем заступле́нії твоє́м, ко Влади́ці А́нгелов і челові́ков благода́рні зове́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ві́рующим челові́ком, Архістрати́же Бо́жий, і столп крі́пок во бра́ніх со врага́ми ви́димими і неви́димими: сего́ ра́ди от сіте́й бісо́вських тобо́ю ізбавля́ємі, благода́рним се́рдцем і усти́ зове́м си́це:","Ра́дуйся, враго́м ві́ри і сопроти́вником Святи́я Це́ркве непобіди́мий противобо́рниче;","ра́дуйся, смире́нним провозве́стником Єва́нгелія неутоми́мий споспі́шниче.","Ра́дуйся, во тьмі злові́рія сідя́щих сві́том ві́ри Христо́ви просвіща́яй;","ра́дуйся, лжему́дрієм об'юро́девших на стезю́ і́стини і покая́нія наставля́яй.","Ра́дуйся, гро́зний отмсти́телю кляну́щимся і́менем Бо́жиїм всу́є;","ра́дуйся, молнієно́сний кара́телю глум'я́щихся безу́мне о та́їнствіх святи́я ві́ри.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє хвале́бноє побіжда́ється мно́жеством чуде́с твої́х, Архістрати́же Бо́жий, я́ко соверше́на суть тобо́ю не то́чію на Небесі́ і на землі́, но і в те́мних сі́ніх преіспо́дней, іді́же глуби́ннаго змі́я связа́л єси́ у́зами си́ли Госпо́дней, да ізбавля́ємії от зло́би єго́ благослов'я́ть Влади́ку Небесе́ і землі́, зову́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сний служи́тель і́стини і чистоти́ богопочита́нія яви́лся єси́, Архістрати́же, єгда́, прови́дя ко́зні ду́ха тьми, воспрети́л єси́ єму́ і́менем Бо́жиїм, да не де́рзнеть сокрове́нноє ті́ло почи́вшаго вождя́ Ізра́їлева Моїсе́я яви́ти ко обо́женію чу́вственним синово́м Ізра́їлевим: сего́ ра́ди, чту́ще ни́ні благосве́тлий собо́р твой, благода́рні вопіє́м ті:","Ра́дуйся, чистоту́ богові́дінія во дні Ве́тхаго Заві́та среди́ іуде́єв сохрани́вий;","ра́дуйся, пле́вели заблужде́ній во дні Но́вия благода́ті мно́гажди іскорени́вий.","Ра́дуйся, язи́чеських прориця́лищ і куми́ров істреби́телю;","ра́дуйся, христия́нських подви́жников і страстоте́рпцев укріпи́телю.","Ра́дуйся, немощни́я ду́хом си́лою благода́ті Бо́жієй ісполня́яй;","ра́дуйся, ізнемога́ющия пло́тію всеору́жієм ві́ри облека́яй.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га с Небесе́ іспроси́ нам, пою́щим во сла́ву всечестна́го іме́не твоєго́, Михаї́ле, да, осіня́ємі твої́м заступле́нієм, во вся́ком благоче́стії і чистоті́ поживе́м, до́ндеже, отреше́ннії сме́ртію от уз пло́ті, сподо́бимся предста́ти огнезра́чному Престо́лу Царя́ Сла́ви і с ли́ки а́нгельськими возопи́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще многообра́зная твоя́ чудеса́, Михаї́ле, во спасе́ніє на́ше соді́янная, мо́лим Го́спода і Влади́ку вся́чеських, да дух ре́вности по сла́ві Бо́жієй, і́же в тебі́, ніколи́же оскуді́єть і в нас, зову́щих ті си́це:","Ра́дуйся, ві́рних рабо́в Бо́жиїх во вре́м'я благопотре́бно на висоту́ вла́сті преди́вне поставля́яй;","ра́дуйся, проде́рзих і недосто́йних с висоти́ си́ли і сла́ви незри́мо низлага́яй.","Ра́дуйся, в день послі́дній ізбра́нних от чети́ріх конце́в землі́ імі́яй собра́ти;","ра́дуйся, і́мже грі́шния, я́ко пле́вели, по гла́су Бо́жию, огню́ ві́чному преда́ни бу́дуть.","Ра́дуйся, і́мже сатана́ со а́нгели єго́ во є́зеро о́гненноє на ві́ки пове́ргнеться;","ра́дуйся, і́мже пра́веднії во оби́теліх Отця́ Небе́снаго пресла́вне водворя́ться.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 13","ps":["О пречу́дний Арха́нгелов і А́нгелов нача́льниче, за преди́вноє служе́ніє твоє́ спасе́нію ро́да челові́чеськаго прийми́ от нас возноси́мий к тебі́ ни́ні глас хвали́ і благодаре́нія, і я́ко іспо́лнь си́ли Бо́жієй, покри́й нас невеще́ственнима крило́ма твої́ма от всіх враг ви́димих і неви́димих, да прославля́ємому тобо́ю і просла́вившему тя Го́споду ви́ну зове́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Я́ко а́нгельських огнезра́чних лико́в предстоя́теля, а́нгельськими у́бо і язи́ки подоба́ше восхвали́ти тя, Михаї́ле: но до́ндеже вразумля́ємі тобо́ю нави́кнем безпло́тних глаго́лом, усли́ши, а́ще і от челові́чеських, оба́че благода́рних усте́н, сицева́я:","Ра́дуйся, звіздо́ ми́ра первообра́зная;","ра́дуйся, свіще́ і́стини і пра́вди златоза́рная.","Ра́дуйся, луче́й сві́та несозда́ннаго пе́рвий во а́нгельських ликостоя́ніях приє́мниче;","ра́дуйся, А́нгелов нача́льниче.","Ра́дуйся, в не́мже найв'я́щше світле́ється сла́ва Тво́рчеськия Десни́ці;","ра́дуйся, і́мже красу́ються собо́ри всіх суще́ств безпло́тних.","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Кондак 1","ps":["Ізбра́нний Небе́сних сил воєво́до і ро́да челові́чеськаго засту́пниче, сіє́ тебі́ і́же тобо́ю от ско́рбних ізбавля́ємі, благода́рственноє прино́сим пі́ніє: ти же, я́ко предстоя́й Престо́лу Царя́ Сла́ви, от вся́ких нас бід свобожда́й, да с ві́рою і любо́вію в похвалу́ тебі́ зове́м:","Ра́дуйся, Михаї́ле, вели́кий Архістрати́же, со всі́ми Небе́сними си́лами."]},{"h":"Молитва","ps":["Святи́й і вели́кий Арха́нгеле Бо́жий Михаї́ле, неісповіди́мия і пресу́щественния Тро́йці пе́рвий во А́нгеліх предстоя́телю, ро́да же челові́чеськаго приста́вниче і храни́телю, сокруши́вий с во́їнстви свої́ми главу́ прего́рдаго денни́ці на небесі́ і посрамля́яй ви́ну зло́бу і кова́рства єго́ на землі́! К тебі́ прибіга́єм с ві́рою і тебі́ мо́лимся с любо́вію: бу́ди щит несокруши́м і забра́ло тве́рдо Святі́й Це́ркві і Правосла́вному Оте́чествію на́шему, огражда́я їх молнієно́сним мече́м твої́м от всіх враг, ви́димих і неви́димих. Не оста́ви же, о Арха́нгеле Бо́жий, по́мощію і заступле́нієм твої́м і нас, прославля́ющих днесь свято́є і́м'я твоє́: се бо, а́ще і многогрі́шни єсьми́, оба́че не хо́щем в беззако́ніїх на́ших поги́бнути, но є́же обрати́тися ко Го́споду і оживле́нним би́ти от Него́ на діла́ блага́я. Озари́ у́бо ум наш сві́том лиця́ Бо́жия, і́же ви́ну сія́єть на молнієви́днем челі́ твоє́м, да возмо́жем разумі́ти, что єсть во́ля Бо́жия о нас блага́я і соверше́нная, і ві́діти вся, я́же подоба́єть нам твори́ти і я́же презира́ти і оставля́ти. Укріпи́ благода́тію Госпо́днею сла́бую во́лю і немощно́є проізволе́ніє на́ше, да, утверди́вшеся в зако́ні Госпо́днем, преста́нем про́чеє вла́ятися земни́ми по́мисли і похоті́нії пло́ті, увлека́ющеся, по подо́бію несми́сленних діте́й, скороги́бнущими красо́тами ми́ра сего́, я́ко ра́ди тлі́ннаго і земна́го безу́мне забива́ти ві́чная і небе́сная. Над всі́ми же си́ми іспроси́ нам Сви́ше дух і́стиннаго покая́нія, нелицемі́рную печа́ль по Бо́зі і сокруше́ніє о грісі́х на́ших, да остаю́щеє нам число́ дній вре́меннаго живота́ на́шего іждиве́м не во угожде́нії чувств і рабо́ті страсте́м на́шим, но во ізглажде́нії зол, соді́янних на́ми, слеза́ми ві́ри і сокруше́нія серде́чнаго, по́двигами чистоти́ і святи́ми діла́ми милосе́рдія. Єгда́ же прибли́зиться час оконча́нія на́шего, освобожде́нія от уз бре́ннаго сего́ тілесе́, не оста́ви нас, Арха́нгеле Бо́жий, беззащи́тних проти́ву духо́в зло́би поднебе́сних, оби́кших прегражда́ти душе́ челові́честій восхо́д в го́рняя, да, охраня́ємі тобо́ю, безпреткнове́нні дости́гнем о́них пресла́вних селе́ній ра́йських, іді́же ність печа́ль, ні воздиха́ніє, но жизнь безконе́чная, і, сподо́бльшеся узрі́ти пресві́тлоє лице́ Всеблага́го Го́спода і Влади́ки на́шего, па́дше со слеза́ми у ног Єго́, в ра́дості і умиле́нії воскли́кнем: сла́ва Тебі́, дража́йший Іскупи́телю наш, І́же за премно́гую любо́в Твою́ к нам, недосто́йним, благоволи́л єси́ посла́ти А́нгели Твоя́ в служе́ніє спасе́нію на́шему! Амі́нь."]},{"h":"Тропар, глас 4","ps":["Небе́сних во́їнств Архістрати́же, / мо́лим тя при́сно ми недосто́йнії, / да твої́ми моли́твами огради́ши нас / кро́вом крил невеще́ственния твоєя́ сла́ви, / сохраня́я нас, припа́дающих прилі́жно і вопію́щих: / от бід ізба́ви нас, // я́ко чинонача́льник ви́шніх Сил."]},{"h":"Кондак, глас 2","ps":["Архістрати́же Бо́жий, / служи́телю Боже́ственния сла́ви, / А́нгелов нача́льниче і челові́ков наста́вниче, / поле́зноє нам проси́ і ве́лію ми́лость, // я́ко Безпло́тних Архістрати́г."]},{"h":"Величання","ps":["Велича́єм вас, Арха́нгели і А́нгели і вся во́їнства, Херуви́ми і Серафи́ми, сла́в'ящия Го́спода."]}],"notes":[]},{"u":"Акафіст святим Безплотним силам","e":"Akathist to the Holy Bodiless Powers","secs":[{"h":"Кондак 1","ps":["Святі́ї Безпло́тнії си́ли, у Престо́ла Вседержи́теля предстоя́щії і непреста́нно трисвяту́ю піснь Єму́ вопію́щії, досто́йно ублажи́м і восхва́лим вас, ско́рих моли́твенников і засту́пников на́ших во вся́ких ну́ждах і печалях, і с благодаре́нієм вопіє́м вам си́це:","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Ікос 1","ps":["Святі́ї Серафи́ми, Херуви́ми, Престо́ли і Вла́сті, Госпо́дствія, Си́ли і Нача́ла, Арха́нгели і А́нгели, любо́вію ко Го́споду і Творцю́ непреста́нно горя́щії, і всім нам спасти́ся хотя́щії, сего́ ра́ди ми вам, грі́шнії, воспіва́ти дерза́єм:","Ра́дуйтеся, пресла́вниє Серафи́ми і Херуви́ми;","Ра́дуйтеся, победоносниє Престо́ли, Госпо́дствія і Си́ли.","Ра́дуйтеся, богомудриє Вла́сті і Нача́ла;","Ра́дуйтеся, пресветлиє Арха́нгели і А́нгели су́щії от нача́ла.","Ра́дуйтеся, слуги́ Бо́жії непоколеби́мії;","Ра́дуйтеся, Влади́ки Христа́ дру́ги ві́рнії.","Ра́дуйтеся, святі́ї посла́нници Бо́жії;","Ра́дуйся, і ти, святи́й А́нгеле-Храни́телю мой.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 2","ps":["«Ста́нем до́брі, ста́нем со стра́хом Бо́жиїм!» - возгласи́л єси́, Архістрати́же Михаї́ле, увлекая за собо́ю во́їнство Небе́сноє проти́ву па́дшаго Денни́ці і сокруши́л єси́ го́рдаго, сего́ ра́ди вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["До́брий і бесстрашний Воєво́до во́їнства Небе́снаго, Арха́нгеле Михаї́ле, се бо непоколеби́мо предстої́ши пред Престо́лом Царя́ царе́й го́ря любо́вію ко Го́споду і помога́єши нам низлага́ти вся́коє малоду́шіє і го́рдость, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, о си́лі Бо́жієй громогласно возвіща́ющий;","Ра́дуйся, от страхова́ній вра́жиїх ізбавля́ющий.","Ра́дуйся, мечом ре́вности по Бо́гу на дьявола, я́ко льва рикающего, вооружающий;","Ра́дуйся, сатану́ стра́хом я́ко гро́мом поражающий.","Ра́дуйся злослов'ящим І́м'я Госпо́днє і рабо́в Бо́жиїх гро́зноє отмще́ніє;","Ра́дуйся, му́чеников і іспові́дников Христо́вих утвержде́ніє.","Ра́дуйся, ізгна́нних пра́вди ра́ди благослове́ніє;","Ра́дуйся, Архістрати́же Михаї́ле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 3","ps":["Шестокрилатиє Серафи́ми, я́ко зві́зди лучезарниє пла́менем любве́ к Созда́телю неуста́нно горя́щії, попалі́те на́ші стра́сті, да вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["І́же Серафи́ми, скве́рни греховниє на́ші єще́ іздале́ча пожигающії і любо́вію к Бо́гу се́рдця ісполня́ющії, сего́ ра́ди вопіє́м вам си́це:","Ра́дуйтеся, от жестосе́рдія ізбавля́ющії;","Ра́дуйтеся, любо́в і милосе́рдіє істоча́ющії.","Ра́дуйтеся, всепроще́нієм Бо́жиїм ка́ющихся грі́шников укрепляющії;","Ра́дуйтеся, духовниє ра́ни їх ісціля́ющії.","Ра́дуйтеся, я́ко стра́жи в пла́менних доспехах любві́ Бо́жієй на тве́рди Небе́сній незиблимо пребива́ющії;","Ра́дуйтеся, о ми́рі і благоде́нствії на землі́ Бо́га моля́щії.","Ра́дуйтеся, шестокрилатиє Серафи́ми;","Ра́дуйтеся, сокрушители адськой си́ли.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 4","ps":["Многоочитиє Херуви́ми, си́ли і му́дрости Бо́жієй ісполненниє, научі́те нас і́стинному покая́нію, да вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["І́же Херуви́ми, та́йнам Пресвято́й Тро́йці служа́щії і богопознанію нас научающії, сего́ ра́ди вопіє́м вам си́це:","Ра́дуйтеся, лжемудрованія я́ко грозними сіки́рами правдой Бо́жієй отсекающії;","Ра́дуйтеся, смиренному́дріє насаждающії.","Ра́дуйтеся, прему́дрости Бо́жієй научающії;","Ра́дуйтеся, душевниє о́чі незри́мо храня́щії.","Ра́дуйтеся, я́ко Небесниє колесни́ци к позна́нію Бо́га вознося́щії;","Ра́дуйтеся, «Свят,Свят,Свят Госпо́дь Савао́ф» немо́лчно вопію́щії.","Ра́дуйтеся, многоочитиє Херуви́ми;","Ра́дуйтеся, усмирители вся́кой горди́ні.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 5","ps":["Огненниє Престо́ли, непостижи́мо Самого́ Бо́га нося́щії і раболе́пно Єму́ служа́щії, утверді́те нас во іспові́данії свято́й ві́ри правосла́вной, да вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["І́же Престо́ли, Небесниє Уми́, ве́ліє дерзнове́ніє ко Го́споду Вседержи́телю іму́щії і правосу́дію Єго́ вершиться помога́ющії, сего́ ра́ди вопіє́м вам си́це:","Ра́дуйтеся, от лі́ності і нераде́нія охраняющії;","Ра́дуйтеся, лука́вство істребляющії.","Ра́дуйтеся, спаси́тельному стра́ху Бо́жию научающії;","Ра́дуйтеся, тве́рдою боже́ственною ре́вностію я́ко гро́зним всеору́жієм пилающії.","Ра́дуйтеся, я́ко огненниє столпи́ для судо́в Бо́жиїх поставленниє;","Ра́дуйтеся, всі́ми ві́рними прославляємиє.","Ра́дуйтеся, могущественниє Престо́ли;","Ра́дуйтеся, побіди́телі вся́кой зло́би.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 6","ps":["«Ра́дуйся Благода́тная, Госпо́дь с Тобо́ю!» - благовіствова́л єси́, Арха́нгеле Гавриї́ле, Влади́чице Богоро́дице та́йну воплоще́нія Си́на Бо́жия, сего́ ра́ди вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Сокровенниє та́йни Бо́жії, Арха́нгеле Гавриї́ле, челові́чеському ро́ду открива́єши і се́рдця на́ші святи́м смире́нієм і весе́лієм духо́вним ісполня́єши, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, в смире́ніє я́ко в панцир облекающий;","Ра́дуйся, к благородству духо́вному причащающий.","Ра́дуйся, в небесниі сво́ди путе́м смире́нія восходить указу́ющий;","Ра́дуйся, ро́ду людсько́му благові́стієм о воплоще́нії Бо́га-Сло́ва к Присноді́ві Марі́ї послужи́вший.","Ра́дуйся, к созерца́нію Нетва́рнаго сві́та привлече́ніє;","Ра́дуйся, апо́столов Христо́вих укріпле́ніє.","Ра́дуйся, миротво́рцев благослове́ніє;","Ра́дуйся, Арха́нгеле Гавриї́ле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 7","ps":["От Бо́га, для явле́нія Єго́ любві́ і милосе́рдія к лю́дем по́слан бил єси́, Арха́нгеле Рафаї́ле, к Тові́ї, да ісціли́ши отця́ єго́ Тови́та і Са́рру от неду́гов тіле́сних і душе́вних, сего́ ра́ди вопіє́м Пресвято́й Животворя́щей Тро́йці: Аллилу́я."]},{"h":"Ікос 7","ps":["Арха́нгеле Рафаї́ле, от болі́зней душе́вних і тіле́сних нас ісціля́єши і ожесточенниє се́рдця милосе́рдієм ісправля́єши, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, благочести́вих бра́ков устрої́тель чу́дний;","Ра́дуйся, ісціле́ніє от болі́зней і неду́гов да́рующий.","Ра́дуйся, діла́м милосе́рдія помогающий;","Ра́дуйся, я́ко пла́менним щито́м от самолю́бія і сладостра́стія огражда́ющий.","Ра́дуйся, воздержа́нію науча́ющий;","Ра́дуйся, безме́здников Христо́вих ра́дованіє.","Ра́дуйся, ми́лостивих благослове́ніє;","Ра́дуйся, Арха́нгеле Рафаї́ле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 8","ps":["«Како́й сосу́д вмісти́ть в себ'я́ путь Всеви́шняго?» - та́ко, Арха́нгеле Уріїле, вразумля́л єси́ Єздру, да позна́єть прему́дрость Бо́жию, сего́ ра́ди вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Сві́том Бо́жиїм, Арха́нгеле Уріїле, от тьми єресе́й нас просвіща́єши і позна́нію і́стини во Христі́, Го́споді на́шем, науча́єши, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, вся́коє лука́вство я́коже із лу́ка стріла́ми сві́та і́стини і пра́вди Бо́жієй поражающий;","Ра́дуйся, ві́рних в житії́ честно́м і цілому́дренном созидающий.","Ра́дуйся, вся́кий блуд тіле́сний і духо́вний я́ко молнієй істребляющий;","Ра́дуйся, побі́ду над неві́рієм да́рующий.","Ра́дуйся, в і́стинном правосла́вії утвержде́ніє;","Ра́дуйся, святи́телей Христо́вих умудреніє.","Ра́дуйся, чи́стих се́рдцем благослове́ніє;","Ра́дуйся, Арха́нгеле Уріїле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 9","ps":["Бо́гом к погиба́ющим от зно́я в пусти́ні безво́дній А́гари і о́троку по́слан бил єси́, Арха́нгеле Селафіїле, да ко колодезю путь їм пока́жеши і спасе́ши от лютой сме́рти, сего́ ра́ди вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Чи́стой моли́тві к Бо́гу, Арха́нгеле Селафіїле, нас науча́єши і ближнего по за́повіді Госпо́дней проща́ти призива́єши, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, в лати кро́тости сопроти́в кня́зя тьми облекающий;","Ра́дуйся, стра́стний огнь пам'ятозло́бія угашающий.","Ра́дуйся, о́браз Бо́жий в бли́жнем показу́ющий;","Ра́дуйся, к сострада́нію, долготерпі́нію і проще́нію тім преклоняющий.","Ра́дуйся, покро́в от бра́ней і упокоє́ніє;","Ра́дуйся, преподо́бних Христо́вих утіше́ніє.","Ра́дуйся, кротцих благослове́ніє;","Ра́дуйся, Арха́нгеле Селафіїле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 10","ps":["Рече́ Госпо́дь Савао́ф, рабу́ Своєму́ Мойсе́ю: «І́м'я Моє́ на нем» - та́ко ти Арха́нгеле Ієгудіїле, сугу́бо от Него́ просла́влен єси́, сего́ ра́ди велича́єм тя і почита́єм служе́ніє твоє́ наро́ду Ізраїльському, я́ко ше́ствовал пред ним для покоре́нія землі́ Ханаанськой і вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Неутоми́мий ревни́телю сла́ви Бо́жієй, Арха́нгеле Ієгудіїле, от стра́сті уни́нія і лі́ності ізбавля́єши і пра́ведно сла́вити Го́спода Ісу́са Христа́ науча́єши, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, я́ко звізда́ у́тренняя, от тьми уни́нія просвіща́ющий;","Ра́дуйся, малові́ріє і безволіє от рабо́в Бо́жиїх я́ко о́стрим копіє́м прободающий і отгоня́ющий.","Ра́дуйся, тобо́ю, в му́жественноє трезві́ніє облекаємся;","Ра́дуйся, тобо́ю, от лука́вих внушеній і пре́лести духо́вной очища́ємся.","Ра́дуйся, от духо́в зло́би поднебе́сних охранитель сла́вний;","Ра́дуйся, пра́ведних защи́титель си́льний.","Ра́дуйся, а́лчущих і жа́ждущих пра́вди благослове́ніє;","Ра́дуйся, Арха́нгеле Ієгудіїле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 11","ps":["Благослове́ніє от Бо́га, Арха́нгеле Варахіїле, всім ві́рним на вся́коє ді́ло благо́є посила́єши, да научі́мся діла́м богоуго́дним і вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Пред Господом Вседержи́телем, Арха́нгеле Варахіїле, предстої́ши і на всіх путеіх спасе́нія нас защища́єши, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, богопроти́внаго злата́го тельця́ сокрушающий;","Ра́дуйся, в сві́тлую броню́ нестяжа́нія облекающий.","Ра́дуйся, за усо́пших молиться напоминающий;","Ра́дуйся, всім ві́рним ра́дость духо́вную да́рующий.","Ра́дуйся, великоду́шних странноприїмцев покрови́телю чу́дний;","Ра́дуйся, о Христа́ ра́ди юро́дивих попечи́телю ди́вний.","Ра́дуйся, ни́щих ду́хом благослове́ніє;","Ра́дуйся, Арха́нгеле Варахіїле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 12","ps":["«Всеви́шній на ві́сах взвесил вік сей» - та́ко умудрял єси́, Арха́нгеле Ієреміїле, Єздру, да позна́єть суєтность ми́ра сего́, і вопіє́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["К покая́нію се́рдця на́ші хладниє, Арха́нгеле Ієреміїле, приклоняєши, - да омоємся, я́ко дожде́м покая́нними і сокрушенними слеза́ми о соді́янних грехах і удалимся от печа́лі по тлі́нному ми́ру сему́, сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, к отверзающему Небеса́ покаянному і спаси́тельному пла́чу о грехах, преклоняющий;","Ра́дуйся, от геє́нни о́гненной спаса́ющий.","Ра́дуйся, безу́міє ми́ра сего́, палицей ві́дінія про́мисла Бо́жия сокрушающий;","Ра́дуйся, мудростью духо́вной ра́зум напоя́ющий.","Ра́дуйся, стезей ко Го́споду ісправле́ніє;","Ра́дуйся, проро́ков Бо́жиїх возвише́ніє.","Ра́дуйся, пла́чущих благослове́ніє;","Ра́дуйся, Арха́нгеле Ієреміїле, на́ше умиле́ніє.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 13","ps":["О свято́є Небе́сноє во́їнство, про́сим вас ми, гріхми́ отягченниє, да не поги́бнем в беззако́ніях на́ших, но молі́те Го́спода за нас, да пощади́ть, і поми́луєть, і спасе́ть нас по вели́цій Своє́й ми́лості, сего́ ра́ди вопіє́м Єму́: Аллилу́я","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Святі́ї Серафи́ми, Херуви́ми, Престо́ли і Вла́сті, Госпо́дствія, Си́ли і Нача́ла, Арха́нгели і А́нгели, любо́вію ко Го́споду і Творцю́ непреста́нно горя́щії, і всім нам спасти́ся хотя́щії, сего́ ра́ди ми вам, грі́шнії, воспіва́ти дерза́єм:","Ра́дуйтеся, пресла́вниє Серафи́ми і Херуви́ми;","Ра́дуйтеся, победоносниє Престо́ли, Госпо́дствія і Си́ли.","Ра́дуйтеся, богомудриє Вла́сті і Нача́ла;","Ра́дуйтеся, пресветлиє Арха́нгели і А́нгели су́щії от нача́ла.","Ра́дуйтеся, слуги́ Бо́жії непоколеби́мії;","Ра́дуйтеся, Влади́ки Христа́ дру́ги ві́рнії.","Ра́дуйтеся, святі́ї посла́нници Бо́жії;","Ра́дуйся, і ти, святи́й А́нгеле-Храни́телю мой.","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Кондак 1","ps":["Святі́ї Безпло́тнії си́ли, у Престо́ла Вседержи́теля предстоя́щії і непреста́нно трисвяту́ю піснь Єму́ вопію́щії, досто́йно ублажи́м і восхва́лим вас, ско́рих моли́твенников і засту́пников на́ших во вся́ких ну́ждах і печалях, і с благодаре́нієм вопіє́м вам си́це:","Ра́дуйтеся, всі святі́ї Безпло́тнії си́ли."]},{"h":"Молитва","ps":["О, святі́ї Безпло́тнії си́ли, воззрі́те ми́лостивно на нас грі́шних і не возгнушайтесь на́шими скве́рнами. Но умолі́те Го́спода Ісу́са Христа́, да не поги́бнем ми в пучи́ні беззако́ній на́ших, но в ти́хую гавань спасе́нія при́йдем. Єму́ же подоба́єть сла́ва со Безнача́льним Єго́ Отце́м і Святи́м Ду́хом во ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Небе́сних во́їнств Архістрати́зі, / мо́лим вас при́сно ми недосто́йнії, / да ва́шими моли́твами оградите́ нас / кро́вом крил невеще́ственния ва́шея сла́ви, / сохраня́юще ни припа́дающия прилі́жно і вопію́щия: / от бід ізба́віте ни, // я́ко чинонача́льници ви́шніх Сил."]},{"h":"Кондак, глас 2","ps":["Архістрати́зі Бо́жії, / служи́теліє Боже́ственния сла́ви, / А́нгелов нача́льници, і челові́ков наста́вници, / поле́зноє нам просі́те, і ве́лію ми́лость, // я́ко Безпло́тних Архістрати́зі."]},{"h":"Величання","ps":["Велича́єм вас, / Арха́нгели і А́нгели / і вся во́їнства, / Херуви́ми і Серафи́ми, // сла́в'ящия Го́спода."]}],"notes":[]},{"u":"Акафіст усім святим, що від віку Богу догодили","e":"Akathist to All the Saints Who Have Pleased God from the Ages","secs":[{"h":"Кондак 1","ps":["Ізбра́нним уго́дником Бо́жиїм, всім святи́м, от ві́ка во всем ми́рі просія́вшим і на небесі́ вінці́ сла́ви прия́вшим, похва́льноє прино́сим пі́ніє. Ви же, я́ко іму́щії ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́те, да зове́м вам хвале́бно:","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Ікос 1","ps":["А́нгельський собо́р, ума́ленний паде́нієм го́рдих а́нгел і ва́ми, всі́ми святи́ми, восполня́ємий, сві́тло торжеству́єть в день па́м'яті ва́шей, і всю вселе́нную созива́єть на весе́ліє духо́вноє. Ми же, їм подража́юще, зове́м вам ра́достно:","Ра́дуйтеся, святі́ї, от ві́ка Бо́гом предуве́деннії і предуста́вленнії к сла́ві небе́сній;","ра́дуйтеся, от всіх родо́в, міст і време́н в служе́ніє Го́споду ізбра́ннії.","Ра́дуйтеся, ізбра́ніє ва́ше по́двигами благоче́стія оправда́вшії;","ра́дуйтеся, о́бразом до́брих діл ва́ших пра́вий путь к небесі́ нам показа́вшії.","Ра́дуйтеся, пре́жде пи́саннаго зако́на Бо́жия по зако́ну со́вісти пра́ведно пожи́вшії;","ра́дуйтеся, в зако́нній сі́ні благоче́стно житіє́ своє́ соверши́вшії.","Ра́дуйтеся, в но́вій благода́ті сві́тло доброді́тельми просія́вшії;","ра́дуйтеся, в послі́дняя сія́ времена́ Бо́гу благоугоди́вшії і мзду с пе́рвими получи́вшії.","Ра́дуйтеся, от земни́х скорбе́й преше́дшії к небе́сному поко́ю;","ра́дуйтеся, сподо́бльшіїся зрі́ти неісповіди́мую сла́ву Бо́жию.","Ра́дуйтеся, с ли́ки безпло́тних непреста́нно хва́лящії Пресвяту́ю Тро́йцю;","ра́дуйтеся, всегда́ моля́щіїся Єй о всіх почита́ющих вас.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 2","ps":["Ви́дящи Правосла́вная Христо́ва Це́рков, многочи́сленними ли́ки святи́х, я́ко прекра́сними ра́йськими цві́ти себі́ укра́шену, сві́тло почита́єть па́м'ять їх і Пречи́стую Богома́тер с Ро́ждшимся от Нея́ Христо́м Бо́гом велича́єть, вопію́щи Тому́ хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зуму на́шему просвіще́ніє у Го́спода іспросі́те, святі́ї уго́дниці Бо́жії, да отря́сши земно́є пристра́стіє, вознесе́мся се́рдцем і ми́слію в насле́дованная ва́ми і нам обіща́нная селе́нія ра́йськая, і возопіє́м вам ра́достно:","Ра́дуйтеся, ветхозаве́тнії пра́отці і патріа́рсі, родонача́льници по пло́ті Христа́ Си́на Бо́жия;","ра́дуйтеся, я́ко благослове́нієм Бо́жиїм умно́жишася ро́ди ва́ша, я́ко зві́зди небе́сния.","Ра́дуйтеся, среди́ мра́ка дре́вняго нече́стія пра́вую ва́шу ві́ру во і́стиннаго Бо́га сохрани́вшії;","ра́дуйтеся, с наде́ждою ча́явшії обітова́ннаго Іскупи́теля.","Ра́дуйтеся, я́ко от ва́шего пле́мене возсія́ пресві́тлая свіща́ — Богоро́диця Марі́я;","ра́дуйтеся, я́ко от Нея́ роди́ся Побіди́тель сме́рти і а́да.","Ра́дуйтеся, ві́рою во гряду́щаго Христа́ спасе́ніє улучи́вшії;","ра́дуйтеся, вмі́сто дре́внія кля́тви благослове́ніє тім получи́вшії.","Ра́дуйтеся, і во а́ді Христо́ва прише́ствія ожида́вшії;","ра́дуйтеся, а́дських муче́ній Їм ізба́вленнії.","Ра́дуйтеся, на небеса́ со сла́вою возведе́ннії;","ра́дуйтеся, с ли́ки а́нгельськими во ві́чния оби́телі Отця́ Небе́снаго вселе́ннії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго осенени́ би́вше, святі́ї, дерзнове́нно ополчи́стеся проти́ву нача́л і власте́й зло́би поднебе́сния, і побіди́вше тіх кова́рства, вся блага́я начина́нія ва́ша до́брі соверши́сте, воспіва́юще всеси́льному человіколю́бцю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще святі́ї проро́ци пресла́вная селе́нія во оби́теліх до́му Отця́ Небе́снаго і присносу́щним сві́том лиця́ Бо́жия просвіща́ємі, неізрече́ннаго воі́стину со всі́ми святи́ми наслажда́єтеся блаже́нства, єго́же ми земні́ї прича́стници би́ти жела́юще, воспіва́єм вам си́це:","Ра́дуйтеся, святі́ї проро́ци, Бо́гом ізбра́ннії пре́жде ва́шего рожде́нія;","ра́дуйтеся, ві́рно порабо́тавшії Єму́ пре́жде Христо́ва воплоще́нія.","Ра́дуйтеся, от младе́нчества благода́тію Свята́го Ду́ха освяще́ннії;","ра́дуйтеся, по́сланнії от Го́спода вразумля́ти заблу́ждшия си́ни Ізра́їлеви.","Ра́дуйтеся, предвозвісти́вшії Христо́во от Ді́ви сла́вноє рожде́ніє;","ра́дуйтеся, зві́зди, предвари́вшії прише́ствіє і́стиннаго Со́лнця.","Ра́дуйтеся, законопресту́пних царе́й Ізра́їлевих дерзнове́нно обличи́вшії;","ра́дуйтеся, вся́коє людсько́є нече́стіє мече́м сло́ва Бо́жия неща́дно посе́кшії.","Ра́дуйтеся, ві́рнії раби́ Госпо́дні, вся хоті́нія Єго́ іспо́лнившії;","ра́дуйтеся, і́стину небоя́зненно пред властьми́ веща́вшії.","Ра́дуйтеся, мно́гі ско́рбі в ми́рі претерпі́вшії;","ра́дуйтеся, со всі́ми ізбра́нними торжеству́ющії на небесі́ в сла́ві ві́чній.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 4","ps":["Бу́ри жите́йськія ізба́вльшеся, всі святі́ї, прейдо́сте в небе́сний поко́й, на міста́ зла́чна і прохла́дна, іді́же пото́ци сла́дости неісповіди́мия, пи́ща сла́ви Бо́жия нетлі́нная, пі́нія і гла́си пра́зднующих; та́мо у́бо торжеству́єте со всі́ми а́нгельськими си́лами, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["О́ко не ви́ді і у́хо не сли́ша, і на се́рдці земна́го челові́ка не взидо́ша ра́дости і сла́дости, ї́хже ви ни́ні наслажда́єтеся, Апо́столи святі́ї. Сего́ ра́ди благогові́йно взива́єм вам:","Ра́дуйтеся, святі́ї Апо́столи, с Предте́чею Іоа́нном ближа́йшії дру́зі Христо́ви;","ра́дуйтеся, по Пресвято́й Ді́ві Марі́ї, первостоя́теліє у Престо́ла Святи́я Тро́йці.","Ра́дуйтеся, возвісти́вшії ми́ру та́їнство на́шего іскупле́нія;","ра́дуйтеся, сві́том ві́ри Христо́ви омраче́нния лю́ди просвіти́вшії.","Ра́дуйтеся, сі́м'я сло́ва Бо́жия в сердця́ челові́чеськая все́явшії;","ра́дуйтеся, плоди́ трудо́во ва́ших в небе́сном вертогра́ді пожина́ющії.","Ра́дуйтеся, святі́ї отці́, седьмію́ вселе́нськими собо́ри іспові́даніє правосла́вния ві́ри утверди́вшії;","ра́дуйтеся, ути́шившії бу́рю єреті́чеськаго нече́стія.","Ра́дуйтеся, із'ясни́вшії нам догма́ти правосла́вния ві́ри;","ра́дуйтеся, і дони́ні уче́нієм ва́шим огражда́ющії Це́рков Христо́ву от єресе́й і раско́лов.","Ра́дуйтеся, святі́ї ієра́рсі, сло́вом і житіє́м сві́тло просія́вшії;","ра́дуйтеся, во сві́ті невече́рнім с духо́вними ва́шими ча́ди ни́ні обита́ющії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 5","ps":["Богото́чною, Спа́се, Кро́вію Твоє́ю іскупле́ннії і ві́рно Тебі́ на землі́ послужи́вшії всі святі́ї, ни́ні на тве́рди церко́вній я́ко зві́зди пресві́тлия сія́ють, і всіх нас, по мо́рю стра́стнаго сего́ житія́ пла́вающих, на путь пра́вий, к небе́сному оте́честву веду́щий, наставля́ють; о сем у́бо с ра́достію благода́рно поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши святі́ї му́ченици, я́ко в ми́рі сем вся су́єтна суть і тлі́нію прича́стна, потща́стеся предве́чному Бо́гу благоугоди́ти і претерпі́нієм лю́тих мук тлі́нная на нетлі́нная преміни́ти, за є́же сподо́бистеся предстоя́нія у стра́шнаго Престо́ла Влади́чня в сла́ві ві́чній, в не́йже не забу́діте і нас, па́м'ять ва́шу соверша́ющих і вопію́щих вам такова́я:","Ра́дуйтеся, святі́ї страстоте́рпці, кро́вію своє́ю запечатле́вшії пра́вую ва́шу во Христа́ ві́ру;","ра́дуйтеся, не убоя́вшіїся убива́ющих ті́ло, душі́ же не могу́щих уби́ти.","Ра́дуйтеся, претерпі́вшії стра́шная муче́нія;","ра́дуйтеся, я́вльшії на себі́ Христо́вих страсте́й ізображе́нія.","Ра́дуйтеся, побіди́вшії лю́тих мучи́телей свирі́пства;","ра́дуйтеся, чрез огнь і во́ду проше́дшії і в поко́й ві́чний вше́дшії.","Ра́дуйтеся, іспові́дниці і священному́ченици, пострада́вшії за благоче́стіє і почита́ніє святи́х іко́н;","ра́дуйтеся, преподобному́ченици, в моли́тві Бо́гу собесе́довавшії і страда́нієм дия́вола попра́вшії.","Ра́дуйтеся, за сла́ву і честь Царя́ Небе́снаго му́жественно во́їнствовавшії;","ра́дуйтеся, побі́дную по́честь от Христа́ на небесі́ приі́мшії.","Ра́дуйтеся, ве́лію благода́ть от Го́спода получи́вшії;","ра́дуйтеся, мно́гая і разли́чная чудеса́ в сла́ву Бо́жию в поднебе́сній содіва́ющії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 6","ps":["Пропові́дують христия́нстії ро́ди сла́ву ва́шу, всі святі́ї; ви бо я́ко рай насажде́нний яви́стеся посреді́ Це́ркве, іму́щії дре́во жи́зні Сама́го Го́спода, от него́ же вкуси́вше сла́дости ра́йськия, вся скороги́бнущая в ми́рі сем презрі́сте, і ра́достно в небе́сний вертогра́д внидо́сте, пою́ще: Аллилу́я."]},{"h":"Ікос 6","ps":["Правові́ріє і доброді́телі преподо́бних оте́ць, я́ко со́лнце, всему́ ми́ру сія́ють і нам мра́чний путь жи́зні сея́ просвіща́ють, да не заблуди́м в пусти́ні гріха́ і душепа́губних єресе́й. Сего́ ра́ди хвале́бно їм воспіва́єм:","Ра́дуйтеся, преподо́бнії отці́, мир і я́же в ми́рі любве́ ра́ди Бо́жия во́лею оста́вившії;","ра́дуйтеся, преподо́бнії ма́тері, в по́двизіх дневни́х і нощни́х земно́є тече́ніє соверши́вшії.","Ра́дуйтеся, пусти́нници, в пеще́рах і гора́х со звірми́ пожи́вшії;","ра́дуйтеся, по́стници, в а́лчбі і жа́жді вре́менноє житіє́ препроводи́вшії.","Ра́дуйтеся, сто́лпници, мраз і зной Ца́рствія ра́ди Небе́снаго претерпі́вшії;","ра́дуйтеся, затво́рници, в серде́чній тишині́ Бо́га взиска́вшії.","Ра́дуйтеся, ді́вственници, целому́дріє сохрани́вшії і непоро́чному А́гнцю Христу́ послі́довавшії;","ра́дуйтеся, послу́шници, Христо́во смире́ніє стяжа́вшії.","Ра́дуйтеся, в общежи́тіїх во взаї́мной бра́тськой любві́ а́нгельськи пожи́вшії;","ра́дуйтеся, му́дрії і кро́тції мона́хов наста́вници би́вшії.","Ра́дуйтеся, всі трудолю́бці, доброді́телей соверше́нство стяжа́вшії;","ра́дуйтеся, в поко́й Го́спода своєго́ вше́дшії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 7","ps":["Хотя́ Всеблаги́й Госпо́дь яви́ти ми́ру, я́ко не всу́є тружда́ються всі благоугожда́ющії Єму́, но я́ко ве́лія мзда угото́вася їм в Ца́рствії Небе́снім; сего́ ра́ди просла́ви со́нми святи́х уго́дник Свої́х, разли́чні тому́ на землі́ послужи́вших; да і ми поревну́єм тіх житію́, і тоя́ же ві́чния сла́ви ча́юще, поє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["«Ві́руяй в М'я, а́ще і у́мреть жив бу́деть»,— рече́ Госпо́дь. Вам же, святі́ї всі, ізря́дно прили́чествують сі́ї Влади́чни глаго́ли; ви бо а́ще і умро́сте на землі́ пло́тію, но душа́ми во ви́шнім селе́нії всегда́ жи́ви су́ще, мно́гая і неізрече́нная соверша́єте в ми́рі чудеса́, і те́плим ва́шим к Бо́гу хода́тайством посо́бствуєте нам, си́це возглаша́ющим вам:","Ра́дуйтеся го́рняя му́дрствующим ва́шим умо́м і́стиннаго Бо́га позна́вшії;","ра́дуйтеся, пра́вую ва́шу в Святу́ю Тро́йцю ві́ру непоро́чно сохрани́вшії.","Ра́дуйтеся, Христа́ Си́на Бо́жия, і́стиннаго Бо́га і соверше́ннаго Челові́ка іспові́давшії;","ра́дуйтеся, в спаси́тельния Єго́ стра́сті несумні́нно ві́ровавшії.","Ра́дуйтеся, правосла́вієм, я́ко зві́зди, блиста́ющії;","ра́дуйтеся, пра́ведностію, я́ко фі́нікс процвіта́ющії.","Ра́дуйтеся, пло́тію на землі́, умо́м же на небесі́ пожи́вшії;","ра́дуйтеся, вре́менною сме́ртію на безконе́чную жизнь преше́дшії.","Ра́дуйтеся, ті́сним путе́м єва́нгельськи ше́ствовавшії;","ра́дуйтеся, у́зькими врати́ Ца́рствія Небе́снаго дости́гшії.","Ра́дуйтеся, ві́чних благ наслі́дници;","ра́дуйтеся, о спасе́нії на́шем те́плії к Бо́гу хода́таї.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 8","ps":["Страну́ ону́ го́рнюю, іді́же всі святі́ї по труді́х земни́х почива́ють, у́мним очесе́м свої́м представля́юще, а́ще і не мо́жем пости́гнути су́щаго та́мо блаже́нства, ми земні́ї і пло́тію обложе́ннії, оба́че, ві́рою сіє́ проразуміва́юще і се́рдцем предвкуша́юще, поє́м ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Ісчита́яй мно́жество звізд і всім їм імена́ нариця́яй, Вседержи́телю Го́споди, Ти єди́н ві́си по і́мені всіх благоугоди́вших Тебі́. Ми же, ді́ло су́ще руку́ Твоє́ю, я́коже песка́ морська́го ісчести́, си́це і всіх святи́х по і́мені нарещи́ не могу́ще, то́кмо ізря́днейшия раби́ Твоя́, от нача́ла ми́ра Тебі́ благоугоди́вшия, імену́єм, глаго́люще:","Ра́дуйтеся, Ада́ме і Є́во, пра́отці всего́ ро́да челові́чеськаго;","ра́дуйтеся, А́велі і Си́фе, пе́рвії в ми́рі благоче́стія рачи́теліє.","Ра́дуйтеся, Но́є, втори́й ро́да на́шего родонача́льниче, і Авраа́ме, заві́та Бо́жия приє́мниче;","ра́дуйтеся, Мойсе́є богови́дче і Ааро́не, пе́рвий ветхозаве́тний свяще́нниче.","Ра́дуйтеся, Єно́ше і Іліє́, пло́тію сме́рті невкуси́вшії і на не́бо восхище́ннії;","ра́дуйтеся, Іса́їє, Дави́де і Данії́ле, зри́теліє та́їн Бо́га Вседержи́теля.","Ра́дуйтеся, Іоаки́мі і А́нно, роди́вшії Ді́ву Марі́ю, Ма́тер Христа́ Бо́га на́шего;","ра́дуйтеся, Пе́тре, Па́вле, Іа́кове і Іоа́нне, ізбра́ннійшії Апо́столи Христо́ви.","Ра́дуйтеся, Нико́лає, Васи́ліє, Григо́ріє, Іоа́нне і Афана́сіє, непоколеби́мії столпи́ це́ркве Христо́ви;","ра́дуйтеся, Анто́ніє, Пахо́міє, Євфи́міє, Іларіо́не і Са́вво, вели́кіє мона́хов наста́вници.","Ра́дуйтеся, Гео́ргіє, Дими́тріє, Євстра́тіє і Пантелеї́моне, вели́ції му́ченици Христо́ви;","ра́дуйтеся, Варва́ро, Іри́но, Параске́во, Єкатери́но і всі му́ченици, кро́вію своє́ю торжество́ ві́ри возвели́чившії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 9","ps":["Всі святі́ї Твої́, Го́споди, а́нгельський подража́я чин, безпреста́ни сла́в'ять Пресвято́є І́м'я Твоє́ на небесі́, «Свят, свят, свят», — вопію́ще; с ни́ми же і ми грі́шнії на землі́ бре́нними устна́ми вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї суєму́дрия недоумі́ють глаго́лати: ка́ко ви, всі святі́ї, подобостра́стії нам би́вше челові́ци, непреодоле́ни страстьми́ би́сте, му́жеством ва́шим безпло́тния враги́ побіди́сте. Ми же, прославля́юще укріпи́вшаго вас Го́спода, хва́лим до́блести ва́ша і умиле́нно вопіє́м:","Ра́дуйтеся, святі́ї, вседу́шно Го́спода возлюби́вшії;","ра́дуйтеся, любве́ Єго́ ра́ди живота́ своєго́ не щади́вшії.","Ра́дуйтеся, мир і миродержи́теля побіди́вшії;","ра́дуйтеся, вся сі́ті дре́вняго змі́я я́ко паучи́ну разори́вшії.","Ра́дуйтеся, смири́вшіїся под крі́пкую ру́ку всеблага́го про́мисла Бо́жия;","ра́дуйтеся, покори́вшії во́лю свою́ во́лі Отця́ Небе́снаго.","Ра́дуйтеся, просла́вившії Го́спода в душа́х і тілесі́х ва́ших;","ра́дуйтеся, возвели́чившії Єго́ во всіх ді́ліх ва́ших.","Ра́дуйтеся, воздвиза́вшії ру́ці ва́ші на творе́ніє діл благи́х;","ра́дуйтеся, направля́вшії стопи́ ва́ша на путь пра́вий.","Ра́дуйтеся, не приложи́вшії серде́ць ва́ших к земно́му бога́тству і наслажде́нію;","ра́дуйтеся, всегда́ помишля́вшії о бла́гах небе́сних і ві́чном весе́лії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 10","ps":["Спасе́нія путе́м пра́во ше́ствующе і о судьба́х пра́вди Бо́жия поуча́ющеся, всі святі́ї, яви́стеся я́ко древеса́ благопло́дная при ісхо́дищах вод, і принесо́сте Бо́гу плод доброді́телей ва́ших во вре́м'я своє́. Ни́ні же в го́рнем Єде́ме неізрече́ннаго наслажда́ющеся блаже́нства, пом'яні́те і нас, чад ва́ших, оте́чеськоє ва́ше о спасе́нії на́шем попече́ніє восхваля́ющих, Бо́гу же пою́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда нам проти́ву лиця́ вра́жия ви єсте́, всі святі́ї, і те́плії моли́твенниці ко Христу́ о всем ро́де христия́нстім. Ті́мже от стріл неви́димаго бори́теля при́сно ва́ми защища́ємі, ра́достно взива́єм:","Ра́дуйтеся, ро́да челові́чеськаго ве́ліє украше́ніє;","ра́дуйтеся, в стра́нствії земно́м при́сная нам отра́да і утіше́ніє.","Ра́дуйтеся, в бра́ні со врага́ми спасе́нія на́шего си́льнії нам помо́щници;","ра́дуйтеся, от меча́ гні́ва Бо́жия моли́твами ва́шими нас защища́ющії.","Ра́дуйтеся, са́мі іскуше́ни би́вше, і нам во іскуше́ніїх помога́ющії;","ра́дуйтеся, покая́нію нас грі́шних зіло́ ра́дующіїся.","Ра́дуйтеся, на разли́чних мі́стіх землі́ во вся времена́ пра́ведно пожи́вшії;","ра́дуйтеся, а́ще і согріши́вшії, оба́че і́стинним покая́нієм і слеза́ми скве́рну гріхо́в оми́вшії.","Ра́дуйтеся, от Ада́ма да́же до днесь в наде́жді жи́зні ві́чния сконча́вшіїся;","ра́дуйтеся, от Восто́ка і За́пада прише́дшії і на ло́ні Авраа́мли почи́вшії.","Ра́дуйтеся, я́ко сонм ваш но́вими с землі́ прише́льцями всегда́ умножа́ється;","ра́дуйтеся, я́ко ва́ми мі́сто па́дших духо́во в собо́рі а́нгельськом восполня́ється.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 11","ps":["Пі́сні на́ша хвале́бния, а́ще би і тьмочи́слени би́ли, не довлі́ють к прославле́нію доброді́телей ва́ших, всі святі́ї; і нам немощни́м удо́біє люби́ти молча́ніє; но да не яви́мся ліни́ви і неблагода́рни за полу́ченния вас ра́ди ми́лости і благодія́нія Бо́жия, поє́м просла́вльшему вас Влади́ці: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льници сві́та невече́рняго ви єсте́, всі святі́ї, у Престо́ла Пресвяти́я Тро́йці с а́нгельськими чи́ньми в моли́тві о нас присногоря́щії, і на сві́тлую спасе́нія стезю́ наставля́ющії вопію́щих вам си́це:","Ра́дуйтеся, світи́льници огня́ невеще́ственнаго;","ра́дуйтеся, насе́льници оби́телей Отця́ Небе́снаго.","Ра́дуйтеся, гро́здіє виногра́да Христо́ва;","ра́дуйтеся, благоуха́ннії цві́ти ра́йстії.","Ра́дуйтеся, живото́чнії рі́ки, в жа́жді духо́вній нас напоя́ющії;","ра́дуйтеся, дождено́снії о́блаці, в зно́ї іскуше́ній нас прохлажда́ющії.","Ра́дуйтеся, духо́внії ві́три, зи́му уни́нія от серде́ць на́ших прогоня́ющії;","ра́дуйтеся, сладкопе́снивії сла́вії, духо́вную ве́сну ві́чнаго блаже́нства нам возвеща́ющії.","Ра́дуйтеся, ми́сленния го́ри, к небесі́ нас возводя́щії;","ра́дуйтеся, у́мнаго Со́лнця лучи́, ми́лость Єго́ на нас ізлива́ющії.","Ра́дуйтеся, до́брії ко́рмчії, от потопле́нія гріхо́внаго нас спаса́ющії;","ра́дуйтеся, ві́рнії путевожді́є, в небе́сноє оте́чество нас путеводя́щії.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 12","ps":["Благода́ть, от Бо́га да́нную вам во воздая́ніє мно́гих доброді́телей ва́ших, кто от земноро́дних іспові́сти возмо́жеть, о святі́ї! Я́коже бо ка́плі морськи́я по єди́ной ісчерпа́ти, си́це чудоді́йствій ва́ших і подава́ємих ва́ми нам благодія́ній ність мо́щно ісчести́. Сего́ ра́ди ра́достно соверша́єм сла́вноє ва́ше торжество́, і вся ді́йствующему во вас Го́споду зове́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Тя, Влади́ко Вседержи́телю, восхваля́єм всі Пресвято́є І́м'я Твоє́, я́ко от нача́ла ми́ра в разли́чная времена́ яви́л єси́ приснопа́м'ятния святи́я Твоя́, Тебі́ єди́ному в Тро́йці сла́вимому Бо́гу благоугоди́вшия, ї́хже моли́твами от всіх зол ізбавля́єши вопію́щия к ним:","Ра́дуйтеся, святі́ї Бо́жії уго́дниці с Пресвяте́йшею всея́ тва́рі Присноді́вою Марі́єю;","ра́дуйтеся, і ви, безпло́тнії а́нгели, храни́теліє ро́да челові́чеськаго.","Ра́дуйтеся, святі́ї ца́ріє і кня́зі, на землі́ благочести́во ца́рствовавшії і Небе́сноє Ца́рствіє насле́дившії;","ра́дуйтеся, до́брії градоправи́теліє, в небе́сном гра́де обита́ти сподо́бльшіїся.","Ра́дуйтеся, нелицеприя́тнії земні́ї судії́, у небе́снаго Судії́ оправда́ніє і ми́лость получи́вшії;","ра́дуйтеся, ре́вностнії слове́сних ове́ць па́стиріє, от Пастиренача́льника Христа́ похвале́ннії і просла́вленнії.","Ра́дуйтеся, пра́веднії земледе́лателіє, в простоті́ се́рдця і незло́бії Бо́гу послужи́вшії;","ра́дуйтеся, терпіли́вії стра́нници, небе́снаго оте́чества дости́гшії.","Ра́дуйтеся, юро́дивії, поноше́нія і укоре́нія Христа́ ра́ди претерпі́вшії;","ра́дуйтеся, безсре́бренници, ту́не боля́щим ісціле́нія подава́вшії і на небесі́ мзду прия́вшії.","Ра́дуйтеся, во вся́ком возрасте́ і зва́нії угоди́вшії Бо́гу му́жіє і жени́, я́ко ви єди́но єсте́ о Го́споді і ду́ші ва́ша в руці́ Бо́жієй;","ра́дуйтеся, я́ко в бу́дущем ві́ці ку́пно с душа́ми і тілеса́ ва́ша ві́чния сла́ви прича́стни бу́дуть.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 13","ps":["О всеблаже́ннії уго́дниці Бо́жії, всі святі́ї, прия́вшії наслі́діє благ ві́чних! Приймі́те сіє́ на́ше хвале́бноє пі́ніє, і благоприя́тними ва́шими к Бо́гу моли́твами іспросі́те нам гріхо́в оставле́ніє і ві́чних мук ізбавле́ніє, да с ва́ми в небе́сном на́шем Оте́честві поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський собо́р, ума́ленний паде́нієм го́рдих а́нгел і ва́ми, всі́ми святи́ми, восполня́ємий, сві́тло торжеству́єть в день па́м'яті ва́шей, і всю вселе́нную созива́єть на весе́ліє духо́вноє. Ми же, їм подража́юще, зове́м вам ра́достно:","Ра́дуйтеся, святі́ї, от ві́ка Бо́гом предуве́деннії і предуста́вленнії к сла́ві небе́сній;","ра́дуйтеся, от всіх родо́в, міст і време́н в служе́ніє Го́споду ізбра́ннії.","Ра́дуйтеся, ізбра́ніє ва́ше по́двигами благоче́стія оправда́вшії;","ра́дуйтеся, о́бразом до́брих діл ва́ших пра́вий путь к небесі́ нам показа́вшії.","Ра́дуйтеся, пре́жде пи́саннаго зако́на Бо́жия по зако́ну со́вісти пра́ведно пожи́вшії;","ра́дуйтеся, в зако́нній сі́ні благоче́стно житіє́ своє́ соверши́вшії.","Ра́дуйтеся, в но́вій благода́ті сві́тло доброді́тельми просія́вшії;","ра́дуйтеся, в послі́дняя сія́ времена́ Бо́гу благоугоди́вшії і мзду с пе́рвими получи́вшії.","Ра́дуйтеся, от земни́х скорбе́й преше́дшії к небе́сному поко́ю;","ра́дуйтеся, сподо́бльшіїся зрі́ти неісповіди́мую сла́ву Бо́жию.","Ра́дуйтеся, с ли́ки безпло́тних непреста́нно хва́лящії Пресвяту́ю Тро́йцю;","ра́дуйтеся, всегда́ моля́щіїся Єй о всіх почита́ющих вас.","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Кондак 1","ps":["Ізбра́нним уго́дником Бо́жиїм, всім святи́м, от ві́ка во всем ми́рі просія́вшим і на небесі́ вінці́ сла́ви прия́вшим, похва́льноє прино́сим пі́ніє. Ви же, я́ко іму́щії ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́те, да зове́м вам хвале́бно:","Ра́дуйтеся, всі святі́ї, те́плії о всем ми́рі Бо́гу моли́твенниці."]},{"h":"Молитва","ps":["К вам, о святі́ї всі, я́ко путево́дним світи́льником, дія́ньми свої́ми освети́вшим путь небе́снаго восхо́да, аз, многогрі́шний, смире́нно колі́на се́рдця моєго́ преклоня́ю і із глубини́ душі́ взива́ю: умолі́те о мні Человіколю́бця Бо́га, да не попу́стить мі єще́ блужда́ти по распу́тіям гріха́, но да просвіти́ть мой ум і се́рдце сві́том бла́гости Своєя́, я́ко да то́ю озаря́єм і подкріпля́єм, возмогу́ про́чеє вре́м'я земна́го житія́ пра́вою стезе́ю непреткнове́нно прейти́ і хода́тайством ва́шим ко Всеблаго́му Го́споду сподо́блюся поне́ вма́лі прича́стник би́ти духо́вния ва́шея трапе́зи в небе́снім черто́зі Царя́ сла́ви, Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м, Благи́м і Животворя́щим Ду́хом бу́ди сла́ва, честь і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І́же во всем ми́рі му́ченик Твої́х, / я́ко багряни́цею і ви́ссом, / кровми́ Це́рков Твоя́ украси́вшися, / ті́ми вопіє́ть Ті Христе́ Бо́же: / лю́дем Твої́м щедро́ти Твоя́ низпосли́, / мир жи́тельству Твоєму́ да́руй, // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Я́ко нача́тки єстества́, Насади́телю тва́рі, / вселе́нная прино́сить Ті Го́споди богоно́сния му́ченики. / Тіх моли́твами в ми́рі глубо́ці Це́рков Твою́, // жи́тельство Твоє́, Богоро́дицею соблюди́ Многоми́лостиве."]},{"h":"Величання","ps":["Велича́єм вас, апо́столи, му́ченици, проро́ци і всі святі́ї, і чтим святу́ю па́м'ять ва́шу, ви бо мо́лите за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст про упокоєння спочилих","e":"Akathist for the Repose of the Departed","secs":[{"h":"Кондак 1","ps":["Непостижи́мим про́мислом ко бла́гу ві́чному мир уготовля́яй, челові́ком времена́ і о́браз кончи́ни опреділи́вий, оста́ви, Го́споди, от ві́ка уме́ршим вся согріше́нія їх, прийми́ я во оби́телі сві́та і ра́дованія, об'я́тія О́тчі отве́рсти їм потщи́ся і усли́ши ни, па́м'ять їх совершающия і пою́щия:","Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Ікос 1","ps":["Ада́ма па́дшаго і весь род челові́чеський от ві́чния поги́белі спаса́яй, посла́л єси́, Бла́же, в мир Си́на Твоєго́, Кресто́м бо і Воскресе́нієм Єго́ возсія́ і нам Живо́т Ві́чнующий. На безмі́рноє Твоє́ милосе́рдіє упова́юще, ча́єм нетлі́ннаго Ца́рствія Сла́ви Твоєя́, усо́пшим дарова́ти того́ про́сим і мо́лим Ті ся. Возвесели́, Го́споди, душі́ жите́йськими бу́ри істомленния, да ско́рби і воздиха́нія земни́я забве́нію предадя́ть. Усли́ши я, Го́споди, на ло́ні Твоє́м, я́ко же мать ча́да своя́, і ріки́ їм: прощаються вам гріси́ ва́ша. Прийми́ я. Го́споди, в блаже́нноє і ти́хоє приста́нище Твоє́ да возра́дуються о боже́ственній сла́ві Твоє́й. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 2","ps":["Озаре́нієм Всеви́шняго просвіща́єм, преподо́бний Мака́рій глас от черепа язи́чеська усли́ша: «Єгда́ молі́теся о стра́ждущих во а́ді, отра́да бива́єть язичником». О, ди́вния си́ли моли́тв христия́нських і́миже преіспо́дняя озаря́ється! Неві́рния ку́пно і ві́рния утіше́ніє приє́млють, єгда́ о всем ми́рі вопіє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Рече́ ні́когда Ісаа́к Сиріянин: «Се́рдце милующеє о лю́діх і скоті́х і о тва́рі всей моли́тви сле́зния єжеча́сно прино́сить, даби́ сохранилися і очистилися». Та́кожде і ми все дерзнове́нно всім от ві́ка уме́ршим у Го́спода по́мощі прося́ще, взива́єм. Ниспосли́ нам. Го́споди, дар моли́тви пламенеющей о уме́рших. Пом'яни́, Го́споди, вся заповедавшия нам, недосто́йним, моли́тися о них, і ізжени́ забве́нния і́ми гріхи́. Пом'яни́, Го́споди, вся без моли́тви погребе́нния, прийми́, Го́споди, в селе́нія Твоя́, вся от ско́рби іли́ ра́дости сме́ртію напрасной скончавшіяся. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 3","ps":["Пови́нни єсьми́ в бі́дствії ми́ра, в страда́нії безслове́сния тва́рі, в болі́зніх і му́ках младе́нцев непоро́чних, гріхопаде́нієм бо люде́й блаже́нство і лі́пота всея́ тва́рі разрушся. О Велича́йший от страда́льцев невинних, Христе́ Бо́же наш! Ти Єди́н єси́ отпусти́ти всім мо́жеши. Отпусти́ же всім і вся, ми́ру первозда́нноє благоде́нствіє пода́ждь, ме́ртвії і живі́ї да обря́щуть, взива́я: Аллилу́я."]},{"h":"Ікос 3","ps":["Сві́те ти́хий. Іскупи́телю всея́ вселе́нния, любо́вію мир весь об'ємляй: се сли́шиться со креста́ вопль Твой о вразі́х Твої́х: «О́тче, отпусти́ їм!» І́менем всепроще́нія Твоєго́ моли́тися Отцю́ Небе́сному об упокоє́нії ві́чнім Твої́х і на́ших враг дерза́єм. Прости́, Го́споди, кров непови́нную пролившия, жите́йський путь наш скорбми́ усеявшия, благоде́нствіє своє́ слеза́ми бли́жніх свої́х устроя́ющия. Не осуди́. Го́споди, гонящия ни клевето́ю і зло́бою, ми́лостію возда́ждь, ї́хже оби́діхом іли́ оскорби́хом по неві́дінію, і да бу́деть свя́та моли́тва на́ша о них та́їнством примире́нія. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́!"]},{"h":"Кондак 4","ps":["Спаси́, Го́споди, в тя́жких муче́ніях скончавшіяся, убієнния, живи́ми погребе́нния, земле́ю засипанния, волна́ми і огне́м поглоще́нния, звірми́ растерзанния, от гла́да, мра́за, бу́ри іли́ паде́нія с висоти́ умершія і ра́дость Твою́ ві́чную пода́ждь їм за скорб кончи́ни. Да благослов'я́ть страда́ній свої́х вре́м'я, я́ко іскупле́нія день, воспіва́я: Аллилу́я."]},{"h":"Ікос 4","ps":["Всім, і́же поємлемі суть могилой во сві́тлой ю́ности, і́же на землі́ терно́вий віне́ць страда́ній прия́ша, і́же ра́дости земни́я не узрі́ша, щедро́тами Твоєя́ безконе́чния любве́ возда́ждь. Го́споди. Под тя́жким бре́менем трудо́в уме́ршим воздая́ніє пода́ждь. Прийми́, Го́споди, в черто́зі рая́ о́троци і ді́ви і сподо́би я ликовствованія на ве́чері Си́на Твоєго́. Утиши́, Го́споди, скорб роди́телей о ча́діх уме́рших. Упоко́й, Го́споди, вся ро́да і сі́мені не іму́щия, о ни́хже ність кому́ моли́тву вознести́ Тебе́, Созда́телю, да ісче́знуть гріси́ їх от блиста́нія всепроще́нія Твоєго́. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 5","ps":["Я́ко послі́днєє ко вразумле́нію і покая́нію зна́меніє смерть дарова́л єси́, Го́споди. При грозном блиста́нії єя́ суєта́ земна́я обнажа́ється, стра́сті пло́тськия і страда́нія утиха́ють, непокори́вий ра́зум смиря́ється. Пра́вда ві́чная отверза́ється, отягче́нния же гріхми́ і безбожници на сме́ртном о́дре битіє́ Твоє́ ві́чноє іспові́дують і к милосе́рдію Твоєму́ взива́ють: Аллилу́я."]},{"h":"Ікос 5","ps":["О́тче утіше́нія вся́чеськаго, со́лнцем озаря́єши, плода́ми услажда́єши, лі́потою ми́ра дру́зі і вразі́ Твоя́ весели́ши. Ві́руєм бо, я́ко і за гробо́м милосе́рдіє Твоє́, да́же всі́ми отве́рженния грі́шници милующеє, не істощаєвається. Скорби́м об ожесточенних і беззако́нних хулителях Святи́ні Твоєя́. Бу́ди, Го́споди, над ни́ми спаса́ющая блага́я во́ля Твоя́. Оста́ви, Го́споди, без покая́нія сконча́вшимся, спаси́ в омраче́нії ума́ са́мі себе́ погубившия, да уга́снеть пла́мень греховности їх в мо́ре благода́ті Твоєя́.","Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 6","ps":["Стра́шен єсть мрак душі́, от Бо́га удаленной, со́вісти терза́нія, скре́жеть зубни́й, огнь неугаси́мий і черв неумира́ющий. Трепе́щу такови́я участи і, я́коже о самі́м себі́, молю́ся о во а́ді стра́ждущих. Да сни́деть на ня росо́ю прохлажде́нія на́ша піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л світ Твой, Христе́ Бо́же наш, на сідя́щия во тьмі і сі́ні сме́ртній і во а́ді су́щия, Тебі́ взива́ти не могу́щия. В преіспо́дняя землі́ снизше́д, ізведи́, Го́споди, во отра́ду гріхми́ с Тобо́ю разлученния, но не отре́кшіяся от Тебе́ ча́да Твоя́, стра́ждуть бо лю́ті, поми́луй я. Согріши́ша бо на Не́бо і пред Тобо́ю, безмі́рно тя́жки гріхи́ їх, ми́лость же Твоя́ безмі́рна єсть. Посіти́ го́ркую нищету́ душ от Тебе́ отдаленних, поми́луй, Го́споди, і́стину по неві́дінію гнавшия, бу́ди їм любо́в Твоя́ не огне́м паля́щим, но райською прохла́дою. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 7","ps":["По́мощ пода́ти десни́цею Своє́ю тща́шеся усо́пшим рабо́м Свої́м, яви́ся їм. Го́споди, во виді́ніїх та́їнственних, ясновидно, на моли́тву їх вдохновляя, да помина́я отше́дшия, блага́я діла́ і по́двизі за ня творя́ть, взива́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Це́рков Христо́ва Вселе́нськая непреста́нно єжеча́сно моли́тви за почившия по всей землі́ возно́сить, гріхи́ бо ми́ра Пречи́стою Кро́вію Боже́ственнаго вінця́ смиваються, от сме́рти к животу́ і от землі́ к Небесі́ душі́ усо́пших си́лою моли́тв за ня пред олтари́ Бо́жії. Бу́ди, Го́споди, хода́тайство Це́ркві уме́ршим лі́ствицею к Небесі́. Поми́луй я. Го́споди, предста́тельством Пресвяти́я Богоро́диці і всіх святи́х. Оста́ви їм согріше́нія, ві́рних Твої́х ра́ди, день і ноч к Тебі́ вопію́щих. Незло́бивих ра́ди младе́нцев поми́луй, Го́споди, роди́телей їх, і ма́терей слеза́ми іскупи́ согріше́нія чад їх. За моли́тви безвинних страда́лець, за кров му́ченик пощади́ і поми́луй грі́шници. Прийми́, Го́споди, моли́тви на́ша і ми́лостині, я́ко воспомина́ніє доброді́телей їх. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 8","ps":["Мир весь о́бщая моги́ла свяще́нная єсть, на вся́ком бо мі́сті прах оте́ць і бра́тій на́ших. Єди́ний неізмі́нно возлюби́вий ни, Христе́ Бо́же наш, прости́ вся, є́же от нача́ла і до ни́ні умершія, да воспою́ть любо́вію безмі́рною: Аллилуя."]},{"h":"Ікос 8","ps":["Гряде́ть би́ти день, я́ко пещ горя́щая, день ве́лій і стра́шний Суда́ послі́дняго, та́йни челові́чеськія откри́ються, кни́ги со́вістния разгну́ться… «Примирі́теся с Бо́гом!» – вопіє́ть Апо́стол Па́вел, – примирі́теся пре́жде того́ стра́шнаго дне». Помози́ нам. Го́споди, слеза́ми живи́х недостающеє уме́рших воспо́лнити. Да бу́деть їм, Го́споди, звук труби́ А́нгельськой спасе́нія благові́стієм і в час Суда́ Твоєго́ ра́достнаго поми́лованія їх сподо́би. Увінча́й, Го́споди, сла́вою за Тя пострадавшия і покри́й бла́гостію Твоє́ю прегріше́нія немощни́х. Го́споди, вся по і́мені ві́дий, пом'яни́ во і́ночестім чи́ні спасавшіяся, пом'яни́ благослове́нния па́стирі со ча́да їх. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 9","ps":["Благослові́те скоротекущеє вре́м'я. Ка́ждий бо час, мгнове́ніє ка́ждоє к ві́чності приближа́єть. Но́вая скорб, сіди́на но́вая суть ві́стници ми́ра гряду́щаго, свиді́теліє тлі́нности земни́я, я́ко вся мимотечеть возвіща́ють, я́ко Ца́рство Ві́чноє прибли́жися, іді́же ність ні слез, ні воздиха́нія, но отрадная пі́нія: Аллилу́я."]},{"h":"Ікос 9","ps":["Я́ко дре́во по вре́мені ли́ствій свої́х лиша́ється, та́ко і дні́є на́ші по коли́ких лі́тіх оскудіва́ють. Ув'яда́єть і ю́ности пра́зднество, світи́льник ра́дованія угаса́єть, близиться ста́рости отчужде́ніє. Дру́зі і сро́дниці умира́ють. Гді ви, ю́ния ликующия? Безмолвни гро́би їх, но душі́ їх в десни́ці Твоє́й. Ми́слим взори їх із ми́ра невеще́ственнаго. Го́споди, Ти єси́ Со́лнце пресві́тлоє, озари́ і согрі́й усо́пших селе́нія. Да пре́йдеть наві́ки го́ркаго разлуче́нія вре́м'я. Сподо́би ни ра́достнаго свиданія на Небесі́х. Сотвори́, Го́споди, да все єди́но бу́дем с Тобо́ю. Возврати́, Го́споди, отшедшим ді́тства чистоту́ і ю́ности благоду́шіє і пра́здником Па́схи да бу́деть їм Живо́т Ві́чний. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 10","ps":["Пролива́я ти́хия сле́зи на могилах сро́дников на́ших, мо́лимся с наде́ждою і с упова́нієм взива́єм: скажи́ нам, Го́споди, я́ко оста́вил єси́ гріхи́ їх! Даждь о сем открове́ніє та́їнственноє ду́ху на́шему, да воспіва́єм: Аллилу́я."]},{"h":"Ікос 10","ps":["Весь путь преше́дшия жи́зні на́шея ви́жу озираяся, коли́ко мно́жество люде́й, от пе́рваго дне і до ни́ні отше́дшия, і мно́зі їх блага́я мі содеявшия. Любо́вію своє́ю до́лжная сим воздава́я, вопію́ Ті. Сподо́би, Го́споди, сла́ви Небе́сная роди́телі моя́ і бли́жняя моя́, над ло́жем мої́м младенчеським бодрствовавшия, возрастившия і воспитавшия м'я. Просла́ви, Го́споди, пред А́нгели святи́ми, всіх благовествовавших мі сло́во спасе́нія, добру́, пра́вді, святи́м приме́ром жи́зні своєя́ учившия м'я. Услади́, Го́споди, тіх, і́же во дні ско́рби моєя́, ма́нною сокрове́нною послужи́ша мі. Вся доброді́телі і благоді́телі вознагради і спаси́. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 11","ps":["Гді ти, сме́рти жа́ло, гді же і мрак і страх твой пре́жде бива́ющий? Отнині ти жела́нная, неразлу́чно с Бо́гом сочетаєши. Поко́ю вели́кий суббо́тства та́їнственнаго. Жела́ніє і́мам умре́ти і со Христо́м би́ти, взива́єть Апо́стол. Ті́мже і ми, взира́я на смерть, я́ко на стезю́ к Ві́чній Жи́зні, воззове́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Воскре́снуть ме́ртвії і воста́нуть су́щії во гробі́х і возвеселя́ться живу́щії на землі́, я́ко воста́нуть тілеса́ духо́вния, сві́тло просла́вленния, нетлі́нния. Ко́сті сухи́я, сли́шіте сло́во Госпо́днє: «Се Аз введу́ во вас дух живота́ і дам на вас жи́ли і возведу́ на вас плоть і простру́ по вам ко́жу». Возстаньте із дре́вле проше́дшаго вре́мене, іскупленнії кро́вію Си́на Бо́жия, оживле́ни сме́ртію Єго́, возсія́ бо на ни світ Воскресе́нія. Отве́рзи їм, Го́споди, ни́ні всю бе́здну соверше́нств Твої́х. Ти сія́л єси́ їм сві́том со́лнця і луни́, да у́зрять они́ і сла́ву лучезарних лико́в А́нгельських. Ти услаждал єси́ я великолі́пієм восто́ка і за́пада світи́л небе́сних, да у́зрять же они́ і світ невече́рній Божества́ Твоєго́. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 12","ps":["Плоть і кров Ца́рствія Бо́жия не наслі́дять, доко́лі во пло́ті живе́м, отлученнії от Христа́. А́ще же і у́мрем, но оживе́м для Ві́чності. Подоба́єть бо тлі́нному ті́лу на́шему в нетлі́ніє облекшись і ме́ртвенному сему́ бессмертієм просія́ти, даби́ во сві́ті невече́рняго дне воспі́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Ча́єм срі́тенія со Го́сподем, ча́єм ясной зари́ воскресе́нія, ча́єм пробужденія із гробо́в сро́дников на́ших і зна́ємих і оживле́нія в благоговейнейшей лі́поті жи́зні уме́рших. І гряду́щеє преображе́ніє всея́ тва́рі торжеству́єм і Возсоздателю на́шему вопіє́м: Го́споди, к торжеству́ ра́дости і добро́ті мир созда́вий, нас к свя́тости із глубини́ гріхо́вния возста́вивий, даждь уме́ршим ца́рствовати посреді́ битія́ но́ваго, да возсія́ють я́ко світи́ла на Небесі́ в день сла́ви їх. Да бу́деть їм А́гнець Боже́ственний сві́том невече́рнім. Даждь, Го́споди, і нам с ни́ми Па́сху нетлі́нія пра́здновати. Соєдини́ умершія і живи́я в несконча́ємій ра́дости. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 13","ps":["О, Премилосердний О́тче Безнача́льний, всім хотя́й спасти́ся. Си́на к погибшим ниспославий і Ду́ха Животворя́щаго ізлива́яй! Поми́луй, прости́ і спаси́ родни́я і бли́зькия нам усо́пшия і всіх от ві́ка сконча́вшихся і предста́тельством їх, посіти́ нас, да вместе с ни́ми вопіє́м Тебі́, Спаси́телю Бо́гу, побі́дную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ада́ма па́дшаго і весь род челові́чеський от ві́чния поги́белі спаса́яй, посла́л єси́, Бла́же, в мир Си́на Твоєго́, Кресто́м бо і Воскресе́нієм Єго́ возсія́ і нам Живо́т Ві́чнующий. На безмі́рноє Твоє́ милосе́рдіє упова́юще, ча́єм нетлі́ннаго Ца́рствія Сла́ви Твоєя́, усо́пшим дарова́ти того́ про́сим і мо́лим Ті ся. Возвесели́, Го́споди, душі́ жите́йськими бу́ри істомленния, да ско́рби і воздиха́нія земни́я забве́нію предадя́ть. Усли́ши я, Го́споди, на ло́ні Твоє́м, я́ко же мать ча́да своя́, і ріки́ їм: прощаються вам гріси́ ва́ша. Прийми́ я. Го́споди, в блаже́нноє і ти́хоє приста́нище Твоє́ да возра́дуються о боже́ственній сла́ві Твоє́й. Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Кондак 1","ps":["Непостижи́мим про́мислом ко бла́гу ві́чному мир уготовля́яй, челові́ком времена́ і о́браз кончи́ни опреділи́вий, оста́ви, Го́споди, от ві́ка уме́ршим вся согріше́нія їх, прийми́ я во оби́телі сві́та і ра́дованія, об'я́тія О́тчі отве́рсти їм потщи́ся і усли́ши ни, па́м'ять їх совершающия і пою́щия:","Го́споди, Люби́ Неізрече́нная, пом'яни́ усо́пшия раби́ Твоя́."]},{"h":"Молитва за спочилих","ps":["Бо́же духо́в і вся́кия пло́ті, смерть попра́вий і дия́вола упраздни́вий, і живо́т ми́ру Твоєму́ дарова́вий! Сам, Го́споди, упоко́й душі́ усо́пших раб Твої́х: святі́йших патріа́рхов, преосвященних митрополи́тов, архієпи́скопов і єпи́скопов, во свяще́нничеськом, церко́вном і монашеськом чи́ні Тебі́ послужи́вших; созда́телей свята́го хра́ма сего́, правосла́вних пра́отець, оте́ць, бра́тій і сесте́р, зді і повсю́ду лежа́щих; вожде́й і во́їнов за ві́ру і оте́чество живо́т свой положи́вших, ві́рних, убіє́нних в междоусобной бра́ні, утонувших, сгоревших, на мра́зі замерзших, расте́рзанних звірми́, без покая́нія внеза́пно сконча́вшихся і не успевших примириться с Церковю і со свої́ми враги́; в ізступле́нії ума́ самоубієнних, тіх, о ко́їх заповедали і просили ни моли́тися, о ко́їх ність кому́ моли́тися і ві́рних, погребе́нія христия́нськаго лише́нних (ім’я) в мі́сті сві́тлі, в мі́сті зла́чні, в мі́сті поко́йні, отню́дуже отбіже́ болі́знь, печа́ль і воздиха́ніє. Вся́коє согріше́ніє, соді́янноє ї́ми сло́вом іли́ ді́лом іли́ помишле́нієм, я́ко благи́й Человіколю́бець Бог прости́, я́ко ність челові́к, і́же жив бу́деть і не согріши́ть. Ти бо єси́ єди́н кромі́ гріха́, пра́вда Твоя́ – пра́вда во ві́ки, і сло́во Твоє́ – і́стина.","Я́ко Ти єси́ Воскресе́ніє, і Живо́т і Поко́й усо́пших раб Твої́х (ім’я), Христе́ Бо́же наш, і Тебі́ сла́ву возсила́єм со безнача́льним Твої́м Отце́м, і Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст покаянний Пресвятій Богородиці","e":"Penitential Akathist to the Most Holy Theotokos","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Небе́сним Царе́м, превисшей і у́мних чино́в, всеблаго́й Цари́це, ро́да христия́нськаго Засту́пнице і от всіх зол і напа́стей ско́рому вспоможенію, всі ми, грі́шнії і в безмі́рних біда́х су́щії раби́ Єя́, со слеза́ми і умиле́нієм се́рдця, принесе́м покаянниє пі́нія: Ти же, я́ко премилосе́рдная Ма́ти на́ша, сама́ духоно́сному моле́нію наста́ви нас і прия́ти сія́ воздиха́нія душі́ на́шея удосто́й:","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Ікос 1","ps":["Тьма неві́рія і в сні глубо́ці запусті́ніє жи́зні богоподобниє об'яша до конця́ предавшийся тлі́нію род челові́чеський, і в неісходних плени́цях паде́ній гріхо́вних оковал все ни светоненавистник і дре́вній уби́йця-дия́вол, князь ми́ра сего́. Но і врага́ми соделавшихся, не преста́ла люби́ти люде́й свої́х бла́гость Творця́, нас спасающего, і Тобо́ю, о Пренепоро́чная дщер Дави́дова, обітова́л Он ізнача́ла дарова́ти погибшим Сі́м'я жени́ Христа́ Емману́їла. Се і ми ни́ні, а́ще і ослепихом очеса́ на́ша малові́рієм і ужаса́ємся глубини́ неотмитних беззако́ній свої́х, но от Тебе́, о Ма́ти Сві́та, ча́єм спасе́нія, і не і́щуще самооправданія во грісі́х неісче́тних, Тебі́ наде́ждою непозиблемою к себі́ зове́м:","О, Благода́тная, на по́мощ к нам поспіши́, — Цари́це Небе́сная, із бе́здни паде́ній нас ісхити́.","О, Благода́тная, луча́ми сві́та го́рняго всеобдержащий мрак житія́ на́шего озари́, — Ді́во Пречи́стая, сія́нієм чистоти́ Твоєя́ гріхми́ потемневшиє на́ша се́рдця освіти́.","О, Благода́тная, біжа́ти льще́ній лжі і гріха́ Ти нас научи́ — Ма́тер Святі́йшая, любо́в і ві́рность пра́вді в душі́ на́ша вложи́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 2","ps":["Оста́вивше двор о́тчий і, я́ко блу́дний син, на страну́ дале́че отишедше, во мрак язи́чества, ти́ну страсте́й і сінь сме́ртную впадо́ша всі си́ни Си́фови, і ні цар і ні проро́к, ні а́нгел і ні мудре́ць, но то́чію Боже́ственний Син Твой, о Благода́тная Марі́є, возмо́же їх к сві́ту богові́дінія принести́ і вся си́ли, я́же к животу́ і благоче́стію, дарова́ти, да умиле́ніє, спасе́ніє обрі́тши, Творцю́ і ізба́вителю своєму́ поє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Шата́шася всу́є язи́ци і лю́діє заблудшії поучахося тще́тним, поне́же забве́но бисть чи́стоє преда́ніє сино́в Бо́жиїх, і сіть многобо́жія привлече́ осуєтившієся наро́ди в кумирослуженіє лжі і істаяваніє вредоно́сних по́хотей і скве́рни угожде́нія грехолюбивой пло́ті. Єгда́ же предста́ Тебі́, віща́ти ди́вная, во́їнств а́нгельських вождь — Гавриї́л, разгнася Сві́том Восто́ка і́дольськой ле́сти ночная тьма, і нача́ток яви́ся во Христі́ Ісу́се вся́кия пло́ті коне́чнаго ісціле́нія. Ті́мже і ми умиле́нним се́рдцем, глави́зну спасе́нія ви́дяще, со Арха́нгелом в благогові́нії Тебі́ взива́єм:","О, Благода́тная, всегда́ с Тобо́ю Бог і Госпо́дь, — Ді́во Богоро́дице, спасе́ніє Той і нам в Тебі́ соді́лала.","О, Благода́тная, коль благослове́н во і́стину пречи́стаго чре́ва Твоєго́ Боже́ственний Плод, — свята́я святи́х Святі́йшая, в Тебі́ вмісти́ся Невмісти́мий і не́бом, не то́чію бре́нною землей.","О, Благода́тная, колицеє вели́чіє сотвори́ Тебі́ Цар і Госпо́дь, — Ма́тер Безневі́стная, любве́ безконе́чной і нам осія́й животворя́щий світ.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 3","ps":["Но́вую твар созида́ти і люде́й Свої́х во є́же не земна́я, но го́рняя мудровати привести́, сни́де с небесе́ во юдо́ль земну́ю Человіколю́бець Госпо́дь, от Него́же і поднесь устроя́ється Ца́рствіє Бо́жиє на землі́ і претворя́єть собо́ю, я́коже квас до́брий, да вскиса́єть все многоразли́чноє сміше́ніє челові́чеськоє. Ми же, єди́ноє ста́до Христо́во возлюби́вше і крі́пці во дворі́ Єго́ при́сно се́рдцем утвержда́ющеся, єдиноду́шно, і в паде́ніях на́ших всяпобеждающему, Влади́ці жи́зні на́шея поє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Го́рній Ієрусали́м всегда́ осія́я і всеоживляющей Благода́тію Свята́го Ду́ха утіша́я просла́вленних Свої́х, яви́ Госпо́дь і в ми́рі земно́м жизнь і си́лу Ца́рствія Своєго́, і уже́ не юдо́лію пла́ча і слез, но ми́ра всеутоляющаго і ра́дости нескомчаємия, єя́ же нікто́же не мо́жеть от'яти, предстої́ть всім ві́рним небошественний путь стра́нствія на́шего во вре́менном сем битії́. На него́ же взира́юще, і ми недосто́йнії і ліни́вії, к сему́ блаже́нству призва́нії, но ізменою безверія і пустотою миролюбленія себі́ із него́ ізвергшії, от Тебе́, о Богома́ти, по́мощі і спасе́нія себі́ ча́єм і слеза́ми раска́янія і сердечного обраще́нія от ги́белі сія́ вопіє́м:","О, Благода́тная, Ти нас ісціли́, — Ма́ти милосе́рдная, проще́ніє Бо́жиє нам іспроси́,","О, Благода́тная, к жи́зні в Си́ні Твоє́м возврати́. Небе́сний Покро́ве наш, током благода́ті, су́щей в Тебі́, ізсо́хшеє се́рдце в нас ороси́,","О, Благода́тная, не люби́ти ми́ра і злих, я́же в ми́рі, нас научи́, — Ді́во Пречи́стая, влече́нія се́рдця на́шего к чи́стой любві́ Христо́вой устреми́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвленной наш дух оживи́."]},{"h":"Кондак 4","ps":["Небошественнаго путі́ злати́я пра́вила іму́ще і ма́ло ізбра́нних, в сих подвиза́ющихся, повсю́ду при́сно ви́дяще, в Тебі́, на висшую степе́нь богоподобія восшедшей, о́браз небе́сній му́дрості і в Бо́зі ві́чнаго созида́нія обріта́єм і Тобо́ю преізли́ха утіша́ємся, і́бо найпа́че пред всі́ми слага́ла єси́ в чисті́йшем се́рдці Твоє́м вся словеса́ дія́ній і уче́ній Воплотившейся прему́дрости — Си́на Твоєго́: отню́дуже приі́скренні о всіх сих умилящієся і ди́вная ду́ха в Тебі́ созерца́юще, толи́ко просла́вльшемуся во святи́х Свої́х, похва́льно всі воспіва́єм: Аллилу́я."]},{"h":"Ікос 4","ps":["Внутр нас, я́коже рече́ть Госпо́дь, — в се́рдці челові́ка, єго́ просветленії, но́вой жи́зні і го́ре устремленіях, єсть Ца́рствіє Бо́жиє, є́же імену́ється пра́вда і мир і ра́дость о Ду́сі Свя́те, і красото́ю благоустроє́нія душі́ во ізбра́нних Бо́жиїх огнезрачне сія́єть нам. І сіє́ со́вістію ві́дуще і ду́хом і́щуще, ді́ли же сту́дними і окая́нством беззако́ній свої́х всп'ять — во страну́ самоїстуканних страсте́й — отторгающеся, Тебі́, во ізбра́нних ізбра́нную, воспо́лнити і утоли́ти на́ше обнищаніє про́сим і ско́рбними воздиханіями се́рдця сино́вне умоля́єм си́це:","О, Благостная, приблизітеся к Тебі́ помози́, — сил Повелительнице, о Бо́зі возмога́ти нас укріпи́.","О, Благода́тная, се́ю благода́тію, в Тебі́ преізбиточествующею, оскудіва́ющая се́рдця на́ша напо́й, — во бла́зі Помо́щнице цві́ти доброделанія в пусти́нния на́ші душі́ всади́.","О, Благода́тная, достига́ти Ца́рствія Си́на Твоєго́ подви́гни нас і усоверши́, — непоро́чности Ві́чне, духовниє бла́га ценити і іска́ти научи́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 5","ps":["Я́ко пшени́ця до́брая на ни́ві, вирастаєть і краси́ плоди́ть і зреєть незри́мо на се́рдці челові́ка Ца́рствіє Бо́жиє, і стори́цею виращаєть Оте́ць щедро́т сі́м'я слове́с Єго́, а́ще почвою до́брою, углубленною і пото́м усе́рдія возделанною приє́млеть сіє́ се́рдце на́ше. І сія́ вся до́брі ві́дуще і ра́достні созерца́юще прославля́єм Єди́наго Вино́вника всячеського доброделанія — Тебе́, Отця́ сві́тов, от Него́же ісхо́дить вся́коє дая́ніє бла́го і всяк дар соверше́н: Аллилу́я."]},{"h":"Ікос 5","ps":["«Блаже́нни сли́шащії сло́во Бо́жиє і храня́щії єго́», і́бо ні в сем ві́ці, ні в бу́дущем не отниметься от них сія́ блага́я часть, і соблю́дше ю в добро́м і чи́стом се́рдце своє́м, всегда́ прино́сять они́ в терпі́нії оби́льний плод свой, ра́дуяся. І́бо і бра́том, і сестрой, і да́же мате́рією Своє́ю удосто́їл найменовать їх Госпо́дь, а́ще іспо́лнять они́ во́лю Отця́ Єго́, І́же на небесі́х. Воі́стину, си́це єще́ і ду́хом і все́ю жи́знію соді́лалася Ти, о Пресвята́я Ді́во, Ма́терію Го́спода Твоєго́, Єго́же Пречи́стая Плоть істка́ся от Твої́х честни́х крове́й: і́бо па́че всіх соблюла́ єси́ Боже́ственноє сло́во Єго́ і к небесе́м со сла́вою восшла єси́, сотво́рши во́лю Отця́ Небе́снаго. Ми же всі, умо́м і се́рдцем сві́дуще сія́ со́лнцем блиста́ющия добро́ти Твоя́, і ра́достію прославля́юще во Успе́нії Твоє́м к небесі́ возвише́ніє ро́да челові́чеськаго, благогові́йними усти́ согла́сно поє́м боже́ственния вели́чія Твоєя́:","О, Благода́тная, я́ко Ма́ти Влади́ки, восцарившаяся на небесі́, — Ві́нче, Преви́сший всякого созда́нія, і нас, ско́рбних і убо́гих, не оставля́ющая на землі́.","О, Благода́тная, на ка́мені ісполне́нія за́повідей нас утверди́, — Возлю́бленная Бо́гом і ли́ки а́нгельськими, і на́ша замкнувшієся і в моги́лу себ'ялюбія погребльшіяся се́рдця отве́рзи к любві́.","О, Благода́тная, із душной темни́ці горди́ні, уни́нія і плотськи́х по́хотей вся ни ізведи́, — Цари́це Небе́сная, к Бо́жию ро́ду і нас, страстми оземляневших, сопричти́ і подніми.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 6","ps":["«І́же ність со Мно́ю, на М'я єсть, і і́же не со Мно́ю собира́єть, — расточа́єть», рече́ Свої́м ві́рним Іпоста́сная Прему́дрость, Христо́с Госпо́дь, презира́я в глубині́ віко́во всепроницяющим О́ком Свої́м і сего́ дне, об'юродевших без Христа́ мудрецо́в, на песці́ зиждемая строє́нія. Ї́хже шата́нія ви́дяще і в позна́нії пра́вди християнського благоче́стія па́че утвержда́ющеся, проникновенним се́рдцем і усти́ воспіва́єм ми Єди́ному краєуго́льному Ка́меню небе́сних і земни́х созиданій, Влади́ці Христу́: Аллилу́я."]},{"h":"Ікос 6","ps":["Путь і жизнь і і́стину прия́т род челові́чеський во Христі́, і побі́да, є́ю же Он побіди́ мир, соді́лася достоя́нієм всіх ві́рних Єго́ — до́брих ді́лателей зді виногра́дника Бо́жия. І́бо не то́чію зало́г блаже́нства ві́ка гряду́щаго Влади́ка да́руєть їм, но в до́брой со́вісти ка́ждаго во бла́го устроя́ється вся́чеськоє і земно́є ді́ланіє їх, і в пра́вді созида́ється взаїмноє служе́ніє бра́тій, любо́вію і ми́ром побіжда́ющеє вражду́ і разділе́нія в лю́діх, найпа́че же от ра́бства і тьми заблужде́ній свободи́ть сей ві́рний раб земно́є житіє́ своє́. Оба́че — уви́ нам, в лі́ності і небреже́нії і сліпоті́ безу́мно іждивающим, неісче́тною ціно́ю дарова́нноє, преми́рноє сокро́вище світоза́рния ві́ри Христо́вой! І́бо і плін, і у́зи, і осліпле́нія свої́ — в свобо́ди мі́сто возлюби́ли самопрельщенне все ми, світ за́повідей Царя́ своєго́ заби́в до конця́ і самохо́тні преда́вшеся соблазнам і обманам мно́гим в сі́ї лука́виє дні, я́ко і вся до́брая, отці́ пре́данная, пра́вила па́че расточате, в небреже́нії своє́м без Христа́ і сві́та ві́ри устроя́я свою́ жизнь. Сего́ ра́ди Тебе́, я́ко сті́ну ві́ри і жи́зні христия́нськия, нико́їми же зли́ми рушиму, до́брі ві́дущії і Єди́ную Наде́жду себі́ іму́щії, із бе́здни отча́янія умоля́єм і вопіє́м:","О, Благода́тная, Сама́ су́щи во і́стині, ко і́стині і нас приведи́, — Ми́лостивая ізнемогшим Помо́щнице, победителями гріха́ моля́щихся Тебі́ сотвори́.","О, Благода́тная, є́же ви́діти і ненави́діти злой плін свой наш ум озари́, — му́дрости го́рній сокро́вище, кра́сная жи́зні ві́чная очеса́м се́рдця яви́.","О, Благода́тная, собла́знов прельще́ніє от нас отжени́, — пра́вди Христо́вой Світ немерца́ющий, развіва́ти, я́ко пиль плевельную. Лука́виє ухищре́нія вся ни умудри́. \\","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любві́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 7","ps":["Ді́во Пренепоро́чная, Жизнь ми́ру роди́вшая, приобщи́тися і нас, недосто́йних, сея́ і́стинния Жи́зні в Си́ні Твоє́м призови́ і ли́ку ізбра́нних Єго́ сопричти́, і я́коже Сама́ от до́льних землі́ ко го́рнім восшедшая, і на́ші одебелевшиє взори го́ре устреми́ і духо́вния зрі́ти научи́, во глубина́х душі́ на́шея всеці́лую пре́данность Бо́гу, я́ко Отцю́ любві́, возбуди́, да приі́скренні славосло́вим Єго́, вку́пі, во і́м'я Єго́, соше́дшеся: Аллилу́я."]},{"h":"Ікос 7","ps":["Коль сві́тла і благотишна, коль сладка́ і ра́достна жизнь богоізбранних во Христі́, коль дивниє зна́менія си́ли і любві́ явля́єть в поко́є їх се́рдця Сладча́йший Спаси́тель наш, Госпо́дь Ісу́с! Та́ко і во всіх тя́готах і обремененії і ско́рби душе́вной к Себі́ зове́ть нас Єго́ бесконечная Любо́в, — да возьмем Єго́ і́го на себ'я́ і да о́браз кро́тости і смире́нія Спа́са своєго́ в се́рдці своє́м воспримем ми. І бла́го Єго́ і́го, і бре́м'я Єго́ поі́стині легко́, вся́кую тугу́ серде́чную облегча́я во утіше́ніє нам і отрадой ми́ра неот'ємлемого преобразу́я сію́ ско́рбную жизнь. Оба́че всіх сих благи́х і развраще́нних і стро́потних гріха́ лишившихся, тлю же по́хотей і за́висти, і зло́би, і уни́нія, і іна́я вся пле́вельная в се́рдці сгяжавшії, прегорце во всіх сих осужда́єм себе́ і стяняше, в покая́нії нелицемерном к Тебі́ єди́ній о́чі свої́ возво́дим і сино́вне зове́м:","О, Благода́тная, прості́ нас, прости́, — двер милосе́рдія нам отве́рзше, лю́ди своя́ воззови́.","О, Благода́тная, благо́є і́го Христо́во жела́ти нас научи́, Небе́сний о́бразе смире́нія, сіє́ с кро́тостію і в на́ше се́рдце вложи́.","О, Благода́тная, мир в на́ші душі́, мир і с бли́жніми нам ниспосли́, — ми́ра і любві́ Влади́чице, все житіє́ страждущего наро́да Твоєго́ умири́ і в покая́ніє возраждающеє приведи́.","О, Благода́тная, поми́луй нас і спаси́, і па́че со́лнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух озари́."]},{"h":"Кондак 8","ps":["Би́сер многоці́нний і по́честь найвисшаго в ми́рі сем зна́нія дарова́ся нам Отце́м сві́тов і Істо́чником щедро́т, я́ко синам Святи́я Єго́, Єди́ния Правосла́вния Це́ркве, я́же єсть столп і утвержде́ніє і́стини. Ми же, а́ще по достоя́нію ценити сего́ не нави́кше і дія́ньми скве́рнаго грехолюбія всечастно сим ізменяюще, — оба́че о таково́м ца́рськом зва́нії своє́м умиле́нним благодаре́нієм Призва́вшему нас — Влади́ці не́ба і землі́ — поє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["«О ро́ді неві́рний і развраще́нний. Доко́лі Я с ва́ми, доко́лі терплю́ вас», — возгласи́л і в долготерпі́нії Своє́м Госпо́дь, — о тіх, і́же в безверії і притворстве, єще́ же в лі́ності і пустоте се́рдця і в скве́рнах гріхо́вних, приступали к нему́, і тьма су́ще, к Сві́ту Чисті́йшему приобщали себ'я́. Но се і ми, а́ще і христия́не іменуємії, та́кожде му́чим і распинаєм Спасшего нас, і́бо зло́бою мно́гою і ожесточе́нієм, і ізменами неві́рія, і я́звами всесожигающих страсте́й по вся дні уязвляєм Єго́, і не могу́ще от хладности і небреже́нія, і от лени своєя́, в покая́ніє і ісправле́ніє прийти́, па́че і па́че дви́жем на себ'я́ пра́ведний гнів Судії́. Ти же, Єди́ноє Упова́ніє на́ше, благода́тію вся могу́щи, — мо́жеши і сія́ неісцельниє неду́ги уврачева́ти нам і пра́ведне на ни дви́жимий гнів Бо́жий Твої́м предста́тельством і моли́твами утоли́ти і отвести́. Сего́ ра́ди всім усе́рдієм, все́ю любо́вію своє́ю і із глубини́ се́рдця воздиха́ньми к Тебі́ припа́даєм і вопіє́м:","О, Благода́тная, помози́ нам, о помоги, — Ма́тер Милосе́рдная, із мерзькой ти́ни гріхо́в ізими.","О, Благода́тная, єле́єм любве́ Твоє́й одеревеневшеє се́рдце на́ше см'ягчи́, — всіх нас возлюби́вшая, луча́ми добро́т Твої́х оледененіє лі́ності на́шей і самохотних вожделі́ній в на́шей душе́ растопи́.","О, Благода́тная, во ві́ру, в жизнь ду́ха призови́ нас і введи́ — Ді́во Пречи́стая, се́рдцем косну́тися свя́тости і любві́ Христо́вой нас подими́.","О, Благода́тная, поми́луй нас і прости́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 9","ps":["Сотвори́ Тебі́ вели́чіє Си́льний, я́ко возлюбленной Ма́тері Божественного Си́на Своєго́, я́ко Святейшей із святи́х, Честні́йшей Херуви́м і Славнейшей без сравне́нія Серафи́м. Оба́че і Тебі́ путе́м крестним ідти́ к сла́ві указа́ла О́тчая Любо́в, єгда́ уста́ми Симео́на предте́че, я́ко ору́жіє про́йдеть сквозь матернськи скорб'ящеє се́рдце Твоє́. Ми же, я́ко во спасе́ніє на́ше все сіє́ бу́деть, ві́дущи, і безмерности Боже́ственной бла́гости к нам грі́шним пости́гнути не могу́щії, благода́рні піснь хвале́нія возноси́м Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["О́гненную ціп лю́тих муче́ній, і найпа́че позорнаго пригвожде́нія ко кресту́, претерпі́ пред очи́ма Твої́ма Боже́ственний Син, до конця́ покорною Отцю́ во́лею іспи́в ча́шу, все гріхи́ ми́ра омивающих, страда́ній Свої́х. І то зря́ще і се́рдцем с Сино́м распинающися, до конця́ іспила́ і Ти ча́шу сію́, ізболевшим се́рдцем Свої́м усинови́в Себе́ во Христі́ всіх стра́ждущих і озлобля́ємих, ко́ї ізнемога́ють под бре́менем жи́зненнаго креста́ своєго́. Сего́ ра́ди і ми во всіх печалях і ті́сних обстояніях свої́х, к Тебі́, я́ко Ма́тері состраждущей всім ско́рбним і угнете́нним, прибіга́єм і в горестях і напастях дній сих, Тебі́ с наде́ждою крі́пкою зове́м:","О, Благода́тная, Ти нас заступи́, — Любо́вію пламені́ющая, болі́зні лю́тия многовоздиха́ющия душі́ моєя́ утоли́.","О, Благода́тная, терпі́нієм в ско́рб'ях на́ших усоверши́, — Благослове́нная Богоро́дице, си́лу побора́ти іскуше́нія в нас утверди́.","О, Благода́тная, от злих обстоя́ній нас свободи́, — Ма́тер Всеблага́я, Твою́ си́лу — всепобеждающую і враго́в пра́вди разящую — наро́ду малові́рному ни́ні яви́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 10","ps":["Іскони́ ви́діша наро́ди христия́нстії Твоє́, о Крі́пкая Охрано бедствущих і погубляємих, неуси́пноє о них попече́ніє, єя́ же ра́ди вини́ і просла́виша Тя всі і із ро́да в род свиді́тельствоваша о ди́вних чудесах, всю́ду поборающей о ві́рних і на вся́кую усе́рдную мольбу́ поспешающей, всесильной по́мощі Твоє́й, і та́ко благода́рственні пели і пою́ть із кра́я в край о Тебі́ піснь хвале́бную Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Ве́ліє чу́до сотвори́ Госпо́дь Твоєго́ ра́ди, о Ма́тер Бо́жия, всемо́щнаго об отці́х на́ших хода́тайства. Єгда́ бо вели́кий ненавистник ро́да християнського і лю́тий мучи́тель Темираксак хвалишеся всю Россі́йськую зе́млю положи́ти в запусті́ніє і іскорени́ти христия́нськую ві́ру, к Тебі́ возопи́ша лю́діє Твої́ о спасе́нії і в покая́нії і слеза́х мно́гих притеко́ша к святі́й Владимирстей іко́ні Твоє́й. І біжа́ тогда́ нечести́вий, і́бо в со́нмі святи́х узрі́ той Тебі́, я́ко Цари́цю, во сла́ві неізрече́нной, молнієзрачними луча́ми па́че со́лнця осіяваємую і єму́ отити от преді́л на́шея страни́ гро́зно претящу, о ві́рних же Свої́х, рука́ми просте́ртима, к Си́ну Своєму́ моля́щуюся. Ми же, ві́рою несомні́нною вели́коє мо́ре чуде́с Твої́х вспоминающе, і все ча́яніє своє́ на Тя возло́жше, от мо́ря злих устремле́ній, і в нас сами́х і о́крест нас ополчи́вшихся, і ни́ні огради́ти наро́д наш умоля́єм і в рида́ніях мно́гих поє́м:","О, Благода́тная, на ни належа́щую гро́зу отжени́, — Ма́ти Блага́я, покри́вши любо́вію, разслабле́ніє на́ше удали́ і прости́.","О, Благода́тная, си́лу і лі́поту Правосла́вія ми́ру яви́, — ві́ри Храни́тельнице, і нас убо́гих досто́йними єя́ сотвори́.","О, Благода́тная, со́лнця превисшую сла́ву Твою́ на́шему се́рдцю откри́й, — Ти, Ма́тер Сві́та, тьму належа́щую с на́ших оче́с разжени́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 11","ps":["Мно́гажди і отці́ на́ші ослабеваху в добро́м христия́нськом житії́ своє́м, і темнотою і неві́жеством, поро́ки і непра́вдами, та́кожде і братоненавиді́нієм і обидами слабому, в ти́ну студодія́нія себі́ погружаху. Оба́че, і па́дающе глубо́ці, не к іні́м кумирам, но к Єди́ному Бо́гу — Спаси́телю своєму́ прибіга́ху, і го́рняя возлюби́в, покая́нієм же сле́зним к Тебі́, Засту́пнице Усердной, о́чі свої́ возводя́ще, не престава́ху пред святи́ми Твої́ми іко́нами пі́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Разоряшеся ні́когда страна́ Ру́ськая лихолетієм, єгда́ сму́ти і безнача́ліє, татьби́ і обмани, уби́йства і кровопроли́тія, і зло́ба мно́гая обуя́ша лю́ди православниє, і ізмалодушествовалися всі, себі́ погубля́юще, єще́ і тя́жкому враго́в інові́рних і же́стоких наше́ствію предаде́ я Госпо́дь. І кто же би спас тогда́ ізнемо́гших і я́ко ли́ствія разсипавшихся, і уже́ в бе́здну отча́янія прише́дших отце́в на́ших, а́ще не Ти, о Всеблага́я, умилосердилась о них, Єя́же предста́тельством, я́ко же пові́да святи́й уго́дник Бо́жий і моли́твенник за ни, Се́ргій, суд об оте́честві на́шем на ми́лость преложи́л Влади́ка Христо́с. Та вся вспоминающе і бо́льшая сих зол во дні на́ша ви́дяще, і я́ко во волна́х морськи́х погиба́ющії, і ми Тебі́ громце зове́м:","О, Благода́тная, зло́бі враго́в лю́тих одолеть нас немощни́х не попусти́, — ми́ра Влади́чице, всп'ять ко́зні губи́тельния їх обрати́.","О, Благода́тная, Судію́ Пра́веднаго о нас умоли́, — Кро́тости Вели́чіє, тишину́ ми́ра і любві́ в наро́ді Твоє́м утверди́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 12","ps":["Ізлія́ся благода́ть, во апо́столе язи́ков су́щая, на вся верующая, я́ко і на неду́жния наносиша от по́та ті́ла єго́ главотя́жи і убру́сці, і ті́ї ісціля́хуся от неду́г свої́х, та́кожде гонимії си́лою Бо́жиєю, біжа́ху і ду́хи нечи́стії із них. Ізлива́єши і Ти, Преізбиточествующая благода́тію, сію́ от полноти́ Твоєя́ во святи́є іко́ни Твоя́, я́же ізбираєши в зна́менія от Твоєя́ любве́ по́мощі ві́рним, надеющимся на Тя, да поє́м, ра́достію торжеству́юще о сих явленіях си́ли Твоє́й, всі Просла́вльшему я́ко Цари́цю, Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Мно́гоє мно́жество ми́лости Своєя́ яви́ла єси́, Богоро́дице, правосла́вним лю́дем Твої́м, найпа́че же во святи́х написаніях Пречи́стаго Ли́ка Твоєго́. І́бо і сія́ ди́вная зна́менія во мно́жестві яви́шася в на́ші дні, ї́хже не зна́ша отці́ на́ші і ні єди́ний наро́д на землі́, я́ко єди́ною то́чію благода́тною си́лою Твоє́ю, я́ві же і соверше́ніє начим іни́м, обновишася і сві́тло сія́ють святи́є іко́ни Твої́. І то зря́ще і по достоя́нію воспі́ти сія́ вели́чія недоуміва́юще, благогові́йно преклоня́ються і умиляються се́рдцем всі верниє лю́ди Твої́. Сего́ ра́ди і ми ни́ні, у Тебе́ єди́ния утіше́нія і́щуще, і благода́рним се́рдцем ди́вния діла́ любве́ Твоєя́ свиді́тельствующе, а́ще і хладно єсть во ві́рі житіє́ на́ше і пу́сто от разліне́нія гріхо́внаго се́рдце на́ше, прилі́жно у Тебе́ проси́ти блага́го прише́ствія Твоєго́ подвиза́ємся, і во ви́шняя Твоя́ се́рдце под'ємлюще, єди́ними усти́ і єди́ним се́рдцем Тебі́ вопіє́м:","О, Благода́тная, к до́брому житію́ по ві́рі Христо́вой наш дух пробуди́, — жизнь нам Роди́вшая, от закосні́нія нас сохрани́.","О, Благода́тная, в наде́жді незиблемой Ти нас утверди́, — Ді́во Влади́чице, Твої́ми ві́рними вся ни соблюди́.","О, Благода́тная, сія́ страни́ до́льняя Покро́вом Твої́м осіни́, — о всіх болезнущи, во бла́го устро́їти на́шу го́ркую жизнь научи́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний, наш дух оживи́."]},{"h":"Кондак 13","ps":["О, Преблагослове́нная Ма́ти, пред Єя́же любо́вію то́чію льна куре́ніє і са́моє си́льноє жела́ніє на́ше. Умилосе́рдися на ни, Твоя́ многогрі́шния раби́, прости́ і поми́луй вся ни Твоє́ю любо́вію мо́лим Тя, помози́, да́руй ізбавле́ніє от отяготевших толи́ко літ лю́тих зол і бід ві́рному наро́ду Твоєму́, сина́ми неві́рія порабоще́нному і растлеваємому. Твоє́ ізбавле́ніє пошли — врачующеє і на́ші неду́ги душевниє, да на благо́є і ві́рноє житіє́ по благо́му зако́ну Си́на Твоєго́ при́йдем ми і да се́рдцем ісцельшіїся, і о сві́ті ві́ри на́шея святи́є ра́дующеся, сино́вне із ро́да в род благода́рною любо́вію і умиле́нієм воспіва́єм Всеблаго́му Отцю́ своєму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Тьма неві́рія і в сні глубо́ці запусті́ніє жи́зні богоподобниє об'яша до конця́ предавшийся тлі́нію род челові́чеський, і в неісходних плени́цях паде́ній гріхо́вних оковал все ни светоненавистник і дре́вній уби́йця-дия́вол, князь ми́ра сего́. Но і врага́ми соделавшихся, не преста́ла люби́ти люде́й свої́х бла́гость Творця́, нас спасающего, і Тобо́ю, о Пренепоро́чная дщер Дави́дова, обітова́л Он ізнача́ла дарова́ти погибшим Сі́м'я жени́ Христа́ Емману́їла. Се і ми ни́ні, а́ще і ослепихом очеса́ на́ша малові́рієм і ужаса́ємся глубини́ неотмитних беззако́ній свої́х, но от Тебе́, о Ма́ти Сві́та, ча́єм спасе́нія, і не і́щуще самооправданія во грісі́х неісче́тних, Тебі́ наде́ждою непозиблемою к себі́ зове́м:","О, Благода́тная, на по́мощ к нам поспіши́, — Цари́це Небе́сная, із бе́здни паде́ній нас ісхити́.","О, Благода́тная, луча́ми сві́та го́рняго всеобдержащий мрак житія́ на́шего озари́, — Ді́во Пречи́стая, сія́нієм чистоти́ Твоєя́ гріхми́ потемневшиє на́ша се́рдця освіти́.","О, Благода́тная, біжа́ти льще́ній лжі і гріха́ Ти нас научи́ — Ма́тер Святі́йшая, любо́в і ві́рность пра́вді в душі́ на́ша вложи́.","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]},{"h":"Кондак 1","ps":["Ізбра́нной Небе́сним Царе́м, превисшей і у́мних чино́в, всеблаго́й Цари́це, ро́да христия́нськаго Засту́пнице і от всіх зол і напа́стей ско́рому вспоможенію, всі ми, грі́шнії і в безмі́рних біда́х су́щії раби́ Єя́, со слеза́ми і умиле́нієм се́рдця, принесе́м покаянниє пі́нія: Ти же, я́ко премилосе́рдная Ма́ти на́ша, сама́ духоно́сному моле́нію наста́ви нас і прия́ти сія́ воздиха́нія душі́ на́шея удосто́й:","О, Благода́тная, поми́луй нас і спаси́, і пачесолнечною теплото́ю любве́ Твоєя́ гріхми́ умерщвле́нний наш дух оживи́."]}],"notes":[]},{"u":"Акафіст Архангелу Божому Гавриїлу","e":"Akathist to the Archangel of God Gabriel","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом от всіх Небе́сних Сил послужи́ти предве́чной та́йні спасе́нія ро́да челові́чеськаго, ди́вний предстоя́телю Престо́лу Святи́я Тро́йці, носи́телю тайн і чуде́с Бо́жиїх, Арха́нгеле Гавриї́ле, к тебі́ припа́даєм і умиле́нно воспіва́єм ті:","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і вся́чеських ізбра́ тя, тайнови́дче Гавриї́ле, в пречу́днем Сові́ті Святи́я Тро́йці, да послу́жиши та́йні Боговоплоще́нія, і повелі́ би́ти тебі́ носи́телем си́ли і чуде́с Бо́жиїх. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, Гавриї́ле, ізбра́нний Творцо́м служи́телю;","Ра́дуйся, Гавриї́ле, Промишле́нія Бо́жия носи́телю.","Ра́дуйся, я́ко тобо́ю хва́ляться Си́ли Небе́сния;","Ра́дуйся, я́ко тебі́ сла́в'ять сердца́ земноро́дних.","Ра́дуйся, ві́рно послужи́вий Престо́лу Святи́я Тро́йці;","Ра́дуйся, со дру́ги свої́ми сокруши́вий і ізри́нувий денни́цю.","Ра́дуйся, обличи́вий заблужде́нія того́;","Ра́дуйся, із пе́рвих піснь Трисвяту́ю воспі́вий.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 2","ps":["Ви́дя Творе́ць тя усе́рднаго і ві́рнаго служи́теля Своєго́, возлюби́ тя і вознесе́ пред А́нгельськими чи́ньми, і укрепле́нний благода́тію Єго́ в свої́х вели́ціх до́блестіх, ти воспіва́єши с ли́ки А́нгельськими усе́рдно Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом смиренному́дренно прекло́ньшеся пред та́йною непостижи́мою єдиносу́щности Святи́я Тро́йці, ти благода́тних открове́ній прия́л єси́ неістощи́мий істо́чник благогові́йнаго тре́пета, любві́ к Творцю́, і ра́дости іспо́лненний сія́єши, Арха́нгеле, пред Престо́лом Всеви́шняго, я́ко світи́льник пла́менний. О сем благогові́йно воспіва́ти дерза́єм:","Ра́дуйся, лампа́до неугаси́мая седьмисве́щника вели́каго;","Ра́дуйся, звіздо́ світоза́рная небосво́да духо́внаго.","Ра́дуйся, первоприє́мниче Боже́ственних сія́ній;","Ра́дуйся, сокро́вище Боже́ственних велі́ній.","Ра́дуйся, кла́дезь смире́нія неісчерпа́ємий;","Ра́дуйся, ріко́, послуша́нія іспо́лненная.","Ра́дуйся, я́ко ти у Престо́ла ви́ну пребива́єши;","Ра́дуйся, я́ко ти ве́ліє дерзнове́ніє к Бо́гу і́маши.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 3","ps":["Си́ли Небе́сния ра́дуються о тебі́, Арха́нгеле, і защище́нния ні́когда от зловрі́дних заблужде́ній денни́ці, в го́рдості возста́вшаго проти́в Творця́ своєго́, с весе́лієм взива́ють непреста́нно Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще ве́ліє дерзнове́ніє ко Святі́й Тро́йці, ве́лію благода́ть приє́млеши от Бо́га непреста́нно, і я́ко луч Боже́ственнаго Трисія́тельнаго Со́лнця, повсю́ду разлива́єши світ велі́ній Бо́жиїх, да сла́виться спаси́тельноє і́м'я Бо́жиє сердця́ми земноро́дних, тебе́ пою́щих:","Ра́дуйся, Небе́сних Сил Нача́льниче;","Ра́дуйся, Пра́вди ві́чния побо́рниче.","Ра́дуйся, твоя́ крі́пкая пре́данность Бо́гу чи́ни А́нгельськия укріпи́;","Ра́дуйся, чрез тебі́ Госпо́дня благода́ть їх сугу́бо просвіти́.","Ра́дуйся, і земле́ ти благода́ть от Бо́га прино́сиши;","Ра́дуйся, ти огнь небе́сний в сердця́ челові́ков низво́диши.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 4","ps":["Бу́ря злочести́вих за́мислов врага́ Бо́жия разби́ся о скалу́ ві́рности слуг Госпо́дніх, і побіди́вши свої́м смире́нієм горди́ню того́, воспе́ли Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь іспове́дованія тобо́ю вели́каго І́мені Єго́, Арха́нгеле, іспо́лнися благоволе́нія, і озари́в тя Своє́ю благода́тію, вся просвіти́ воспі́ти ті:","Ра́дуйся, адама́нте небе́сний;","Ра́дуйся, сто́лпе Це́ркві Вселе́нський.","Ра́дуйся, рая́ Госпо́дня храни́телю;","Ра́дуйся, цві́те благоче́стія.","Ра́дуйся, лучу́ престо́ла Бо́жия;","Ра́дуйся, украше́ніє порфи́ри Царя́ Христа́.","Ра́дуйся, знамено́сче Бо́жий;","Ра́дуйся, украше́ніє воєнача́льничей Небе́сних Сил.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю текл от висо́т надзве́здних, Гавриї́ле, да возвісти́ши земни́м ра́дость бли́зькаго спасе́нія, предста́л єси́ пра́ведним Іоаки́му і А́нні і провіща́л єси́ їм ми́лость Бо́жию, і ра́дуяся с ни́ми ку́пно, воспі́л Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши тя єдиновре́менно роди́телі Богоотрокови́ці, су́щії в страна́х разли́чних, сше́дшихся у две́рей хра́ма по твоєму́ глаго́лу, диви́шася і в ра́дості взива́ху ті:","Ра́дуйся, служи́телю Святи́я Тро́йці;","Ра́дуйся, ди́вний благові́стниче.","Ра́дуйся, Бо́жий ізбра́нниче;","Ра́дуйся, Госпо́дней во́лі провозві́стниче.","Ра́дуйся, я́ко тобо́ю ра́дость лю́дям прино́ситься;","Ра́дуйся, я́ко тебі́ хвала́ во сла́ву Бо́жию земноро́дними поє́ться.","Ра́дуйся, пла́нов Тво́рчеських ісполни́телю;","Ра́дуйся щедро́т Бо́жиїх раздая́телю.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 6","ps":["Пропові́дником Бо́жия милосе́рдія ти, Гавриї́ле, яви́лся Заха́рії, віща́я єму́ Боже́ственния глаго́ли і науча́я єго́ пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в благода́тію Бо́жиєю пред очи́ма Заха́рії, ужаси́л єси́ єго́, і вла́стію ті Бо́гом да́нною смири́л єси́ єго́, да не де́рзнеть сомне́нієм ума́лити си́лу Бо́жию. І умудре́нний сви́ше Заха́рія безмо́лвним у́мним гла́сом воспі́л ті такова́я:","Ра́дуйся, досто́їнств Бо́жиїх храни́телю;","Ра́дуйся, вели́кий в ли́кі А́нгельськом.","Ра́дуйся, прекра́сноє творе́ніє Творця́;","Ра́дуйся, тайн сокрове́нних ми́ру открове́ніє.","Ра́дуйся, вели́ких обі́тов Бо́жиїх соверше́ніє;","Ра́дуйся, пра́вди Бо́жієй іспо́лненний.","Ра́дуйся, благода́тію Бо́жієй осія́нний.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 7","ps":["Хотя́щу Бо́гу воплоти́тися і на землі́ яви́тися челові́ком, предста́л єси́, служи́телю, провозве́стником ко ізбра́нній от ві́ка Ді́ві і откри́л єси́ Єй во́лю созда́вшего Ю, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую і непостижи́мую та́йну Боговоплоще́нія откри́л єси́ Богоотрокови́це, Гавриї́ле сла́вне, не постига́я і сам сей вели́кой та́йни, див'я́ся безпреде́льной любві́ і милосе́рдію Бо́жию к лю́дям. О сем і ми, земноро́днії, со стра́хом і ра́достію диві́мся і вопіє́м ті си́це:","Ра́дуйся, Сові́та предві́чнаго служи́телю;","Ра́дуйся, к Богоневі́сті Бо́гом ниспо́сланний.","Ра́дуйся, Пречи́стия Ді́ви небе́сний храни́телю;","Ра́дуйся, Ма́тері Бо́жієй ди́вний служи́телю.","Ра́дуйся, Боже́ственной Отрокови́ці учи́телю;","Ра́дуйся, Єя́ хлі́бом небе́сним пита́телю.","Ра́дуйся, во Свята́я Святи́х с Не́ю глаго́лавий;","Ра́дуйся, глубини́ Бо́жия Про́мисла Єй откри́вий.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 8","ps":["Стра́нно челові́ком зрі́ти лик А́нгельський, стра́нно і глаго́ли небе́сния сли́шати, но умудре́нная Боже́ственною му́дростію Присноді́ва, не устраши́лась зра́ка твоєго́ і вознесла́ к Творцю́ і Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі в ни́жніх, узрі́л єси́ Богоотрокови́цю ви́сшую чино́в А́нгельських, Гавриї́ле, і трепе́ща откри́л єси́ Єй во́лю Влади́ки, і ужаса́ясь та́йні Боговоплоще́нія, іспо́лнися благогові́нія к Богоізбра́нной Ді́ві. Ви́дяще вели́коє твоє́ служе́ніє Престо́лу і зря́ще неізглаго́ланноє смире́ніє твоє́ пред Ді́вою, поє́м ті си́це:","Ра́дуйся, первоприє́мниче сія́ній Тро́їчеських;","Ра́дуйся, сія́ніями ті́ми осія́нний.","Ра́дуйся, благода́ті іспо́лненний;","Ра́дуйся, Присноді́ві Благода́ть прине́сший.","Ра́дуйся, в ли́кі А́нгелов ви́сших;","Ра́дуйся, пред Ді́вою Марі́єю колі́на склони́вший.","Ра́дуйся, ізбра́нній ра́дость возвісти́вий;","Ра́дуйся, і сам сей ра́дости возра́довавийся.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 9","ps":["Вся́кий чин А́нгельський превосходя́, ти пред Боже́ственною земноро́дною Богоотрокови́цею смире́нно предстої́ши, взива́я ра́достію Творцю́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йства многовіща́нния всіх виті́й челові́чеських нічто́ суть пред безгла́сною ве́твю ра́йською, тобо́ю принесе́нною, єгда́ воспі́л єси́ Святу́ю Ді́ву, благовіству́я Єй ізбра́ніє Єя́ би́ти Богома́терію і па́ки возвіща́я спаси́тельноє успе́ніє Єя́. Твоє́й вели́кой му́дрости удиви́шася земля́ і возопи́:","Ра́дуйся, смире́нія учи́телю;","Ра́дуйся, вели́ких тайн Боготво́рчеських зри́телю.","Ра́дуйся, ве́твю чистоту́ Матереде́вства Пречи́стия знамена́вий;","Ра́дуйся, благоуха́нієм кри́на ра́йськаго благоуха́ніє душі́ чисті́йшия показа́вий.","Ра́дуйся, неув'яда́нієм Цві́та небе́снаго неув'яда́ємость жи́зні Богома́тері предвеща́вий;","Ра́дуйся, смире́нной ве́твю смире́ніє ві́тві ца́рственней восхвали́вий.","Ра́дуйся, красото́ю Цві́та небе́снаго духо́вную красоту́ Присноді́ви воспі́вий;","Ра́дуйся, всю сла́ву Ді́ви Марі́ї сим ізобрази́вий.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 10","ps":["Спасе́ніє душ челові́чеських предвозвіща́я, Арха́нгеле Бо́жий, научи́л єси́ нас воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ гріхо́вная между́ не́бом і земле́ю не загради́ла путь тебі́, Арха́нгеле, но я́ко дим і мрак разсе́ялась пред свя́тостію твоє́ю і ти предста́л єси́ Пречи́стій Ді́ві благові́стником небе́сним в Назаре́ті, віща́я: «Ра́дуйся», — прине́сл єси́ Єй, сим ра́дость Воскресе́нія Христо́ва возвіща́я, і ра́ди ра́дости возвеще́нной тобо́ю Ді́ві, і чрез Ді́ву ми́ру, мир принести́ тебі́ дерза́єть:","Ра́дуйся, ра́дости ми́ру віща́ніє;","Ра́дуйся, Бо́жиїх даро́в раздая́ніє.","Ра́дуйся, Гавриї́ле, світи́льниче світоза́рний;","Ра́дуйся, друг і сослужи́тель вели́каго Архистрати́га Михаї́ла.","Ра́дуйся, звіздо́, явле́ніє со́лнця Христа́ возвісти́вий;","Ра́дуйся, мно́гажди Боже́ственній Ма́тері Єго́ послужи́вий.","Ра́дуйся, вели́ких обітова́ній Бо́жиїх соверши́телю;","Ра́дуйся, я́ко ти при гро́бі: «Воскре́се Христо́с, ність зді», — мироно́сицям возвісти́.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 11","ps":["Піснь лико́в А́нгельських прине́сл єси́ земле́ ти, Арха́нгеле, і віща́ти благогові́йноє «Досто́йно» Афо́нськия го́ри і́нока научи́л єси́, і науче́ннії тобо́ю чрез того́ лю́діє благода́рно о сем воспі́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний лик свой сокри́л єси́ ти, Гавриї́ле, обле́кшися оде́ждою і́ночеською, даби́ не ужасну́лся сме́ртний боголі́пнаго зра́ка твоєго́, но умудри́лся би пости́гнути і уясни́ти себі́ піснопі́ніє небе́сноє, і да не мни́ться пре́лестію лука́ваго і́ноку смире́нному явле́ніє чинонача́льника Сил Ви́шніх би́ти, удостове́рить і́стину явле́нія твоєго́ возжела́л єси́. Сего́ ра́ди, ка́мень ве́лій взе́мше, на нем пе́рстом безпло́тним, я́ко по во́ску, начерта́л єси́ Небе́сноє: «Досто́йно», уви́дів чу́до сіє́ ве́ліє, всі і́ноці Афо́нськия гори́ воспі́ша ті согла́сно:","Ра́дуйся, Бо́жий служи́телю;","Ра́дуйся, Боже́ственний Арха́нгеле.","Ра́дуйся, благові́стниче преди́вний;","Ра́дуйся, Богоотрокови́ці храни́телю.","Ра́дуйся, земноро́дних пе́сне Небе́сній научи́вий;","Ра́дуйся, сам пре́жде піснь сію́ ди́вную пред і́ноком воспі́вий.","Ра́дуйся, Боже́ственния слова́ чу́дно на ка́мені начерта́вий;","Ра́дуйся, сей ка́мень в зало́г і́стиннаго зна́менія твоєго́ горі́ Афо́нстій да́вий.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 12","ps":["Благода́тния твоя́ явле́нія воспомина́я, благодаре́ніє прино́сим Творцю́ і Бо́гу, спаса́ющему род челові́чеський, і поє́м Бо́гу усе́рдно: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще все нам ві́домия, Гавриї́ле, до́блести твоя́, неві́домия же ча́єм за предста́тельство твоє́ о нас уві́діти в Небе́сном Ца́рствії. Ни́ні же по си́лі на́шей дерза́єм ті воспі́ти:","Ра́дуйся, Сові́та преві́чнаго Святи́я Тро́йці предначерта́нія прия́вий;","Ра́дуйся, домострої́тельства Бо́жия все пла́ни охраня́вий.","Ра́дуйся, охране́нієм о́них Творцю́ служи́вий;","Ра́дуйся, ми́ру спасе́ніє возвісти́вий.","Ра́дуйся, Ма́тері Бо́жієй храни́телю;","Ра́дуйся, Це́ркві Христо́вой блюсти́телю.","Ра́дуйся, і Втора́го прише́ствія Христо́ва на зе́млю возвісти́телю;","Ра́дуйся, я́ко ти преди́деши Си́лам Небе́сним с вели́ким тру́бним гла́сом в день Стра́шнаго Суда́ Бо́жия.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 13","ps":["О ди́вний тайнови́дче і пресла́вний Арха́нгеле, вели́ко дерзнове́ніє твоє́ пред Го́сподом і си́льна моли́тва твоя́. Припа́даєм к тебі́ і мо́лим, Гавриї́ле пречу́дне, прийми́ нас немощни́х под кров крил твої́х і защити́ от ко́зней враго́во ви́димих і неви́димих. Пом'яни́ нас недосто́йних в твоє́м предста́тельстві пред Престо́лом Всеви́шняго, да воспоє́м Єму́ по неізрече́нному милосе́рдію Єго́ в Ца́рстві Сла́ви с лико́м А́нгелов і всі́ми святи́ми: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і вся́чеських ізбра́ тя, тайнови́дче Гавриї́ле, в пречу́днем Сові́ті Святи́я Тро́йці, да послу́жиши та́йні Боговоплоще́нія, і повелі́ би́ти тебі́ носи́телем си́ли і чуде́с Бо́жиїх. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, Гавриї́ле, ізбра́нний Творцо́м служи́телю;","Ра́дуйся, Гавриї́ле, Промишле́нія Бо́жия носи́телю.","Ра́дуйся, я́ко тобо́ю хва́ляться Си́ли Небе́сния;","Ра́дуйся, я́ко тебі́ сла́в'ять сердца́ земноро́дних.","Ра́дуйся, ві́рно послужи́вий Престо́лу Святи́я Тро́йці;","Ра́дуйся, со дру́ги свої́ми сокруши́вий і ізри́нувий денни́цю.","Ра́дуйся, обличи́вий заблужде́нія того́;","Ра́дуйся, із пе́рвих піснь Трисвяту́ю воспі́вий.","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом от всіх Небе́сних Сил послужи́ти предве́чной та́йні спасе́нія ро́да челові́чеськаго, ди́вний предстоя́телю Престо́лу Святи́я Тро́йці, носи́телю тайн і чуде́с Бо́жиїх, Арха́нгеле Гавриї́ле, к тебі́ припа́даєм і умиле́нно воспіва́єм ті:","Ра́дуйся, Гавриї́ле, тайнозри́телю Святи́я Тро́йці."]},{"h":"Молитва","ps":["О, святи́й вели́кий Арха́нгеле Гавриї́ле, Бо́жию Престо́лу предстоя́й і озаре́нієм от Боже́ственнаго сві́та осія́нний, ві́дінієм же непостижи́мих тайн о преві́чній Прему́дрости Єго́ просвіще́нний! Всеусе́рдно молю́ тя, наста́ви м'я к покая́нію от злих діл і ко утвержде́нію во ві́рі моє́й, укріпи́ і огради́ ду́шу мою́ от іскуше́ній прельсти́тельних і умоли́ Созда́теля на́шего о отпуще́нії гріхо́в мої́х. О, святи́й вели́кий Гавриї́ле Арха́нгеле! Не пре́зри мене́ грі́шнаго моля́щаго теб'я́ о по́мощі і заступле́нії твоє́м во ві́ці сем і в бу́дущем, но при́сно помо́щник мні яви́ся, да непреста́нно сла́влю Отця́ і Си́на і Свята́го Ду́ха держа́ву і твоє́ предста́тельство во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Небе́сних во́їнств Архістрати́же, / мо́лим тя при́сно ми недосто́йнії, / да твої́ми моли́твами огради́ши нас / кро́вом крилу́ невеще́ственния твоєя́ сла́ви, / сохраня́я нас, припа́дающих прилі́жно і вопію́щих: / от бід ізба́ви нас, // я́ко чинонача́льник Ви́шніх сил."]},{"h":"Кондак, глас 8","ps":["Пресві́тлия і Честни́я, і Вседі́тельния, / пренеісче́тния і стра́шния Тро́йці, / ти єси́, Архістрати́же, сла́вний служи́телю і моли́твенниче, / ни́ні непреста́нно моли́ / ізба́витися нам от вся́ких бід і мук, да зове́м ті: // ра́дуйся, покро́ве рабо́м твої́м."]},{"h":"Інший кондак, глас 2","ps":["На Небесі́х зря Бо́жию сла́ву / і на землі́ с висоти́ подая́ благода́ть, / нача́льниче А́нгелов, му́дре Гавриї́ле, Бо́жия сла́ви служи́телю / і ми́ра Боже́ственний побо́рниче, / спаса́й, соблюда́й вопію́щия ті: // сам бу́ди помо́щник, і нікто́же на ни."]},{"h":"Величання","ps":["Велича́єм вас, / Арха́нгели і А́нгели / і вся во́їнства, / Херуви́ми і Серафи́ми, // сла́в'ящия Го́спода."]}],"notes":[]},{"u":"Акафіст Архангелу Рафаїлу","e":"Akathist to the Archangel Raphael","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом от Во́їнства Небе́снаго і низпосланний на зе́млю в служе́ніє ро́ду челові́чеському, святи́й Арха́нгеле Рафаї́ле, ціле́бниче неду́гов на́ших і моли́твенниче о нас пред Го́сподем, помози́ нам ізба́витися от бід, скорбе́й і болі́зней, с ві́рою і любо́вію в похвалу́ тебі́ зовущим:","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Ікос 1","ps":["Арха́нгели, і А́нгели, і вся Во́їнства Небе́сная, предстоя́ще пред Престо́лом Святи́я Тро́йці, непреста́нно славосло́в'ять Творця́ не́ба і землі́; с ни́ми же і ти, сла́вний Рафаї́ле, воспіва́я хвале́бния пі́сні Вседержи́телю, мо́лишися о нас, земноро́дних, похва́льноє пі́ніє принося́щих тебі́ сицево́є:","Ра́дуйся, предстоя́щий Престо́лу Святи́я Тро́йці.","Ра́дуйся, со всі́ми Небе́сними Си́лами воспіва́ющий Трисвяту́ю піснь Бо́гові.","Ра́дуйся, на служе́ніє лю́дем от Го́спода низпосилаємий.","Ра́дуйся, во́лю Бо́жию ви́ну ісполня́ющий.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 2","ps":["Ви́дяще очеса́ми ві́ри си́лу і вели́чіє молнієно́снаго зра́ка твоєго́, Арха́нгеле Бо́жий, ми, земноро́днії, а́ще у́бо і грі́шнії, і недосто́йнії, оба́че с любо́вію і благодаре́нієм дерза́єм вку́пі с тобо́ю і со всі́ми святи́ми А́нгели взива́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум чист і свобо́ден от страсте́й іспроси́ нам, Арха́нгеле Бо́жий Рафаї́ле, і не оста́ви нас, беззащи́тних, в борбі́ со гріхо́м і соблазнами ми́ра сего́, да тобо́ю от ві́чних мук ізбавля́ємі, в ра́дості духо́вній воззове́м ті си́це:","Ра́дуйся, безпло́тний во́їне Царя́ Небе́снаго.","Ра́дуйся, немощни́х ціле́бниче і путеше́ствующих покрови́телю.","Ра́дуйся, слуго́ Госпо́день, творя́щий во́лю своєго́ Влади́ки.","Ра́дуйся, приє́мий от Бо́га повелі́ніє і власть челові́ком помога́ти.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 3","ps":["Си́лу необори́мия ре́вности по сла́ві Бо́жієй в себі́ явля́я, помози́ нам, Арха́нгеле Рафаї́ле, вся ко́зні вра́жия, на нас воздвиза́ємия, разруши́ти, Творцю́ і Созда́телю на́шему с ві́рою і любо́вію вопія́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще тя вели́каго помо́щника і крі́пкаго побо́рника на сопроти́вния си́ли, мо́лим тя, Арха́нгеле Бо́жий: бу́ди нам покрови́тель на всіх путеіх жи́зні на́шея, да со благодаре́нієм взива́єм ті си́це:","Ра́дуйся, я́ко споспешествуєши нам во вре́меннім житії́ на́шем.","Ра́дуйся, я́ко на путь спасе́нія стопи́ на́ша наставля́єши.","Ра́дуйся,я́ко за́повіді Госпо́дні ісполня́ти нас науча́єши.","Ра́дуйся, я́ко от зла і гріха́ нас сохраня́єши.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 4","ps":["Бу́ри іскуше́ній і бід нас ізба́ви, Арха́нгеле Бо́жий, і не оста́ви нас безпомо́щних в ско́рбния дні жите́йських обстоя́ній і болі́зней, за беззако́нноє житіє́ нам попущаємия. Ми же, тобо́ю от напа́стей ізбавля́ємі, благодаря́ще тя, воззове́м Бо́гу, Благода́телю на́шему:Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще о твої́х благодія́ніях ро́ду челові́чеському, смире́нно мо́лим тя, Арха́нгеле Рафаї́ле: бу́ди нам в земні́м стра́нствії на́шем непреста́нний помо́щник і к Ца́рствію Небе́сному ві́рний руководи́тель, да зове́м ті хвале́бно:","Ра́дуйся, предста́телю наш пред Бо́гом і моли́твенниче.","Ра́дуйся, я́ко со Арха́нгелами Михаї́лом, Гавриї́лом, Уріїлом, Селафіїлом, Ієгудіїлом, Варахіїлом і Ієреміїлом непреста́нно прославля́єши Святу́ю Тро́йцю.","Ра́дуйся, ми́лостивий хода́таю о нас пред Бо́гом.","Ра́дуйся, ско́рий помо́щниче во обстоя́нії су́щим.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 5","ps":["Путеводительною звіздо́ю бил єси́, Арха́нгеле Бо́жий, о́троку Тові́ї, єгда́ оте́ць посла́ єго́ к сро́днику своєму́ в страну́ дале́че: і не то́кмо спу́тник до́брий бил єси́ єму́, но і врачеватель ізря́дний показа́ся, єгда́ повелі́л єму́ в ріці́ ри́бу ізловити і із'яти із нея́ се́рдце, пе́чень і желч, да сі де́мона-уби́йцю кажде́нієм от діви́ці отженети сліпоту́ отця́ своєго́ уврачу́єть. Сего́ ра́ди тобо́ю облагодетельствовани, воспі́ша Бо́гу благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще тя благонаде́жна спу́тника Тові́ї би́вша, мо́лим тя: бу́ди нам помо́щник в житії́ на́шем многом'яте́жнім, сохраня́я нас от гріха́, вся́каго зла́го обстоя́нія і от враго́во ви́димих і неви́димих, да здра́ві су́ще, в ми́рі і благоде́нствії просла́вим Отця́ Небе́снаго і тебі́, Арха́нгеле, воспої́м си́це:","Ра́дуйся, путеше́ствовати хотя́щим до́брий спутниче і руководи́телю.","Ра́дуйся, о́троку Тові́ї путь єго́ безм'яте́жен сотвори́вий.","Ра́дуйся, му́дрий і до́брий советодатель єму́ би́вий.","Ра́дуйся, я́ко по твоєму́ словесі́, воскуренієм се́рдця і пе́чени в жили́ще діви́ці, де́мон-уби́йця ізгна́н бисть.","Ра́дуйся, я́ко Тови́т пома́занієм оче́с же́лчію ри́би от сліпоти́ ісціли́ся.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь служе́ніє твоє́ ро́ду челові́чеському, святи́й Арха́нгеле, я́ко провозві́стника суде́б Бо́жиїх і моли́твенника. Сего́ ра́ди благода́рним се́рдцем і усти́ поє́м Бо́гу, благоізво́лившему посла́ти нам А́нгели Своя́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возвісти́во во́лю Бо́жию Тови́ту, Арха́нгеле Бо́жий, ти, предста́в пред ним а́ки ю́ноша добронравний, предложи́в себі́ в спу́тники си́ну єго́ Тові́ї в путь да́льній; і єгда́ соверши́в повелі́нная ті от Бо́га і возврати́в о́трока здра́ва і благополу́чна, отше́л єси́ в Небе́сния оби́телі к Посла́вшему тя. Сего́ ра́ди с любо́вію вопіє́м ті:","Ра́дуйся, провозві́стниче суде́б Бо́жиїх і до́брий путеводи́телю.","Ра́дуйся, я́ко ви́ну хода́тайствуєши пред Бо́гом о всіх боля́щих і стра́ждущих.","Ра́дуйся, я́ко возно́сиши моли́тви на́ша ко Престо́лу Вседержи́теля.","Ра́дуйся, я́ко пра́ведний гнів Бо́жий, на нас дви́жимий, твої́м предста́тельством отвраща́єши.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 7","ps":["Хотя́й всім спасти́ся і в ра́зум і́стини прийти́, сердцеві́дець Госпо́дь посила́єть А́нгели Своя́ на служе́ніє челові́ком, дая́ коєму́ждо своє́ послуша́ніє. Тебі́ же, сла́вний Арха́нгеле, даде́ Бог власть і си́лу врачева́ти болі́зні тіле́сния і душе́вния і би́ти спутником путешествующим. Ми же, за таково́є твоє́ служе́ніє нам, грі́шним, благода́рним се́рдцем і усти́ сла́вим Милосе́рдаго Бо́га а́нгельською пі́снію: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно показу́я Госпо́дь, я́ко жизнь челові́чеськая не самослучайна суть, но в десни́ці Єго́ ви́ну содержи́ться, мно́гая благодія́нія яви́ нам чрез Арха́нгела Своєго́ Рафаї́ла. Сего́ ра́ди, благодаря́ще Бо́га за ве́лію ми́лость Єго́ к нам, я́ко дарова́ нам толи́каго помо́щника і ціли́теля, со умиле́нієм служи́телю Єго́ воззове́м:","Ра́дуйся, христия́ном несокруши́мая огра́до.","Ра́дуйся, враго́м ві́ри Христо́ви необори́мая прегра́до.","Ра́дуйся, ві́рним ра́дость от Престо́ла Вседержи́теля ізносящий.","Ра́дуйся, неві́рних на стезю́ пра́вди і і́стини приводя́щий.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до си́ли Бо́жия уві́де на себі́ Товія, єгда́ той, по рече́нному тобо́ю, Арха́нгеле, із Са́рри зла́го ду́ха кажде́нієм ізгна́. Ми же, удивля́яся сему́, с тре́петом і ві́рою вопіє́м Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім у́бо хо́щеши спасти́ся, при́сний наш хода́таю, Арха́нгеле Рафаї́ле: помози́ у́бо нам, засту́пниче наш, в житії́ на́шем і сохрани́ нас от дія́ній і помишле́ній гріхо́вних, вопію́щих тебі́ си́це:","Ра́дуйся, ти́хую ра́дость на се́рдці полага́яй.","Ра́дуйся, душі́ на́ша умиле́нія ісполня́яй.","Ра́дуйся, ві́рний руководи́телю в земно́м стра́нствії на́шем.","Ра́дуйся, ско́рий помо́щниче всім призива́ющим тя.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 9","ps":["Всяк земноро́дний, позна́в ско́рую по́мощ твою́, ра́дости благогові́йния ісполня́ється, я́ко імі́єть такова́го моли́твенника і предста́теля у Престо́ла Святи́я Тро́йці, іді́же ти, о, Арха́нгеле Бо́жий, непреста́нно взива́єши: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к не возмо́жеть ізрещи́ сла́ву твою́ на небесі́, святи́й Арха́нгеле Рафаї́ле, с о́гненними ли́ки Небе́сних Сил у стра́шнаго Престо́ла Царя́ ца́рствующих і Го́спода госпо́дствующих предстоя́щаго, і бла́гость і милосе́рдіє Єго́ о чту́щих тя лю́діх умоля́ющаго. Ми же, благогові́нія і тре́пета іспо́лнені, благода́рственно вопіє́м ті:","Ра́дуйся, ві́рний слуго́ Госпо́день, возвіща́ющий лю́дем во́лю Бо́жию.","Ра́дуйся, А́нгелов нача́льниче і челові́ков наста́вниче і засту́пниче.","Ра́дуйся, ум наш просвіща́яй твої́ми моли́твами.","Ра́дуйся, я́ко лю́б'ящих і чту́щих тя ізбавля́єши от бід і обстоя́ній.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим нам бу́ди помо́щник крі́пок, Арха́нгеле Рафаї́ле, избавля́я нас і сохраня́я от вся́ких бід і напа́стей, найпа́че же от гріхопаде́ній на́ших. Сего́ ра́ди от сіте́й вра́жиїх тобо́ю при́сно ізбавля́ємі, благода́рним се́рдцем і усти́ зове́м Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ тве́рда і огражде́ніє всім, прибегающим к твоєму́ заступленню і по́мощі, Арха́нгеле Бо́жий: сего́ ра́ди сохраня́й нас под кро́вом крил твої́х от кова́рства враго́во ви́димих і невидимих, да тобо́ю от болі́зней ісцеляємі і в путі́ тобо́ю храни́мі, благода́рно взива́єм ті си́це:","Ра́дуйся, я́ко дана́ тебі́ власть і си́ла отража́ти де́монськия на нас нападе́нія.","Ра́дуйся, я́ко от вся́ких ко́зней дия́вольських нас защища́єши і спаса́єши.","Ра́дуйся, я́ко моли́тви на́ша, я́ко кади́ло, к Бо́гу возно́сиши.","Ра́дуйся, я́ко не́мощі на́ша душе́вния і тіле́сния ми́лостивно врачу́єши.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце на небесі́х непреста́нно воспіва́ють чи́ни А́нгельстії, со стра́хом взива́юще: «Свят, Свят, Свят Госпо́дь Савао́ф, іспо́лнь не́бо і земля́ сла́ви Твоєя́»; помози́ же і нам, Арха́нгеле Бо́жий, на землі́ чи́стим се́рдцем і усти́ та́кожде воспіва́ти Трієди́ному Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник мой угасе́, єле́я же до́брих діл ність во мні; сном гріхо́вним отягче́нний, трепе́щу, боя́ся усли́шати в полу́нощі глас: «Се Жени́х гряде́ть!» Помози́ мні, Арха́нгеле Бо́жий, воспрянути от сна гріхо́внаго і напо́лнити сосу́д душі́ моєя́ єле́єм благи́х діл, да приношу́ ті пі́ніє сіє́:","Ра́дуйся, я́ко по Бо́зі і Пресвяті́й Богоро́дице ти єси́ крі́пкоє моє́ упова́ніє.","Ра́дуйся, я́ко те́плим предста́тельством твої́м хода́тайствуєши мні христия́нськую кончи́ну.","Ра́дуйся, я́ко в час сме́рти моєя́ яви́тися і защити́ти ду́шу мою́ от злих де́монов тя умоляю.","Ра́дуйся, я́ко на Стра́шнім Суді́ Христо́вом хода́тайством твої́м десна́го предстоя́нія сподо́битися упова́ю.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 12","ps":["Благода́ть ве́лію прия́л єси́ от Бо́га ціли́ти вся́ку болі́знь і вся́ку я́зву в лю́діх, о, вели́кий Арха́нгеле Рафаї́ле: пода́ждь у́бо і на́шим душа́м і тілесе́м ісціле́ніє от неду́гов нас гнетущих, да здра́ві су́ще, благода́рно воспоє́м Бо́гу: Алиллуя."]},{"h":"Ікос 12","ps":["Пою́ще многообра́зная твоя́ чудеса́ во спасе́ніє на́ше соді́янная, хва́лим тя всі, святи́й покрови́телю наш і те́плий предста́телю о нас пред Го́сподем, і мо́лим: не оста́ви нас зді, в земні́м стра́нствії на́шем і та́мо, на Стра́шнім Суді́ Бо́жиєм, бу́ди нам крі́пкий засту́пник і помо́щник, да безпреткнове́нно пре́йдем мита́рства злих духо́в і Ца́рствіє Небе́сноє унаслі́дуєм, зову́ще тебі́ си́це:","Ра́дуйся, немощни́х ду́хом си́лою благода́ті Бо́жия ісполня́яй.","Ра́дуйся, сиро́т, боля́щих і безпомо́щних благи́й уті́шителю.","Ра́дуйся, ізнемога́ющих от уни́нія і скорбе́й всеору́жієм ві́ри і наде́жди облекаяй.","Ра́дуйся, я́ко твої́ми моли́твами чту́щії тя оставле́ніє гріхо́в приє́млють.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 13","ps":["О, пресла́вний Арха́нгеле Бо́жий Рафаї́ле! За преди́вноє служе́ніє твоє́ ро́ду челові́чеському прийми́ от нас, грі́шних і недосто́йних, сіє́ ма́лоє хвале́ніє і благодаре́ніє і, я́ко іспо́лнь си́ли Бо́жієй, покри́й нас невеще́ственнима крило́ма твої́ма от всіх враг ви́димих і неви́димих, умоли́ Христа́ Бо́га сподо́битися нам христия́нськия ми́рния кончи́ни, ізбавле́нія ві́чних мук і Ца́рствія Небе́снаго наслі́дія, да вку́пі с тобо́ю і со всі́ми святи́ми ра́достно воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгели, і А́нгели, і вся Во́їнства Небе́сная, предстоя́ще пред Престо́лом Святи́я Тро́йці, непреста́нно славосло́в'ять Творця́ не́ба і землі́; с ни́ми же і ти, сла́вний Рафаї́ле, воспіва́я хвале́бния пі́сні Вседержи́телю, мо́лишися о нас, земноро́дних, похва́льноє пі́ніє принося́щих тебі́ сицево́є:","Ра́дуйся, предстоя́щий Престо́лу Святи́я Тро́йці.","Ра́дуйся, со всі́ми Небе́сними Си́лами воспіва́ющий Трисвяту́ю піснь Бо́гові.","Ра́дуйся, на служе́ніє лю́дем от Го́спода низпосилаємий.","Ра́дуйся, во́лю Бо́жию ви́ну ісполня́ющий.","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом от Во́їнства Небе́снаго і низпосланний на зе́млю в служе́ніє ро́ду челові́чеському, святи́й Арха́нгеле Рафаї́ле, ціле́бниче неду́гов на́ших і моли́твенниче о нас пред Го́сподем, помози́ нам ізба́витися от бід, скорбе́й і болі́зней, с ві́рою і любо́вію в похвалу́ тебі́ зовущим:","Ра́дуйся, Арха́нгеле Бо́жий Рафаї́ле, неду́гов на́ших ціли́телю і усе́рдний о нас моли́твенниче."]},{"h":"Молитва","ps":["О, святи́й, сла́вний Арха́нгеле Бо́жий Рафаї́ле, ско́рий помо́щниче і те́плий пред Бо́гом о нас засту́пниче і моли́твениче! Предстоя́ пред Престо́лом Святи́я Тро́йці, іспроси́ нам у Го́спода проще́ніє согріше́ній на́ших, да преложи́ть Он на ми́лость гнів Свой пра́ведний, гріх ра́ди на́ших дви́жимий на нас. Не оста́ви же нас, о, Арха́нгеле Бо́жий, по́мощію і заступле́нієм твої́м, прославля́ющих і́м'я твоє́ свято́є, а́ще і многогрі́шни єсьми́, оба́че не хо́щем в беззако́ніїх на́ших поги́бнути. Укріпи́ благода́тію Госпо́днею сла́бую во́лю на́шу на діла́ блага́я; бу́ди і нам, я́коже о́троку Тові́ї, путеводи́тель і советодатель в на́шем многоско́рбнім житії́; помози́ нам ізба́витися от гнетущих нас болі́зней, я́коже і Тови́та ізба́вил єси́ от многолетней сліпоти́ єго́; єгда́ же приблизиться час сконча́нія на́шего, не оста́ви нас, беззащи́тних, Арха́нгеле Бо́жий, на возду́шних мита́рствах проти́ву духо́в зло́би, преграждающих восхо́д в го́рняя: да тобо́ю охраня́ємі, дости́гнем оби́телей Небе́сних і ку́пно с тобо́ю і со всі́ми святи́ми просла́вим Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Небе́сних во́їнств Архістрати́же, / мо́лим тя при́сно ми, недосто́йнії, / да твої́ми моли́твами огради́ши нас / кро́вом крил невеще́ственния твоєя́ сла́ви, сохраня́я ни, припа́дающия прилі́жно і вопію́щия: / от бід ізба́ви ни, // я́ко чинонача́льник ви́шніх Сил."]},{"h":"Кондак, глас 2","ps":["Архістрати́же Бо́жий, / служи́телю Боже́ственния сла́ви, / А́нгелов нача́льниче і челові́ков наста́вниче, / поле́зноє нам проси́ і ве́лію ми́лость, // я́ко Безпло́тних Архістрати́г."]},{"h":"Величання","ps":["Велича́єм вас, / Арха́нгели і А́нгели / і вся во́їнства, / Херуви́ми і Серафи́ми, // сла́в'ящия Го́спода Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст до Святого Причастя","e":"Akathist before Holy Communion","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Женише́ душ і серде́ць, вочелові́ченієм Свої́м і сме́ртію на Кресті́, обручи́вий Себе́ на ві́ки весь род челові́ч, і да́вий нам в зало́г ві́чния жи́зні са́моє пречи́стоє Ті́ло і Кров Свою́, се по гла́су Твоєму́ і аз, недосто́йний, дерза́я прихожду́ к боже́ственной трапе́зі Твоє́й і, пораже́н вели́чієм єя́, вопію́:","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Ікос 1","ps":["А́нгела Твоєго́ к прови́дцю Іса́її со у́глем горя́щим от алтаря́ небе́снаго посла́л єси́, во є́же очи́стити тім устні́ єго́, єгда́ ви́дів Тя, сідя́ща на престо́лі, о нечистоті́ своє́й сокруша́шеся; аз же, оскверне́нний душе́ю і ті́лом, ка́ко дерзну́ приступи́ти ко причаще́нію Боже́ственних Твої́х Та́їн, а́ще не Ти Сам очи́стиши м'я сви́ше? Ті́мже із глубини́ душі́ вопію́ Ті:","Ісу́се Всеблаги́й, косни́ся огне́м благода́ті Твоєя́ і мої́х нечи́стих усте́н;","Ісу́се, попали́ те́рніє мої́х мно́гих прегріше́ній.","Ісу́се, сози́жди во мні се́рдце чи́сто, і обнови́ во утро́бі моє́й дух пра́вий;","Ісу́се, ізведи́ із темни́ці страсте́й бі́дную ду́шу мою́.","Ісу́се, потреби́ во мні нечи́стия по́мисли і зла́я похоті́нія;","Ісу́се, напра́ви сла́бия стопи́ моя́ на путь за́повідей Твої́х.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 2","ps":["Жела́нієм возжела́вий я́сти со ученики́ послі́днюю пред страда́нієм Твої́м па́сху, да препода́си їм, среди́ єя́, послі́дній і найбо́льшій зало́г любві́ Твоєя́, пре́жде двою́ дню предпосла́л єси́ два от них во Ієрусали́м, да ше́дше угото́вають ю. Поуча́яся отсю́да, ка́ко і нам подоба́єть благовре́менні уготовля́ти себі́ к сніде́нію на́шея Боже́ственния Па́схи, си́річ Ті́ла і Кро́ві Твоєя́, благода́рственно зову́ Ті: Аллилу́я."]},{"h":"Ікос 2","ps":["«Іззу́й сапоги́ от но́гу твоє́ю, земля́ бо, на не́йже стої́ши, свята́я єсть», — рекл єси́ Моїсе́ю із купини́, горе́вшей і несгора́вшей, от неви́димаго во о́ной прису́тствія Твоєго́. Сосу́д с Боже́ственним Ті́лом і Кро́вію Твоє́ю воі́стину бо́ліє і святе́є неопали́мия купини́ єсть; аз же пе́рстен, нечи́ст, про́дан под гріх. Ті́мже со смире́нієм і ві́рою вопію́ Ті:","Ісу́се Всемогу́щий, совлеки́ м'я ве́тхаго челові́ка с дія́ньми єго́;","Ісу́се, умертви́ сі́м'я тлі, во мні гніздя́щеєся.","Ісу́се, расто́ргни у́зи гріха́, і́миже связа́ м'я враг;","Ісу́се пода́ждь мі се́рдце смире́нно і дух сокруше́н.","Ісу́се, отжени́ от мене́ іскуше́нія і собла́зни;","Ісу́се, утверди́ м'я во ві́рі і любві́ к Тебі́.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 3","ps":["«Отці́ ва́ші ядо́ша ма́нну в пусти́ні і умро́ша; Аз єсьм Хліб, сходя́й с небесе́, да а́ще кто ясть от него́, жив бу́деть во ві́ки; і Хліб, єго́же Аз дам, Плоть Моя́ єсть, ю́же Аз дам за живо́т ми́ра», — рекл єси́ іуде́ом, іска́вшим ви́діти от Тебе́ зна́меніє с небесі́, подо́бноє ма́нні Мойсе́євой. Єго́ же ми сли́шаще і сбитіє́ предрече́ннаго ви́дяще, со стра́хом зове́м: Аллилу́я."]},{"h":"Ікос 3","ps":["«Воста́в с ве́чері, — я́коже повіству́єть святи́й Іоа́нн, — і препоя́сався ле́нтієм, уми́л єси́ но́ги ученико́м», науча́я сим, да не приступа́єм к Боже́ственній трапе́зі Твоє́й, неоми́тиє слеза́ми покая́нія, во греха́х на́ших. Ощуща́я презі́льную ну́жду сего́ та́їнственнаго омове́нія і ску́дость слез ожесточе́ннаго се́рдця моєго́, с Петро́м вопію́ Ті:","Ісу́се Преблаги́й, Сам мі уми́й не но́зі то́кмо, но і ру́ці і главу́;","Ісу́се, обнажи́ предо мно́ю бе́здну душе́внаго моєго́ растлі́нія.","Ісу́се, разве́рзі во мні істо́чник сокруше́нія серде́чнаго;","Ісу́се, ороси́ м'я ка́плями Твоєго́ милосе́рдія.","Ісу́се, обве́й м'я стра́хом суда́ і мук ві́чних;","Ісу́се, возбуди́ со́вість, спя́щую во мні, і укріпи́ глас єя́.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 4","ps":["«Не сей ли єсть Ісу́с, син Іо́сифов, Єго́же ми зна́єм отця́ і ма́тер? Ка́ко у́бо глаго́леть Сей, я́ко с небесе́ снидо́х? І ка́ко мо́жеть да́ти нам Плоть Свою́ я́сти?» — глаго́лаху между́ собо́ю жи́дове, усли́шавше о пресла́вном обіща́нії Твоє́м да́тися в снідь ві́рним, не ві́дуще, по окамене́нію серде́ць свої́х, со смире́нієм ві́ровати і взива́ти к Тебі́: Алли́луїя."]},{"h":"Ікос 4","ps":["«А́ще не сні́сте Пло́ті Си́на Челові́чеськаго і не піє́те Кро́ве Єго́, живота́ не і́мате в себі́», — провіща́л єси́ ко́сним во є́же ві́ровати іуде́ом, є́же сло́во же́стоко к сли́шанію показа́ся і ні́киїм от учени́к Твої́х, неві́дущим єще́ та́їн Ца́рствія Бо́жия. Ми же, озаре́нниє сві́том Єва́нгелія і открове́нним лице́м Боже́ственную сла́ву Твою́ зря́ще, с ві́рою і любо́вію зове́м Ті:","Ісу́се, вся моги́й вели́чеством си́ли і держа́ви Твоєя́;","Ісу́се, творя́й і соверша́яй па́че, не́же мо́жем разумі́ти і поми́слити.","Ісу́се, ма́нну с не́ба, ні́когда в зна́меніє настоя́щаго та́їнства, одожди́вий;","Ісу́се, к прообразова́нію того́жде, во́ду із ка́мене істочи́вий.","Ісу́се, о́блак кра́стелей в напита́ніє а́лчущим в пусти́ні іуде́ом посла́вий;","Ісу́се, пред о́чію сами́х сумня́щихся іуде́єв, п'ятію́ хлі́би п'ять ти́сящ наро́да наси́тивий.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 5","ps":["«Яду́щим на ве́чері ученико́м, приє́м хліб, благослови́в і преломи́в, по́дал єси́ їм, рек: приймі́те, яді́те, сіє́ єсть Ті́ло Моє́, за ви ломи́моє, во оставле́ніє гріхо́в; пото́м же ча́шу пода́в, рекл єси́: пи́йте от нея́ всі, сія́ єсть Кров Моя́, за ви ізлива́ємая, во оставле́ніє гріхо́в». — Сему́ боже́ственному і пресла́дкому гла́су вне́млюще, со благодаре́нієм зове́м: Аллилу́я."]},{"h":"Ікос 5","ps":["«Яди́й Мою́ Плоть і пія́й Мою́ Кров во Мні пребива́єть і Аз в нем; той і́мать живо́т ві́чний і Аз воскрешу́ єго́ в послі́дній день», сі єсть во воскресе́ніє живота́ і блаже́нства. Сего́ у́бо вожделі́ннаго воскресе́нія в живо́т іща́ сподо́битися, із глубини́ душі́ вопію́ Ті:","Ісу́се, прибли́зися ко і́щущему соєдине́нія с Тобо́ю;","Ісу́се, вни́ди во утро́бу, во вся соста́ви і вся ко́сті моя́.","[Ісу́се, бу́ди сві́том моєго́ помраче́ннаго ума́;]","Ісу́се, напо́лни Собо́ю ненаси́тимую всім ми́ром бе́здну моєго́ се́рдця.","Ісу́се, віща́й гла́сом моєя́ со́вісти;","Ісу́се, дви́жи і управля́й моє́ю во́лею.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 6","ps":["«Амі́нь, амі́нь, глаго́лю вам: єди́н от вас преда́сть М'я», — рекл єси́ в ско́рбі ду́ха ученико́м Твої́м на ве́чері. Они́ же, а́ще і чи́сти от за́мисла преда́нія, «єда́ аз єсьм», вопроша́ху Тя ки́йждо, показу́я сим глубину́ своєго́ смиренному́дрія. Аз же, что реку́ Ті, седьми́жди на день па́даяй і ізміня́яй Тебі́? Оба́че Ти Сам соблюди́ м'я, да не отпаду́ в коне́ць, взива́я Ті благода́рні: Аллилу́я."]},{"h":"Ікос 6","ps":["«Я́коже розга́ не мо́жеть плода́ твори́ти о себі́, а́ще не бу́деть на лозі́, та́ко і ви, а́ще во Мні не пребу́дете; а і́же бу́деть во Мні і Аз в нем, той сотвори́ть плод мног», — си́це, тайноде́йствуя, поуча́л єси́ возлю́бленниє ученики́ Твоя́ на путі́ в Гефсима́нію. Сему́ у́бо наставле́нію вне́мля, і ві́дий не́мощ єстества́ моєго́ без благода́ті Твоє́й, прилі́жно вопію́ Ті:","Ісу́се, пренебе́сний ді́лателю, Сам м'я всади́ в живоно́сний вертогра́д Твой;","Ісу́се, лоза́ і́стинная, прикрепи́ м'я к Тебі́, я́ко ро́згу ди́кую.","Ісу́се, ко́реню неізсиха́ющий, іспо́лни м'я со́ком жи́зні ві́чния;","Ісу́се, побіди́телю вся́кия ме́ртвенности, отреби́ є́же ізсо́хло єсть во мні от зно́я страсте́й.","Ісу́се, кра́сний добро́тою, украси́ м'я цвіта́ми благи́х чувств і помишле́ній;","Ісу́се, бога́тий в ми́лості, уще́дри м'я плода́ми і́стиннаго покая́нія і пра́вди.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 7","ps":["«І кто єсть предая́й Тя», — вопроси́вшу ученику́, і́же возлеже́ на ве́чері на пе́рсях Твої́х. — «Той єсть, — отвіща́л єси́, — єму́же Аз, омочи́во в соли́ло хліб, пода́м». І омо́ч хліб, по́дал єси́ Іу́ді Си́монову Іскаріо́тському, подвиза́я єго́ на покая́ніє. Он же, ожесточе́н сий ду́хом зло́би, не восхоті́ разумі́ти гла́са любве́ своєго́ Учи́теля і Го́спода. Какова́го жестокосе́рдія да бу́ду ізба́влен благода́тію Твоє́ю, зов'я́ Ті ви́ну: Аллилу́я."]},{"h":"Ікос 7","ps":["Щадя́ не́мощ єстества́ на́шего, отвраща́ющагося вкуше́нія пло́ті челові́чеськой, не я́ві, но под ви́дом хлі́ба і вина́ благоволи́л єси́ препода́ти нам Пречи́стоє Ті́ло і Кров Твою́. Чудя́ся о таково́м снисхожде́нії прему́дрости Твоєя́ к не́мощі єстества́ на́шего, благода́рні славосло́влю Тя си́це:","Ісу́се, прему́дре і человіколю́бне стро́яй все ді́ло спасе́нія на́шего;","Ісу́се, са́мия спаси́тельния та́їнства Твої́ приспособля́яй к не́мощі на́шего разумі́нія і чувств.","Ісу́се, во увіре́ніє сумня́щихся на свято́й трапе́зі мно́гажди вмі́сто хлі́ба і вина́, са́моє Ті́ло і Кров Твою́ прояви́вий;","Ісу́се, досто́йним служи́телям алтаря́ Ду́ха Пресвята́го, на освяще́ніє даро́в сходя́ща, показа́вий.","Ісу́се, вмі́сто недосто́йних служи́телей алтаря́ а́нгелов Твої́х неви́димо, для соверше́нія боже́ственнаго та́їнства, посила́яй;","Ісу́се, явле́нієм чуде́с на святі́й трапе́зі мно́гія із са́мих злові́рних к ві́рі обрати́вий.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 8","ps":["«І по хлі́бе», си́річ по вкуше́нії от по́даннаго Тобо́ю хлі́ба преда́телю, я́коже повіству́єть святи́й Іоа́нн, «вни́де в онь сатана́». О́ле, стра́шния ка́зні за неві́ріє! О́ле, злополу́чнаго жре́бія преда́теля! Є́же во спасе́ніє долженствова́ло би́ти, в смерть і поги́бель єму́ обрі́теся. Пред такови́м у́бо судо́м пра́вди Твоєя́ благогове́я, со стра́хом і тре́петом зову́ Ті: Аллилу́я."]},{"h":"Ікос 8","ps":["«Сіє́ творі́те в Моє́ воспомина́ніє», — рекл єси́ ученико́м на ве́чері, препода́в їм под ви́дом хлі́ба Ті́ло, а под ви́дом вина́ Кров Свою́. «Ті́мже у́бо єли́жди от хлі́ба яди́м і ча́ші піє́м, смерть Твою́ возвіща́єм», по сло́ву свята́го Па́вла. Воспомина́я у́бо ни́ні страда́нія Твоя́, со умиле́нієм зову́ Ті:","Ісу́се, в ру́ці враго́в Твої́х для спасе́нія ми́ра Себі́ проізво́льні преда́вий;","Ісу́се, легіо́ном а́нгелов в защи́ту Твою́ яви́тися не попусти́вий.","Ісу́се, неві́рнаго ученика́ воззрі́нієм на него́ і гла́сом але́ктора к покая́нію обрати́вий;","Ісу́се, Кая́фі і Пила́ту, неразу́мно вопроси́вшим Тя, отві́та не да́вий.","Ісу́се, со Креста́ распе́ншим Тя у Отця́ отпуще́ніє гріхо́в проси́вий;","Ісу́се, Ма́тері Твоє́й возлю́бленнаго ученика́ премилосе́рдне усинови́вий.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 9","ps":["«Іу́до, лобза́нієм ли Си́на Челові́чеськаго предає́ши?» — воззва́л єси́ го́рці к ученику́ неві́рному, єгда́ он приї́де со спи́рою во вертогра́д Гефсима́нський, іща́ преда́ти Тя лобза́нієм. Оба́че і сей прео́стрий глаго́л не порази́ раска́янієм душі́, во злі ожесточе́нния. Ві́дий у́бо непостоя́нство і моєя́ во́лі, страшу́ся, да не дам Ті когда́ і аз, неблагода́рний, лобза́нія Іу́дина. Ти Сам у́бо укріпи́ м'я благода́тію Твоє́ю, да со благоразу́мним разбо́йником ви́ну зову́: Аллилу́я."]},{"h":"Ікос 9","ps":["«О́тче, да всі єди́но бу́дуть, я́коже Ти во Мні і Аз в Тебі́, да і ті́ї в Нас єди́но бу́дуть, да і мир ві́ру і́меть, я́ко Аз от Тебе́ ізидо́х», — та́ко возгласи́л єси́ в послі́дней вели́кой моли́тві ко Отцю́. Сему́ пресла́дкому гла́су Твоєму́ послі́дуя і о си́лі моли́тви Твоєя́ дерза́я, с ві́рою возглаша́ю Ті:","Ісу́се, вся совокупля́яй во єди́но, возсоєдини́ всіх нас неразлу́чні с Тобо́ю і Отце́м Твої́м;","Ісу́се, вся примиря́яй, даждь, да бу́дем все єдиноми́сленни во ві́рі і любві́ к Тебі́.","Ісу́се, не терп'я́й вражди́ і разделе́ній, потреби́ злочести́вия є́ресі і раско́ли;","Ісу́се, всіх люб'я́й і ми́луяй, собери́ во єди́но ста́до вся заблу́дшия о́вці.","Ісу́се, мир всім подава́яй, утоли́ за́висть і преріка́нія между́ призива́ющими і́м'я Твоє́;","Ісу́се, причаща́яй м'я самаго́ Ті́ла і Кро́ві Твоєя́, да бу́ду воі́стину плоть от пло́ті Твоєя́ і кость от косте́й Твої́х.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 10","ps":["На ве́чері в Ка́ні Галиле́йстій, во́ду во вино́ претвори́в, пе́рвоє сим зна́меніє Боже́ственния си́ли Твоєя́ показа́л єси́. Отходя́ же на крест, я́ко Жени́х душ, послі́днєє чу́до любві́ ві́рующим в Тя яви́л єси́, претвори́в хліб в Ті́ло Твоє́ і вино́ в Кров Твою́, і́мже насища́яся і аз в живо́т ві́чний, благода́рні зову́ Ті: Аллилу́я."]},{"h":"Ікос 10","ps":["В день Воскресе́нія Твоєго́, двою́ от учени́к Твої́х спутеше́ствуя во о́бразі стра́нника во Еммау́с, поуча́л єси́ їх о та́йні страда́ній Твої́х: о́німа же держа́стася о́чі, да Тя не позна́ста, а́ще і се́рдце їх горя́ бі в них от сла́дости слове́с Твої́х. Єгда́ же прекло́нься на моле́ніє їх, вшел єси́ с ни́ми облещи́, і благослови́в хліб, по́дал єси́ їм: а́біє отверзо́стіся і́ма о́чі, да Тя позна́ста. Подо́б'ясь сим ученика́м, дерза́ю і аз со смире́нієм вознести́ к Тебі́ сицеви́й глас:","Ісу́се, долготерпіли́вий, не оста́ви і мене́ єди́наго на путі́ жи́зні за ску́дость ві́ри моєя́;","Ісу́се, научи́ м'я, я́коже і о́ніх, разумі́ти проро́чествія о Тебі́ і та́йну благода́тнаго соєдине́нія с Тобо́ю.","Ісу́се, согрі́й і воспламени́, я́коже і о́ніх ученико́в, і моє́ хла́дноє се́рдце;","Ісу́се преблаги́й, обля́зі і со мно́ю, я́ко уже́ преклони́лся єсть к ве́черу день моєя́ жи́зні.","Ісу́се, даждь мі позна́ти Тя воі́стину в настоя́щем преломле́нії та́їнственнаго хлі́ба і в питії́ от ча́ші;","Ісу́се, сотвори́, да і аз, позна́в си́лу любве́ Твоєя́, бу́ду провозве́стником о́ния для бра́тій мої́х.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 11","ps":["Побіжда́ющему обіща́л єси́ да́ти я́сти от дре́ва живо́тнаго, є́же єсть посреди́ рая́ Бо́жия, і от ма́нни сокрове́нния. К сему́ вкуше́нію на небесі́, да бу́деть мі приуготовле́нієм на землі́ причаще́ніє Ті́ла і Кро́ві Твоєя́, к нему́же аз, недосто́йний, ни́ні приступа́я, зову́: Аллилу́я."]},{"h":"Ікос 11","ps":["«Яди́й і пія́й недосто́йні, суд себі́ ясть і піє́ть, не разсужда́яй Ті́ла і Кро́ві Госпо́дні», — вразумля́єть приступа́ющих ко причаще́нію небоше́ственний Па́вел. Ті́мже і аз страшу́сь і трепе́щу своєго́ недосто́їнства, но да не надо́лзі удаля́яся Твоєго́ обще́нія, от ми́сленнаго во́лка звіроуловле́н бу́ду, прихожду́ к Тебі́ со гла́сом такови́м:","Ісу́се, прийми́ м'я, я́коже прия́л єси́ митаря́, блудни́цю і разбо́йника;","Ісу́се, не возгнуша́йся вни́ти под кров душі́ моєя́, а́ще і весь пуст і па́лся єсть.","Ісу́се, разве́рзі і моя́ душе́вния о́чі, я́коже разве́рзл єси́ слі́пу от рожде́нія;","Ісу́се, прорці́ і мні, я́коже о́ному разсла́бленному: возста́ни і ходи́.","Ісу́се, уста́ви ток нечи́стих пожела́ній душі́ моєя́, я́коже уста́вил єси́ то́ки жени́ кровоточи́вия;","Ісу́се, уврачу́й прока́зу душі́ і со́вісти моєя́.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 12","ps":["За́вистію дия́вола, усти́ змі́я глаго́лавшаго, весь род челові́чеський вкуше́нієм от плода́ запреще́ннаго рай погуби́ і сме́рті предаде́ся. Вкуше́нієм же от Пречи́стаго Ті́ла і Кро́ве Твоєя́, всі земноро́днії, па́ки ві́чния сподобля́ються жи́зні і восхо́дять на пе́рвоє достоя́ніє. Врачество́ бо от я́да змії́на і сі́м'я безсме́ртія єсть причаще́ніє животворя́щих Та́їн Твої́х. Ті́мже благода́рні зову́ Ті: Аллилу́я."]},{"h":"Ікос 12","ps":["Се пред сосу́дом с Боже́ственними Та́йнами Твої́ми предстою́, злих же помишле́ній мої́х не отступа́ю; єди́на всемогу́щая благода́ть Твоя́ ободря́єть і привлека́єть м'я. Ті́мже, поверга́я себ'я́ в бе́здну милосе́рдія Твоєго́, вопію́:","Ісу́се, призива́яй к поко́ю в Тебі́ всіх тружда́ющихся і обремене́нних, прийми́ і мене́, утружде́ннаго суєто́ю ми́ра;","Ісу́се, прише́дий призва́ти не пра́ведния, но грі́шния на покая́ніє, разріши́ і м'я от гріхо́в і страсте́й мої́х.","Ісу́се, ісціля́яй вся́кий неду́г і вся́кую я́зву, уврачу́й ра́ни і гноє́ніє душі́ моєя́;","Ісу́се, насища́яй а́лчущия, наси́ти м'я Ті́лом і Кро́вію Твоє́ю.","Ісу́се, воскреша́яй ме́ртвия, оживи́ м'я, уме́ршаго гріха́ми;","Ісу́се, побіди́телю а́да, ізвлеки́ м'я із че́люстей ду́ха зло́би.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 13","ps":["О, Пресла́дкий і Всеще́дрий Ісу́се! Ви́ну сходя́й, я́ко ма́нна с небесе́, для пита́нія душ і тіле́с на́ших в Та́їнстві Пречи́стаго Ті́ла і Кро́ві Твоєя́, сподо́би м'я неосужде́нно причасти́тися Боже́ственних Та́їн Твої́х, да ісціле́н, насище́н, освяще́н і обоже́н Тобо́ю на ві́ки, благода́рно зову́ Ті: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела Твоєго́ к прови́дцю Іса́її со у́глем горя́щим от алтаря́ небе́снаго посла́л єси́, во є́же очи́стити тім устні́ єго́, єгда́ ви́дів Тя, сідя́ща на престо́лі, о нечистоті́ своє́й сокруша́шеся; аз же, оскверне́нний душе́ю і ті́лом, ка́ко дерзну́ приступи́ти ко причаще́нію Боже́ственних Твої́х Та́їн, а́ще не Ти Сам очи́стиши м'я сви́ше? Ті́мже із глубини́ душі́ вопію́ Ті:","Ісу́се Всеблаги́й, косни́ся огне́м благода́ті Твоєя́ і мої́х нечи́стих усте́н;","Ісу́се, попали́ те́рніє мої́х мно́гих прегріше́ній.","Ісу́се, сози́жди во мні се́рдце чи́сто, і обнови́ во утро́бі моє́й дух пра́вий;","Ісу́се, ізведи́ із темни́ці страсте́й бі́дную ду́шу мою́.","Ісу́се, потреби́ во мні нечи́стия по́мисли і зла́я похоті́нія;","Ісу́се, напра́ви сла́бия стопи́ моя́ на путь за́повідей Твої́х.","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]},{"h":"Кондак 1","ps":["Ізбра́нний Женише́ душ і серде́ць, вочелові́ченієм Свої́м і сме́ртію на Кресті́, обручи́вий Себе́ на ві́ки весь род челові́ч, і да́вий нам в зало́г ві́чния жи́зні са́моє пречи́стоє Ті́ло і Кров Свою́, се по гла́су Твоєму́ і аз, недосто́йний, дерза́я прихожду́ к боже́ственной трапе́зі Твоє́й і, пораже́н вели́чієм єя́, вопію́:","Ісу́се, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки."]}],"notes":[]}];
export default D;
